--
-- Name: allocate_vehicle_fuel_period("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."allocate_vehicle_fuel_period"("p_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_period public.vehicle_fuel_consumption_periods%rowtype;
  v_total_basis numeric;
  v_allocated numeric;
  v_tolerance numeric := 0.05;
begin
  select * into v_period from public.vehicle_fuel_consumption_periods where id=p_period_id;
  if not found then raise exception 'Fuel consumption period not found'; end if;
  if v_period.applied_at is null then return; end if;

  if v_period.allocation_method = 'manual' then
    select coalesce(sum(allocated_fuel_liter),0) into v_allocated
    from public.work_result_vehicle_usage where consumption_period_id=p_period_id and status <> 'cancelled';
    if v_allocated > v_period.consumed_liter + v_tolerance then
      raise exception 'Manual allocation exceeds consumed fuel';
    end if;
  else
    update public.work_result_vehicle_usage
    set allocation_basis_value = case v_period.allocation_method
      when 'distance_km' then distance_km
      when 'working_hours' then working_hours
      when 'area_rai' then actual_area_rai
      when 'quantity' then actual_quantity
      else engine_hours end,
      allocation_method = v_period.allocation_method,
      updated_at = now()
    where consumption_period_id=p_period_id and status <> 'cancelled';

    select coalesce(sum(allocation_basis_value),0) into v_total_basis
    from public.work_result_vehicle_usage where consumption_period_id=p_period_id and status <> 'cancelled';
    if v_total_basis <= 0 then
      update public.vehicle_fuel_consumption_periods set unallocated_liter=consumed_liter, updated_at=now() where id=p_period_id;
      return;
    end if;

    update public.work_result_vehicle_usage
    set allocated_fuel_liter = round(v_period.consumed_liter * allocation_basis_value / v_total_basis,3),
        fuel_cost_amount = round(v_period.fuel_cost_amount * allocation_basis_value / v_total_basis,2),
        status = case when status='draft' then 'allocated' else status end,
        updated_at = now()
    where consumption_period_id=p_period_id and status <> 'cancelled';
  end if;

  select coalesce(sum(allocated_fuel_liter),0) into v_allocated
  from public.work_result_vehicle_usage where consumption_period_id=p_period_id and status <> 'cancelled';
  update public.vehicle_fuel_consumption_periods
  set unallocated_liter = greatest(consumed_liter-v_allocated,0),
      status = case when consumed_liter-v_allocated <= v_tolerance then 'allocated' else status end,
      updated_at=now()
  where id=p_period_id;

  update public.work_results r
  set actual_fuel_liter = x.liter,
      actual_fuel_cost = x.cost,
      updated_at = now()
  from (
    select work_result_id, sum(allocated_fuel_liter) liter, sum(fuel_cost_amount) cost
    from public.work_result_vehicle_usage
    where consumption_period_id=p_period_id and status <> 'cancelled'
    group by work_result_id
  ) x
  where r.id=x.work_result_id;

  update public.work_order_machines m
  set fuel_actual_liter=x.liter,
      fuel_cost_amount=x.cost,
      actual_hours=x.hours,
      updated_at=now()
  from (
    select work_order_id, vehicle_id, sum(allocated_fuel_liter) liter,
           sum(fuel_cost_amount) cost, sum(engine_hours) hours
    from public.work_result_vehicle_usage
    where consumption_period_id=p_period_id and status <> 'cancelled'
    group by work_order_id, vehicle_id
  ) x
  where m.work_order_id=x.work_order_id and m.vehicle_id=x.vehicle_id;
end;
$$;


