--
-- Name: approve_goods_issue("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_goods_issue"("p_issue_id" "uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."goods_issues"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_issue public.goods_issues%rowtype;
begin
  update public.goods_issues
  set status='approved',approved_by_profile_id=p_profile_id,approved_at=now(),updated_at=now()
  where id=p_issue_id and status in ('draft','pending_approval')
  returning * into v_issue;
  if not found then raise exception 'Issue % is not in an approvable status',p_issue_id; end if;
  return v_issue;
end;
$$;


