-- Name: approve_goods_return("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_goods_return"("p_return_id" "uuid", "p_profile_id" "uuid") RETURNS "public"."goods_returns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.goods_returns;
begin
  select * into v_row
  from public.goods_returns
  where id=p_return_id
  for update;
  if not found then raise exception 'GOODS_RETURN_NOT_FOUND'; end if;
  if v_row.status='approved' then
    perform public.validate_goods_return_integrity(p_return_id);
    return v_row;
  end if;
  if v_row.status not in ('draft','pending_approval') then
    raise exception 'INVALID_GOODS_RETURN_STATUS';
  end if;

  perform public.validate_goods_return_integrity(p_return_id);

  update public.goods_returns
  set status='approved',
      approved_by_profile_id=p_profile_id,
      approved_at=now(),
      updated_at=now()
  where id=p_return_id
  returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: payroll_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."payroll_periods" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "period_code" "text" NOT NULL,
    "period_name" "text",
    "start_date" "date",
    "end_date" "date",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "prepared_by_profile_id" "uuid",
    "prepared_at" timestamp with time zone,
    "calculated_by_profile_id" "uuid",
    "calculated_at" timestamp with time zone,
    "approved_by_profile_id" "uuid",
    "approved_at" timestamp with time zone,
    "closed_by_profile_id" "uuid",
    "closed_at" timestamp with time zone,
    "calculation_version" integer DEFAULT 1 NOT NULL,
    "configuration_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: approve_payroll_period("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."approve_payroll_period"("p_period_id" "uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."payroll_periods"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_period public.payroll_periods%rowtype;
begin
  if exists(
    select 1 from public.work_result_workers wrw
    join public.work_results wr on wr.id=wrw.work_result_id
    join public.payroll_periods p on p.id=p_period_id
    where wrw.work_date between p.start_date and p.end_date
      and wr.result_status not in ('verified','closed')
  ) then
    raise exception 'Payroll period contains work results that are not verified/closed';
  end if;

  update public.payroll_periods
  set status='approved',approved_by_profile_id=p_profile_id,approved_at=now(),updated_at=now()
  where id=p_period_id and status in ('calculated','reviewing')
  returning * into v_period;
  if not found then raise exception 'Payroll period % is not ready for approval',p_period_id; end if;

  update public.payroll_employee_summaries set status='approved',approved_at=now(),updated_at=now()
  where payroll_period_id=p_period_id;
  return v_period;
end;
$$;


--
-- Name: audit_fuel_control_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."audit_fuel_control_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  insert into public.audit_logs(action,module_name,table_name,record_id,old_value,new_value,changed_by,changed_at,entity_table,entity_id,note)
  values(
    tg_op,'fuel',tg_table_name,
    case when tg_op='DELETE' then old.id else new.id end,
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end,
    auth.uid(),now(),tg_table_name,
    (case when tg_op='DELETE' then old.id else new.id end)::text,
    'fuel control audit'
  );
  return case when tg_op='DELETE' then old else new end;
end;
$$;


--
-- Name: budget_fiscal_year_buddhist("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."budget_fiscal_year_buddhist"("p_fiscal_year" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v_year integer;
begin
  if p_fiscal_year is null or p_fiscal_year !~ '^\d{4}$' then return null; end if;
  v_year := p_fiscal_year::integer;
  if v_year < 2400 then v_year := v_year + 543; end if;
  return v_year;
end;
$_$;


--
-- Name: budget_numeric_condition_match(numeric, "text", numeric, numeric, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."budget_numeric_condition_match"("p_actual" numeric, "p_operator" "text", "p_value_from" numeric, "p_value_to" numeric, "p_value_json" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
select case p_operator
  when 'eq' then p_actual is not null and p_actual = p_value_from
  when 'neq' then p_actual is not null and p_actual <> p_value_from
  when 'gte' then p_actual is not null and p_actual >= p_value_from
  when 'lte' then p_actual is not null and p_actual <= p_value_from
  when 'between' then p_actual is not null and p_actual between p_value_from and p_value_to
  when 'in' then p_actual is not null and exists (select 1 from jsonb_array_elements_text(coalesce(p_value_json,'[]'::jsonb)) x where x.value::numeric = p_actual)
  when 'not_in' then p_actual is not null and not exists (select 1 from jsonb_array_elements_text(coalesce(p_value_json,'[]'::jsonb)) x where x.value::numeric = p_actual)
  when 'is_null' then p_actual is null
  when 'is_not_null' then p_actual is not null
  else false end;
$$;


--
-- Name: budget_rule_matches_block("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."budget_rule_matches_block"("p_rule_id" "uuid", "p_block_id" "uuid", "p_fiscal_year" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_rule public.budget_rate_rules%rowtype;
  v_block public.blocks%rowtype;
  v_condition public.budget_rate_rule_conditions%rowtype;
  v_age integer;
  v_size text;
  v_match boolean;
begin
  select * into v_rule from public.budget_rate_rules where id=p_rule_id;
  select * into v_block from public.blocks where id=p_block_id;
  if not found or v_rule.id is null or v_block.id is null then return false; end if;
  if v_rule.status in ('rejected','cancelled','inactive') or v_block.status <> 'active' then return false; end if;

  if exists(select 1 from public.budget_rate_rule_blocks rb where rb.rule_id=p_rule_id and rb.block_id=p_block_id and rb.is_included=false) then
    return false;
  end if;
  if exists(select 1 from public.budget_rate_rule_blocks rb where rb.rule_id=p_rule_id and rb.block_id=p_block_id and rb.is_included=true) then
    return true;
  end if;
  if v_rule.condition_mode='specific_blocks' then return false; end if;

  v_age := public.calculate_palm_age_for_budget_year(p_fiscal_year,v_block.planting_year);
  v_size := public.palm_size_for_budget_year(p_fiscal_year,v_block.planting_year);

  for v_condition in
    select * from public.budget_rate_rule_conditions where rule_id=p_rule_id and condition_scope='block' order by sort_order,id
  loop
    v_match := case v_condition.condition_key
      when 'planting_year' then public.budget_numeric_condition_match(v_block.planting_year,v_condition.operator,v_condition.value_from_numeric,v_condition.value_to_numeric,v_condition.value_json)
      when 'palm_age' then public.budget_numeric_condition_match(v_age,v_condition.operator,v_condition.value_from_numeric,v_condition.value_to_numeric,v_condition.value_json)
      when 'palm_size' then public.budget_text_condition_match(v_size,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'rspo_status' then public.budget_text_condition_match(v_block.rspo_status,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'ap_code' then public.budget_text_condition_match(v_block.ap_code,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'block_code' then public.budget_text_condition_match(v_block.block_code,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'productive_status' then public.budget_text_condition_match(v_block.productive_status,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'terrain_type' then public.budget_text_condition_match(v_block.terrain_type,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'estate_id' then public.budget_text_condition_match(v_block.estate_id::text,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'zone_id' then public.budget_text_condition_match(v_block.zone_id::text,v_condition.operator,v_condition.value_text,v_condition.value_json)
      when 'plot_id' then public.budget_text_condition_match(v_block.plot_id::text,v_condition.operator,v_condition.value_text,v_condition.value_json)
      else false end;
    if not coalesce(v_match,false) then return false; end if;
  end loop;
  return true;
end;
$$;


--
-- Name: budget_text_condition_match("text", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."budget_text_condition_match"("p_actual" "text", "p_operator" "text", "p_value_text" "text", "p_value_json" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
select case p_operator
  when 'eq' then coalesce(p_actual,'') = coalesce(p_value_text,'')
  when 'neq' then coalesce(p_actual,'') <> coalesce(p_value_text,'')
  when 'contains' then coalesce(p_actual,'') ilike '%' || coalesce(p_value_text,'') || '%'
  when 'in' then exists (select 1 from jsonb_array_elements_text(coalesce(p_value_json,'[]'::jsonb)) x where lower(trim(x.value)) = lower(trim(coalesce(p_actual,''))))
  when 'not_in' then not exists (select 1 from jsonb_array_elements_text(coalesce(p_value_json,'[]'::jsonb)) x where lower(trim(x.value)) = lower(trim(coalesce(p_actual,''))))
  when 'is_null' then nullif(trim(coalesce(p_actual,'')),'') is null
  when 'is_not_null' then nullif(trim(coalesce(p_actual,'')),'') is not null
  else false end;
$$;


--
-- Name: calculate_material_issue_quantity("uuid", numeric, "uuid", "uuid", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_material_issue_quantity"("p_material_id" "uuid", "p_required_quantity" numeric, "p_required_unit_id" "uuid", "p_issue_unit_id" "uuid", "p_allow_fraction" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_raw numeric;
  v_issue numeric;
  v_back numeric;
  v_rate numeric;
begin
  if p_required_quantity is null or p_required_quantity<0 then
    raise exception 'INVALID_REQUIRED_QUANTITY';
  end if;
  v_rate:=public.material_conversion_rate(p_material_id,p_required_unit_id,p_issue_unit_id);
  if v_rate is null then raise exception 'MATERIAL_UNIT_CONVERSION_NOT_CONFIGURED'; end if;
  v_raw:=round(p_required_quantity*v_rate,6);
  v_issue:=case when p_allow_fraction then v_raw else round(v_raw) end;
  v_back:=public.convert_material_quantity(p_material_id,v_issue,p_issue_unit_id,p_required_unit_id);
  return jsonb_build_object(
    'material_id',p_material_id,
    'required_quantity',p_required_quantity,
    'required_unit_id',p_required_unit_id,
    'issue_unit_id',p_issue_unit_id,
    'conversion_rate',v_rate,
    'raw_issue_quantity',v_raw,
    'issue_quantity',v_issue,
    'allow_fraction',p_allow_fraction,
    'converted_back_quantity',v_back,
    'rounding_difference',round(v_back-p_required_quantity,6)
  );
end;
$$;


--
-- Name: FUNCTION "calculate_material_issue_quantity"("p_material_id" "uuid", "p_required_quantity" numeric, "p_required_unit_id" "uuid", "p_issue_unit_id" "uuid", "p_allow_fraction" boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."calculate_material_issue_quantity"("p_material_id" "uuid", "p_required_quantity" numeric, "p_required_unit_id" "uuid", "p_issue_unit_id" "uuid", "p_allow_fraction" boolean) IS 'คำนวณหน่วยจ่ายและปัด .5 ขึ้น ต่ำกว่า .5 ลงเมื่อไม่อนุญาตเศษ พร้อมเก็บส่วนต่าง';


--
-- Name: calculate_palm_age_for_budget_year("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_palm_age_for_budget_year"("p_fiscal_year" "text", "p_planting_year" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_budget_year integer;
  v_planting_year integer;
begin
  if p_planting_year is null or p_planting_year <= 0 then return null; end if;
  v_budget_year := public.budget_fiscal_year_buddhist(p_fiscal_year);
  v_planting_year := case when p_planting_year < 2400 then p_planting_year + 543 else p_planting_year end;
  if v_budget_year is null or v_planting_year > v_budget_year then return null; end if;
  return v_budget_year - v_planting_year;
end;
$$;


--
-- Name: capture_core_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."capture_core_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid;
  entity_uuid uuid;
  old_json jsonb;
  new_json jsonb;
begin
  actor := auth.uid();
  old_json := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end;
  new_json := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end;
  entity_uuid := coalesce(
    case when tg_op in ('INSERT','UPDATE') then new.id else null end,
    case when tg_op in ('UPDATE','DELETE') then old.id else null end
  );

  insert into public.audit_logs(
    user_id,action,module_name,table_name,record_id,
    old_value,new_value,changed_by,changed_at,entity_table,entity_id
  ) values (
    actor,lower(tg_op),split_part(tg_table_name,'_',1),tg_table_name,entity_uuid,
    old_json,new_json,actor,now(),tg_table_name,entity_uuid::text
  );

  return coalesce(new,old);
end;
$$;


--
-- Name: cleanup_full_web_test_run("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_full_web_test_run"("p_run_code" "text" DEFAULT 'WEBTEST-2569'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prefix text:=p_run_code||'%';
  v_deleted jsonb;
begin
  perform set_config('app.allow_test_cleanup','true',true);
  perform public.cleanup_full_web_test_surveys(p_run_code);

  delete from public.payroll_periods where period_code like v_prefix;

  delete from public.fuel_requisitions
  where requisition_no like v_prefix
     or work_order_id in (select id from public.work_orders where work_order_no like v_prefix);

  delete from public.work_result_vehicle_usage
  where work_order_id in (select id from public.work_orders where work_order_no like v_prefix)
     or vehicle_id in (select id from public.vehicles where vehicle_code like v_prefix);

  delete from public.vehicle_fuel_consumption_periods
  where vehicle_id in (select id from public.vehicles where vehicle_code like v_prefix);

  delete from public.goods_issues
  where issue_no like v_prefix
     or work_order_id in (select id from public.work_orders where work_order_no like v_prefix);

  delete from public.stock_transactions
  where work_order_id in (select id from public.work_orders where work_order_no like v_prefix)
     or material_id in (select id from public.materials where material_code like v_prefix)
     or warehouse_id in (select id from public.warehouses where warehouse_code like v_prefix);

  delete from public.work_attendance
  where work_order_id in (select id from public.work_orders where work_order_no like v_prefix);

  delete from public.work_orders where work_order_no like v_prefix;

  delete from public.transport_source_records where record_key like v_prefix;
  delete from public.planned_work_items where note like p_run_code||'%';
  delete from public.annual_work_plans where plan_name like p_run_code||'%';
  delete from public.activity_performance_standards where standard_code like v_prefix;

  delete from public.fuel_tanks where tank_code like v_prefix;
  delete from public.vehicles where vehicle_code like v_prefix;

  delete from public.stock_balances
  where material_id in (select id from public.materials where material_code like v_prefix)
     or warehouse_id in (select id from public.warehouses where warehouse_code like v_prefix);
  delete from public.material_lots
  where material_id in (select id from public.materials where material_code like v_prefix)
     or lot_no like v_prefix;
  delete from public.materials where material_code like v_prefix;
  delete from public.warehouses where warehouse_code like v_prefix;

  delete from public.team_members where team_id in (select id from public.teams where team_code like v_prefix);
  delete from public.teams where team_code like v_prefix;
  update public.departments set manager_employee_id=null where department_code like v_prefix;
  delete from public.employees where employee_code like v_prefix;
  delete from public.departments where department_code like v_prefix;

  delete from public.system_test_runs where run_code=p_run_code;

  v_deleted:=jsonb_build_object('run_code',p_run_code,'status','cleaned','cleaned_at',now(),
                                 'survey_cleanup',true,'locked_payroll_cleanup',true);
  return v_deleted;
end;
$$;


--
-- Name: cleanup_full_web_test_surveys("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_full_web_test_surveys"("p_run_code" "text" DEFAULT 'WEBTEST-2569'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_response_count integer;
  v_template_count integer;
  v_attachment_count integer;
begin
  select count(*) into v_response_count from public.survey_responses where response_no like p_run_code||'%';
  select count(*) into v_template_count from public.survey_templates where template_code like p_run_code||'%';
  select count(*) into v_attachment_count from public.attachments
   where storage_path like 'web-test/'||lower(p_run_code)||'/%'
      or (module_name='survey' and entity_id in (select id::text from public.survey_responses where response_no like p_run_code||'%'));

  delete from public.survey_responses where response_no like p_run_code||'%';
  delete from public.attachments
   where storage_path like 'web-test/'||lower(p_run_code)||'/%'
      or (module_name='survey' and entity_table in ('survey_responses','survey_answers') and coalesce(file_name,'') like '[TEST]%');
  delete from public.survey_templates where template_code like p_run_code||'%';

  return jsonb_build_object('run_code',p_run_code,'responses_deleted',v_response_count,
                            'templates_deleted',v_template_count,'attachments_deleted',v_attachment_count);
end;
$$;


--
-- Name: clone_budget_rate_rule_set("uuid", "text", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."clone_budget_rate_rule_set"("p_source_rule_set_id" "uuid", "p_target_budget_year_id" "text", "p_target_name" "text", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source public.budget_rate_rule_sets%rowtype;
  v_target_year public.budget_years%rowtype;
  v_new_set_id uuid;
  v_version integer;
begin
  select * into v_source from public.budget_rate_rule_sets where id=p_source_rule_set_id;
  select * into v_target_year from public.budget_years where id=p_target_budget_year_id;
  if v_source.id is null then raise exception 'Source rule set not found'; end if;
  if v_target_year.id is null then raise exception 'Target budget year not found'; end if;
  select coalesce(max(version_no),0)+1 into v_version from public.budget_rate_rule_sets where budget_year_id=p_target_budget_year_id;
  insert into public.budget_rate_rule_sets(
    budget_year_id,fiscal_year,rule_set_code,rule_set_name,effective_from,effective_to,version_no,parent_rule_set_id,
    age_basis_month,age_basis_day,status,created_by_profile_id
  ) values(
    v_target_year.id,v_target_year.fiscal_year,'RULE-'||v_target_year.fiscal_year||'-V'||v_version,
    coalesce(nullif(p_target_name,''),'ชุดอัตรางบประมาณ '||v_target_year.fiscal_year),
    v_target_year.effective_from,v_target_year.effective_to,v_version,v_source.id,
    v_source.age_basis_month,v_source.age_basis_day,'draft',p_profile_id
  ) returning id into v_new_set_id;

  insert into public.budget_rate_rules(
    rule_set_id,copied_from_rule_id,source_budget_activity_rate_id,rule_code,rule_name,activity_id,
    activity_code_snapshot,activity_name_snapshot,rate_type,rate_dimension_key,unit_name,calculation_method,
    comparison_basis,condition_mode,condition_name,rate_current,rate_proposed,priority,needs_mapping,
    effective_from,effective_to,status,change_reason,note,source_payload,created_by_profile_id
  )
  select
    v_new_set_id,r.id,r.source_budget_activity_rate_id,r.rule_code,r.rule_name,r.activity_id,
    r.activity_code_snapshot,r.activity_name_snapshot,r.rate_type,r.rate_dimension_key,r.unit_name,r.calculation_method,
    r.comparison_basis,r.condition_mode,r.condition_name,coalesce(r.rate_approved,r.rate_proposed,r.rate_current),
    coalesce(r.rate_approved,r.rate_proposed,r.rate_current),r.priority,r.needs_mapping,
    v_target_year.effective_from,v_target_year.effective_to,'draft','คัดลอกจากปี '||v_source.fiscal_year,r.note,r.source_payload,p_profile_id
  from public.budget_rate_rules r where r.rule_set_id=p_source_rule_set_id and r.status not in ('rejected','cancelled','inactive');

  insert into public.budget_rate_rule_conditions(
    rule_id,condition_scope,condition_key,operator,value_text,value_from_numeric,value_to_numeric,
    value_from_date,value_to_date,value_json,display_value,sort_order
  )
  select nr.id,c.condition_scope,c.condition_key,c.operator,c.value_text,c.value_from_numeric,c.value_to_numeric,
    c.value_from_date,c.value_to_date,c.value_json,c.display_value,c.sort_order
  from public.budget_rate_rule_conditions c
  join public.budget_rate_rules nr on nr.rule_set_id=v_new_set_id and nr.copied_from_rule_id=c.rule_id;

  insert into public.budget_rate_rule_blocks(rule_id,block_id,is_included,override_rate,note)
  select nr.id,rb.block_id,rb.is_included,rb.override_rate,rb.note
  from public.budget_rate_rule_blocks rb
  join public.budget_rate_rules nr on nr.rule_set_id=v_new_set_id and nr.copied_from_rule_id=rb.rule_id;
  return v_new_set_id;
end;
$$;


--
-- Name: close_goods_issue_usage("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."close_goods_issue_usage"("p_issue_id" "uuid", "p_profile_id" "uuid") RETURNS "public"."goods_issues"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_issue public.goods_issues; r record; v_used numeric; v_returned numeric;
begin
  select * into v_issue from public.goods_issues where id=p_issue_id for update;
  if not found then raise exception 'GOODS_ISSUE_NOT_FOUND'; end if;
  if v_issue.status<>'posted' then raise exception 'GOODS_ISSUE_NOT_POSTED'; end if;
  if v_issue.usage_status='closed' then return v_issue; end if;
  for r in select * from public.goods_issue_lines where issue_id=p_issue_id loop
    select coalesce(sum(issue_unit_quantity),0) into v_used from public.goods_issue_daily_usage where goods_issue_line_id=r.id and status<>'cancelled';
    select coalesce(sum(public.convert_material_quantity(r.material_id,grl.quantity,grl.unit_id,r.unit_id)),0) into v_returned
    from public.goods_return_lines grl join public.goods_returns gr on gr.id=grl.return_id
    where grl.goods_issue_line_id=r.id and gr.status='posted';
    if abs(r.quantity-v_used-v_returned)>0.000001 then raise exception 'ISSUE_BALANCE_NOT_CLEARED'; end if;
  end loop;
  update public.goods_issues set usage_status='closed',usage_closed_at=now(),usage_closed_by_profile_id=p_profile_id,updated_at=now()
  where id=p_issue_id returning * into v_issue;
  return v_issue;
end;
$$;


--
-- Name: close_payroll_period("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."close_payroll_period"("p_period_id" "uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."payroll_periods"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_period public.payroll_periods%rowtype;
begin
  update public.payroll_periods
  set status='closed',closed_by_profile_id=p_profile_id,closed_at=now(),updated_at=now()
  where id=p_period_id and status='approved'
  returning * into v_period;
  if not found then raise exception 'Payroll period % must be approved before closing',p_period_id; end if;

  update public.payroll_employee_summaries set status='closed',closed_at=now(),updated_at=now()
  where payroll_period_id=p_period_id;
  update public.payroll_earning_lines e
  set status='closed',is_locked=true,locked_at=now()
  from public.payroll_employee_summaries s
  where s.id=e.payroll_summary_id and s.payroll_period_id=p_period_id;
  return v_period;
end;
$$;


--
-- Name: configure_goods_issue_period("uuid", "date", "date", boolean, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."configure_goods_issue_period"("p_issue_id" "uuid", "p_issue_start_date" "date", "p_issue_end_date" "date", "p_allow_multi_day" boolean, "p_profile_id" "uuid") RETURNS "public"."goods_issues"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_issue public.goods_issues;
begin
  if p_issue_start_date is null or p_issue_end_date is null
     or p_issue_start_date>p_issue_end_date then
    raise exception 'INVALID_ISSUE_PERIOD';
  end if;
  if not coalesce(p_allow_multi_day,false)
     and p_issue_start_date<>p_issue_end_date then
    raise exception 'INVALID_ISSUE_PERIOD';
  end if;

  select * into v_issue
  from public.goods_issues
  where id=p_issue_id
  for update;
  if not found then raise exception 'GOODS_ISSUE_NOT_FOUND'; end if;
  if v_issue.status not in ('draft','approved')
     and exists(
       select 1 from public.goods_issue_daily_usage
       where goods_issue_id=p_issue_id
     ) then
    raise exception 'GOODS_ISSUE_PERIOD_LOCKED';
  end if;

  update public.goods_issues
  set issue_start_date=p_issue_start_date,
      issue_end_date=p_issue_end_date,
      allow_multi_day=coalesce(p_allow_multi_day,false),
      updated_at=now()
  where id=p_issue_id
  returning * into v_issue;
  return v_issue;
end;
$$;


--
-- Name: convert_material_quantity("uuid", numeric, "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."convert_material_quantity"("p_material_id" "uuid", "p_quantity" numeric, "p_from_unit_id" "uuid", "p_to_unit_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare v_rate numeric;
begin
  if p_quantity is null then return null; end if;
  v_rate:=public.material_conversion_rate(p_material_id,p_from_unit_id,p_to_unit_id);
  if v_rate is null then
    raise exception 'MATERIAL_UNIT_CONVERSION_NOT_CONFIGURED';
  end if;
  return round(p_quantity*v_rate,6);
end;
$$;


--
-- Name: FUNCTION "convert_material_quantity"("p_material_id" "uuid", "p_quantity" numeric, "p_from_unit_id" "uuid", "p_to_unit_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."convert_material_quantity"("p_material_id" "uuid", "p_quantity" numeric, "p_from_unit_id" "uuid", "p_to_unit_id" "uuid") IS 'แปลงปริมาณวัสดุตาม SKU conversion ก่อนใช้ conversion กลาง';


--
-- Name: create_canonical_annual_work_plan(integer, "text", "uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_canonical_annual_work_plan"("p_plan_year" integer, "p_plan_name" "text", "p_actor_profile_id" "uuid", "p_request_key" "text", "p_estate_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_plan public.annual_work_plans%rowtype;
  v_request_key text := nullif(btrim(p_request_key), '');
  v_plan_name text := nullif(btrim(p_plan_name), '');
  v_note text := nullif(btrim(p_note), '');
  v_now timestamptz := transaction_timestamp();
begin
  if v_request_key is null or char_length(v_request_key) > 200 then
    raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_INVALID';
  end if;
  if p_plan_year is null or p_plan_year < 1 then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_YEAR_INVALID';
  end if;
  if v_plan_name is null then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_NAME_INVALID';
  end if;
  if p_actor_profile_id is null or not exists (
    select 1
    from public.profiles profile
    where profile.id = p_actor_profile_id
      and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select annual_plan.*
  into v_plan
  from public.annual_work_plans annual_plan
  where annual_plan.planning_request_key = v_request_key
  for key share;

  if found then
    if v_plan.source_type is distinct from 'canonical_budget'
      or v_plan.plan_year is distinct from p_plan_year
      or v_plan.plan_name is distinct from v_plan_name
      or v_plan.created_by is distinct from p_actor_profile_id
      or v_plan.estate_id is distinct from p_estate_id
      or v_plan.note is distinct from v_note
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_REUSED';
    end if;
    return jsonb_build_object('annual_work_plan', to_jsonb(v_plan), 'already_exists', true);
  end if;

  perform set_config('app.phase2c_plan_header_rpc', 'on', true);

  insert into public.annual_work_plans (
    plan_year,
    estate_id,
    plan_name,
    created_by,
    approved_by,
    status,
    created_at,
    approved_at,
    note,
    source_type,
    source_reference,
    is_default,
    updated_at,
    planning_request_key
  )
  values (
    p_plan_year,
    p_estate_id,
    v_plan_name,
    p_actor_profile_id,
    null,
    'draft',
    v_now,
    null,
    v_note,
    'canonical_budget',
    null,
    false,
    v_now,
    v_request_key
  )
  on conflict (planning_request_key)
    where planning_request_key is not null
  do nothing
  returning * into v_plan;

  if not found then
    select annual_plan.*
    into v_plan
    from public.annual_work_plans annual_plan
    where annual_plan.planning_request_key = v_request_key
    for key share;

    if not found
      or v_plan.source_type is distinct from 'canonical_budget'
      or v_plan.plan_year is distinct from p_plan_year
      or v_plan.plan_name is distinct from v_plan_name
      or v_plan.created_by is distinct from p_actor_profile_id
      or v_plan.estate_id is distinct from p_estate_id
      or v_plan.note is distinct from v_note
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_REUSED';
    end if;
    return jsonb_build_object('annual_work_plan', to_jsonb(v_plan), 'already_exists', true);
  end if;

  return jsonb_build_object('annual_work_plan', to_jsonb(v_plan), 'already_exists', false);
end
$$;


--
-- Name: FUNCTION "create_canonical_annual_work_plan"("p_plan_year" integer, "p_plan_name" "text", "p_actor_profile_id" "uuid", "p_request_key" "text", "p_estate_id" "uuid", "p_note" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."create_canonical_annual_work_plan"("p_plan_year" integer, "p_plan_name" "text", "p_actor_profile_id" "uuid", "p_request_key" "text", "p_estate_id" "uuid", "p_note" "text") IS 'Creates one draft canonical Annual Plan through a stable service-only request key.';


--
-- Name: create_canonical_planned_work_item_snapshot("uuid", "text", "text", "text", "uuid", "uuid", "text", "uuid", "uuid", "date", "date", "text", integer, integer, numeric, "text", numeric, "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_canonical_planned_work_item_snapshot"("p_annual_plan_id" "uuid", "p_budget_year_id" "text", "p_budget_activity_rate_id" "text", "p_budget_rate_block_id" "text", "p_block_id" "uuid", "p_activity_id" "uuid", "p_planning_request_key" "text", "p_actor_profile_id" "uuid", "p_plot_id" "uuid" DEFAULT NULL::"uuid", "p_planned_start_date" "date" DEFAULT NULL::"date", "p_planned_end_date" "date" DEFAULT NULL::"date", "p_recurrence_type" "text" DEFAULT NULL::"text", "p_recurrence_interval" integer DEFAULT NULL::integer, "p_repeat_after_last_done_days" integer DEFAULT NULL::integer, "p_target_quantity" numeric DEFAULT NULL::numeric, "p_target_unit" "text" DEFAULT NULL::"text", "p_planned_budget" numeric DEFAULT NULL::numeric, "p_suggested_team_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT 'planned'::"text", "p_note" "text" DEFAULT NULL::"text", "p_ap_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_item public.planned_work_items%rowtype;
  v_material_count integer := 0;
  v_request_key text := nullif(btrim(p_planning_request_key), '');
  v_snapshot_at timestamptz := transaction_timestamp();
  v_normalized_note text := nullif(btrim(p_note), '');
  v_normalized_status text := lower(nullif(btrim(p_status), ''));
  v_plan_year integer;
  v_plan_source_type text;
  v_plan_status text;
  v_budget_fiscal_year text;
begin
  if v_request_key is null then
    raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_REQUIRED';
  end if;
  if char_length(v_request_key) > 200 then
    raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_INVALID';
  end if;
  if v_normalized_status is distinct from 'planned' then
    raise exception using errcode = 'P0001', message = 'PLANNING_ITEM_STATUS_INVALID';
  end if;

  if p_actor_profile_id is null or not exists (
    select 1
    from public.profiles profile
    where profile.id = p_actor_profile_id
      and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select planned_item.*
  into v_item
  from public.planned_work_items planned_item
  where planned_item.planning_request_key = v_request_key
  for key share;

  if found then
    if v_item.source_type is distinct from 'canonical_budget'
      or v_item.annual_plan_id is distinct from p_annual_plan_id
      or v_item.source_budget_year_id is distinct from p_budget_year_id
      or v_item.source_budget_activity_rate_id is distinct from p_budget_activity_rate_id
      or v_item.source_budget_rate_block_id is distinct from p_budget_rate_block_id
      or v_item.block_id is distinct from p_block_id
      or v_item.activity_id is distinct from p_activity_id
      or v_item.plot_id is distinct from p_plot_id
      or v_item.planned_start_date is distinct from p_planned_start_date
      or v_item.planned_end_date is distinct from p_planned_end_date
      or v_item.recurrence_type is distinct from p_recurrence_type
      or v_item.recurrence_interval is distinct from p_recurrence_interval
      or v_item.repeat_after_last_done_days is distinct from p_repeat_after_last_done_days
      or v_item.target_quantity is distinct from p_target_quantity
      or v_item.target_unit is distinct from p_target_unit
      or v_item.planned_budget is distinct from p_planned_budget
      or v_item.suggested_team_id is distinct from p_suggested_team_id
      or v_item.status is distinct from 'planned'
      or v_item.note is distinct from v_normalized_note
      or v_item.ap_code is distinct from p_ap_code
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_REUSED';
    end if;

    select count(*)::integer
    into v_material_count
    from public.planned_work_materials material_snapshot
    where material_snapshot.planned_work_item_id = v_item.id
      and material_snapshot.snapshot_source_type = 'canonical_budget_block_material';

    return jsonb_build_object(
      'planned_work_item', to_jsonb(v_item),
      'material_count', v_material_count,
      'already_exists', true
    );
  end if;

  select annual_plan.plan_year, annual_plan.source_type, annual_plan.status
  into v_plan_year, v_plan_source_type, v_plan_status
  from public.annual_work_plans annual_plan
  where annual_plan.id = p_annual_plan_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;
  if v_plan_source_type is distinct from 'canonical_budget' then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_PLAN_REQUIRED';
  end if;
  if v_plan_status is distinct from 'draft' then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;

  select budget_year.fiscal_year
  into v_budget_fiscal_year
  from public.budget_years budget_year
  where budget_year.id = p_budget_year_id
  for share;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_YEAR_NOT_ELIGIBLE';
  end if;
  if nullif(btrim(v_budget_fiscal_year), '') is null
    or btrim(v_budget_fiscal_year) !~ '^[0-9]+$'
    or v_plan_year::text <> btrim(v_budget_fiscal_year)
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_YEAR_PLAN_MISMATCH';
  end if;

  perform set_config('app.phase2c_snapshot_rpc', 'on', true);

  insert into public.planned_work_items (
    annual_plan_id,
    plot_id,
    activity_id,
    planned_start_date,
    planned_end_date,
    recurrence_type,
    recurrence_interval,
    repeat_after_last_done_days,
    target_quantity,
    target_unit,
    planned_budget,
    suggested_team_id,
    status,
    note,
    block_id,
    ap_code,
    source_type,
    source_budget_year_id,
    source_budget_activity_rate_id,
    source_budget_rate_block_id,
    planning_request_key,
    created_at,
    updated_at
  )
  values (
    p_annual_plan_id,
    p_plot_id,
    p_activity_id,
    p_planned_start_date,
    p_planned_end_date,
    p_recurrence_type,
    p_recurrence_interval,
    p_repeat_after_last_done_days,
    p_target_quantity,
    p_target_unit,
    p_planned_budget,
    p_suggested_team_id,
    'planned',
    v_normalized_note,
    p_block_id,
    p_ap_code,
    'canonical_budget',
    p_budget_year_id,
    p_budget_activity_rate_id,
    p_budget_rate_block_id,
    v_request_key,
    v_snapshot_at,
    v_snapshot_at
  )
  on conflict (planning_request_key)
    where planning_request_key is not null
  do nothing
  returning * into v_item;

  if not found then
    select planned_item.*
    into v_item
    from public.planned_work_items planned_item
    where planned_item.planning_request_key = v_request_key
    for key share;

    if not found
      or v_item.source_type is distinct from 'canonical_budget'
      or v_item.annual_plan_id is distinct from p_annual_plan_id
      or v_item.source_budget_year_id is distinct from p_budget_year_id
      or v_item.source_budget_activity_rate_id is distinct from p_budget_activity_rate_id
      or v_item.source_budget_rate_block_id is distinct from p_budget_rate_block_id
      or v_item.block_id is distinct from p_block_id
      or v_item.activity_id is distinct from p_activity_id
      or v_item.plot_id is distinct from p_plot_id
      or v_item.planned_start_date is distinct from p_planned_start_date
      or v_item.planned_end_date is distinct from p_planned_end_date
      or v_item.recurrence_type is distinct from p_recurrence_type
      or v_item.recurrence_interval is distinct from p_recurrence_interval
      or v_item.repeat_after_last_done_days is distinct from p_repeat_after_last_done_days
      or v_item.target_quantity is distinct from p_target_quantity
      or v_item.target_unit is distinct from p_target_unit
      or v_item.planned_budget is distinct from p_planned_budget
      or v_item.suggested_team_id is distinct from p_suggested_team_id
      or v_item.status is distinct from 'planned'
      or v_item.note is distinct from v_normalized_note
      or v_item.ap_code is distinct from p_ap_code
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_REUSED';
    end if;

    select count(*)::integer
    into v_material_count
    from public.planned_work_materials material_snapshot
    where material_snapshot.planned_work_item_id = v_item.id
      and material_snapshot.snapshot_source_type = 'canonical_budget_block_material';

    return jsonb_build_object(
      'planned_work_item', to_jsonb(v_item),
      'material_count', v_material_count,
      'already_exists', true
    );
  end if;

  v_material_count := public.populate_canonical_planning_material_snapshot(
    v_item.id,
    p_budget_year_id,
    p_budget_activity_rate_id,
    p_budget_rate_block_id,
    p_block_id,
    p_activity_id,
    v_snapshot_at
  );

  return jsonb_build_object(
    'planned_work_item', to_jsonb(v_item),
    'material_count', v_material_count,
    'already_exists', false
  );
end
$_$;


--
-- Name: FUNCTION "create_canonical_planned_work_item_snapshot"("p_annual_plan_id" "uuid", "p_budget_year_id" "text", "p_budget_activity_rate_id" "text", "p_budget_rate_block_id" "text", "p_block_id" "uuid", "p_activity_id" "uuid", "p_planning_request_key" "text", "p_actor_profile_id" "uuid", "p_plot_id" "uuid", "p_planned_start_date" "date", "p_planned_end_date" "date", "p_recurrence_type" "text", "p_recurrence_interval" integer, "p_repeat_after_last_done_days" integer, "p_target_quantity" numeric, "p_target_unit" "text", "p_planned_budget" numeric, "p_suggested_team_id" "uuid", "p_status" "text", "p_note" "text", "p_ap_code" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."create_canonical_planned_work_item_snapshot"("p_annual_plan_id" "uuid", "p_budget_year_id" "text", "p_budget_activity_rate_id" "text", "p_budget_rate_block_id" "text", "p_block_id" "uuid", "p_activity_id" "uuid", "p_planning_request_key" "text", "p_actor_profile_id" "uuid", "p_plot_id" "uuid", "p_planned_start_date" "date", "p_planned_end_date" "date", "p_recurrence_type" "text", "p_recurrence_interval" integer, "p_repeat_after_last_done_days" integer, "p_target_quantity" numeric, "p_target_unit" "text", "p_planned_budget" numeric, "p_suggested_team_id" "uuid", "p_status" "text", "p_note" "text", "p_ap_code" "text") IS 'Creates one canonical Planned Item only under a draft canonical Annual Plan and snapshots its Materials atomically.';


--
-- Name: create_full_web_test_run("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_full_web_test_run"("p_run_code" "text" DEFAULT 'WEBTEST-2569'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_budget_year_id text;
  v_department_id uuid;
  v_team_id uuid;
  v_supervisor_id uuid;
  v_employee_ids uuid[];
  v_warehouse_id uuid;
  v_material_id uuid;
  v_lot_id uuid;
  v_unit_sack uuid;
  v_vehicle_id uuid;
  v_tank_id uuid;
  v_plan_id uuid;
  v_block_fert uuid;
  v_block_harvest uuid;
  v_block_grass uuid;
  v_act_fert uuid;
  v_act_harvest uuid;
  v_act_grass uuid;
  v_item_fert uuid;
  v_item_harvest uuid;
  v_item_grass_draft uuid;
  v_item_grass_ready uuid;
  v_wo_fert uuid;
  v_wo_harvest uuid;
  v_wo_grass_draft uuid;
  v_wo_grass_ready uuid;
  v_result_fert public.work_results%rowtype;
  v_result_harvest public.work_results%rowtype;
  v_result_grass public.work_results%rowtype;
  v_transport_1 uuid;
  v_transport_2 uuid;
  v_fuel_req uuid;
  v_fuel_period uuid;
  v_goods_issue uuid;
  v_payroll_closed uuid;
  v_payroll_review uuid;
  v_d1 date := current_date - 2;
  v_d2 date := current_date - 1;
  v_d3 date := current_date;
  v_d4 date := current_date + 1;
  v_t1_start timestamptz;
  v_t1_end timestamptz;
  v_t2_start timestamptz;
  v_t2_end timestamptz;
  v_t3_start timestamptz;
  v_t3_end timestamptz;
  v_metadata jsonb;
begin
  perform public.cleanup_full_web_test_run(p_run_code);

  insert into public.system_test_runs(run_code,run_name,status)
  values(p_run_code,'ชุดจำลองเต็มระบบสำหรับทดสอบ Web','building')
  returning id into v_run_id;

  v_t1_start := (v_d1::text || ' 08:00:00+07')::timestamptz;
  v_t1_end   := (v_d1::text || ' 14:00:00+07')::timestamptz;
  v_t2_start := (v_d2::text || ' 08:00:00+07')::timestamptz;
  v_t2_end   := (v_d2::text || ' 11:00:00+07')::timestamptz;
  v_t3_start := (v_d3::text || ' 08:00:00+07')::timestamptz;
  v_t3_end   := (v_d3::text || ' 12:00:00+07')::timestamptz;

  select id into v_budget_year_id from public.budget_years where fiscal_year='2569' order by created_at limit 1;
  select id into v_unit_sack from public.units where unit_name='กระสอบ' order by case when unit_code='U-7119AF71' then 0 else 1 end limit 1;
  select id into v_block_fert from public.blocks where block_name='63-A01-R' and status='active' limit 1;
  select id into v_block_harvest from public.blocks where block_name='56-A02' and status='active' limit 1;
  select id into v_block_grass from public.blocks where block_name='56-A03-R' and status='active' limit 1;
  select id into v_act_fert from public.activities where activity_code='MN02' limit 1;
  select id into v_act_harvest from public.activities where activity_code='HV01' limit 1;
  select id into v_act_grass from public.activities where activity_code='WE03' limit 1;

  if v_unit_sack is null or v_block_fert is null or v_block_harvest is null or v_block_grass is null
     or v_act_fert is null or v_act_harvest is null or v_act_grass is null then
    raise exception 'Required master data for WEBTEST is incomplete';
  end if;

  insert into public.departments(department_code,department_name,cost_center_code,status,note)
  values(p_run_code||'-DEPT','[TEST] ฝ่ายปฏิบัติการสวน','WEBTEST','active',p_run_code||' ข้อมูลจำลอง')
  returning id into v_department_id;

  insert into public.employees(
    employee_code,full_name,nickname,nationality,employee_type,position,default_role,
    daily_wage,normal_hours_per_day,worker_type,payment_type,
    department_id,status,start_date,effective_from,change_reason
  ) values
    (p_run_code||'-E01','[TEST] สมชาย หัวหน้าทีม','หัวหน้าทดสอบ','Thai','daily','หัวหน้างาน','supervisor',480,8,'daily','daily',v_department_id,'active',v_d1-30,v_d1-30,p_run_code),
    (p_run_code||'-E02','[TEST] คนงาน ทดสอบ 1','ทดสอบ1','Myanmar','daily','คนงาน','worker',400,8,'daily','daily',v_department_id,'active',v_d1-30,v_d1-30,p_run_code),
    (p_run_code||'-E03','[TEST] คนงาน ทดสอบ 2','ทดสอบ2','Myanmar','daily','คนงาน','worker',400,8,'daily','daily',v_department_id,'active',v_d1-30,v_d1-30,p_run_code),
    (p_run_code||'-E04','[TEST] คนงาน ทดสอบ 3','ทดสอบ3','Myanmar','daily','คนงาน','worker',400,8,'daily','daily',v_department_id,'active',v_d1-30,v_d1-30,p_run_code),
    (p_run_code||'-E05','[TEST] คนงาน ทดสอบ 4','ทดสอบ4','Myanmar','daily','คนงาน','worker',400,8,'daily','daily',v_department_id,'active',v_d1-30,v_d1-30,p_run_code);

  select id into v_supervisor_id from public.employees where employee_code=p_run_code||'-E01';
  select array_agg(id order by employee_code) into v_employee_ids from public.employees where employee_code like p_run_code||'-E%';
  update public.departments set manager_employee_id=v_supervisor_id where id=v_department_id;

  insert into public.teams(team_code,team_name,team_type,supervisor_employee_id,status)
  values(p_run_code||'-T01','[TEST] ทีมปฏิบัติการเต็มระบบ','internal',v_supervisor_id,'active')
  returning id into v_team_id;

  insert into public.team_members(team_id,employee_id,member_role,start_date,is_active)
  select v_team_id,e.id,case when e.id=v_supervisor_id then 'supervisor' else 'worker' end,v_d1-30,true
  from public.employees e where e.employee_code like p_run_code||'-E%';

  insert into public.warehouses(warehouse_code,warehouse_name,status,keeper_employee_id)
  values(p_run_code||'-WH01','[TEST] คลังกลางจำลอง','active',v_supervisor_id)
  returning id into v_warehouse_id;

  insert into public.materials(material_code,material_name,base_unit_id,status)
  values(p_run_code||'-MAT-FERT50','[TEST] ปุ๋ยสูตร 15-15-15 ขนาด 50 กก.',v_unit_sack,'active')
  returning id into v_material_id;

  insert into public.material_lots(material_id,lot_no,received_quantity,remaining_quantity,status)
  values(v_material_id,p_run_code||'-LOT-001',100,100,'active')
  returning id into v_lot_id;

  insert into public.stock_balances(warehouse_id,material_id,material_lot_id,quantity_on_hand,unit_id,last_count_date)
  values(v_warehouse_id,v_material_id,v_lot_id,100,v_unit_sack,v_d1-5);

  insert into public.stock_transactions(material_id,warehouse_id,transaction_type,quantity,quantity_in,quantity_out,unit_cost,unit_id,transaction_date,status)
  values(v_material_id,v_warehouse_id,'opening',100,100,0,850,v_unit_sack,v_d1-5,'posted');

  insert into public.vehicles(
    vehicle_code,vehicle_name,vehicle_type,plate_no,default_driver_id,status,note,
    fuel_type,tank_capacity_liter,minimum_fuel_liter,reorder_point_liter,safety_stock_liter,
    target_fill_percent,minimum_operating_percent,fuel_measurement_basis,standard_liter_per_hour,
    requires_hour_meter,requires_odometer
  ) values(
    p_run_code||'-VEH01','[TEST] รถไถจำลองเต็มระบบ','รถไถ','TEST-01',v_supervisor_id,'active',p_run_code,
    'diesel',120,15,30,20,90,10,'engine_hours',2,true,false
  ) returning id into v_vehicle_id;

  insert into public.vehicle_fuel_balances(vehicle_id,fuel_type,current_estimated_liter,average_unit_cost,last_hour_meter)
  values(v_vehicle_id,'diesel',20,34,1000);

  insert into public.fuel_tanks(
    tank_code,tank_name,warehouse_id,capacity_liter,status,fuel_type,current_balance_liter,
    current_unit_cost,reorder_point_liter,safety_stock_liter,target_fill_percent
  ) values(
    p_run_code||'-TANK01','[TEST] ถังดีเซลกลาง',v_warehouse_id,2000,'active','diesel',800,34,300,200,90
  ) returning id into v_tank_id;

  insert into public.activity_performance_standards(
    activity_id,budget_year_id,standard_code,standard_name,condition_group,output_unit,
    standard_per_person,standard_per_tree,standard_per_rai,standard_per_hour,
    person_weight_pct,tree_weight_pct,area_weight_pct,time_weight_pct,quality_weight_pct,
    efficiency_floor_pct,efficiency_ceiling_pct,minimum_sample_count,minimum_employee_count,
    minimum_team_count,minimum_block_count,minimum_data_quality_pct,effective_from,status,approved_at,note
  ) values
    (v_act_fert,null,p_run_code||'-STD-MN02','[TEST] มาตรฐานใส่ปุ๋ย','default','กระสอบ',4,0.0375,0.833,0.5,40,15,20,5,20,70,125,1,1,1,1,70,v_d1-365,'approved',now(),p_run_code),
    (v_act_harvest,null,p_run_code||'-STD-HV01','[TEST] มาตรฐานตัดปาล์ม','default','กก.',4450,5.8,145.4,556.25,40,15,20,5,20,70,125,1,1,1,1,70,v_d1-365,'approved',now(),p_run_code),
    (v_act_grass,null,p_run_code||'-STD-WE03','[TEST] มาตรฐานตัดหญ้า','default','ไร่',6,null,2,0.75,50,0,25,5,20,70,125,1,1,1,1,70,v_d1-365,'approved',now(),p_run_code);

  insert into public.annual_work_plans(plan_year,plan_name,status,approved_at,note)
  values(2569,p_run_code||' แผนจำลองเต็มระบบ','approved',now(),p_run_code)
  returning id into v_plan_id;

  insert into public.planned_work_items(
    annual_plan_id,block_id,activity_id,planned_start_date,planned_end_date,target_quantity,target_unit,
    planned_budget,suggested_team_id,status,note,source_type
  ) values(v_plan_id,v_block_fert,v_act_fert,v_d1,v_d1,20,'กระสอบ',17000,v_team_id,'planned',p_run_code||' ใส่ปุ๋ย','web_test')
  returning id into v_item_fert;

  insert into public.planned_work_items(
    annual_plan_id,block_id,activity_id,planned_start_date,planned_end_date,target_quantity,target_unit,
    planned_budget,suggested_team_id,status,note,source_type
  ) values(v_plan_id,v_block_harvest,v_act_harvest,v_d2,v_d2,22.25,'ตัน',11681.25,v_team_id,'planned',p_run_code||' ตัดปาล์มเชื่อมใบชั่ง','web_test')
  returning id into v_item_harvest;

  insert into public.planned_work_items(
    annual_plan_id,block_id,activity_id,planned_start_date,planned_end_date,target_quantity,target_unit,
    planned_budget,suggested_team_id,status,note,source_type
  ) values(v_plan_id,v_block_grass,v_act_grass,v_d3,v_d3,30,'ไร่',3000,v_team_id,'planned',p_run_code||' ตัดหญ้ากำลังทำ','web_test')
  returning id into v_item_grass_draft;

  insert into public.planned_work_items(
    annual_plan_id,block_id,activity_id,planned_start_date,planned_end_date,target_quantity,target_unit,
    planned_budget,suggested_team_id,status,note,source_type
  ) values(v_plan_id,v_block_fert,v_act_grass,v_d4,v_d4,24,'ไร่',2400,v_team_id,'planned',p_run_code||' ตัดหญ้ารอสั่งงาน','web_test')
  returning id into v_item_grass_ready;

  insert into public.work_orders(
    work_order_no,planned_work_item_id,block_id,activity_id,scheduled_date,supervisor_employee_id,
    team_id,status,planned_quantity,planned_unit,planned_labor_cost,planned_material_cost,
    planned_fuel_cost,planned_machine_cost,planned_total_cost,note,approved_at,dispatched_at,closed_at
  ) values(
    p_run_code||'-WO-FERT-001',v_item_fert,v_block_fert,v_act_fert,v_d1,v_supervisor_id,
    v_team_id,'in_progress',20,'กระสอบ',480,17000,612,600,18692,p_run_code||' งานปิดครบวงจร',now(),now(),now()
  ) returning id into v_wo_fert;

  insert into public.work_orders(
    work_order_no,planned_work_item_id,block_id,activity_id,scheduled_date,supervisor_employee_id,
    team_id,status,planned_quantity,planned_unit,planned_labor_cost,planned_material_cost,
    planned_fuel_cost,planned_machine_cost,planned_total_cost,note,approved_at,dispatched_at
  ) values(
    p_run_code||'-WO-HARV-001',v_item_harvest,v_block_harvest,v_act_harvest,v_d2,v_supervisor_id,
    v_team_id,'in_progress',22.25,'ตัน',11681.25,0,306,300,12287.25,p_run_code||' งานเชื่อมใบชั่ง',now(),now()
  ) returning id into v_wo_harvest;

  insert into public.work_orders(
    work_order_no,planned_work_item_id,block_id,activity_id,scheduled_date,supervisor_employee_id,
    team_id,status,planned_quantity,planned_unit,planned_labor_cost,planned_total_cost,note,approved_at,dispatched_at
  ) values(
    p_run_code||'-WO-GRASS-DRAFT',v_item_grass_draft,v_block_grass,v_act_grass,v_d3,v_supervisor_id,
    v_team_id,'in_progress',30,'ไร่',3000,3000,p_run_code||' มีบันทึก Draft',now(),now()
  ) returning id into v_wo_grass_draft;

  insert into public.work_orders(
    work_order_no,planned_work_item_id,block_id,activity_id,scheduled_date,supervisor_employee_id,
    team_id,status,planned_quantity,planned_unit,planned_labor_cost,planned_total_cost,note,approved_at
  ) values(
    p_run_code||'-WO-GRASS-READY',v_item_grass_ready,v_block_fert,v_act_grass,v_d4,v_supervisor_id,
    v_team_id,'approved',24,'ไร่',2400,2400,p_run_code||' รอแจกจ่ายงาน',now()
  ) returning id into v_wo_grass_ready;

  insert into public.work_order_materials(work_order_id,material_id,planned_quantity,unit_id,status,note)
  values(v_wo_fert,v_material_id,20,v_unit_sack,'planned',p_run_code);

  insert into public.work_order_machines(
    work_order_id,vehicle_id,driver_employee_id,planned_hours,fuel_plan_liter,status,start_hour_meter
  ) values
    (v_wo_fert,v_vehicle_id,v_supervisor_id,6,12,'assigned',1000),
    (v_wo_harvest,v_vehicle_id,v_supervisor_id,3,6,'assigned',1006);

  select id into v_goods_issue from public.prepare_goods_issue_from_work_order(v_wo_fert,v_warehouse_id,null);
  perform public.approve_goods_issue(v_goods_issue,null);
  perform public.post_goods_issue(v_goods_issue,null);

  insert into public.fuel_requisitions(
    requisition_no,work_order_id,vehicle_id,source_tank_id,requested_liter,requested_by,status,
    requested_for_date,request_source,reason,current_vehicle_fuel_liter,projected_usage_liter,
    projected_balance_liter,safety_stock_liter_snapshot,target_balance_liter,recommended_liter,
    approved_liter,approved_at
  ) values(
    p_run_code||'-FREQ-001',v_wo_fert,v_vehicle_id,v_tank_id,60,v_supervisor_id,'approved',
    v_d1,'manual',p_run_code||' เติมก่อนเริ่มชุดงาน',20,18,2,20,80,60,60,now()
  ) returning id into v_fuel_req;

  insert into public.fuel_issues(
    fuel_requisition_id,issue_no,tank_id,issued_liter,issued_by,status,vehicle_id,work_order_id,
    issue_at,fuel_type,driver_employee_id,note
  ) values(
    v_fuel_req,p_run_code||'-FISS-001',v_tank_id,60,v_supervisor_id,'issued',v_vehicle_id,v_wo_fert,
    (v_d1::text||' 07:30:00+07')::timestamptz,'diesel',v_supervisor_id,p_run_code
  );

  select * into v_result_fert from public.get_or_create_work_result(v_wo_fert,v_d1,null);
  update public.work_results set
    result_no=p_run_code||'-RES-FERT-001',actual_start_at=v_t1_start,actual_end_at=v_t1_end,
    actual_quantity=20,actual_unit='กระสอบ',result_status='closed',source_type='manual',
    actual_area_rai=24,actual_tree_count=534,worker_count=5,total_labor_hours=40,total_labor_days=5,
    working_minutes=360,stoppage_minutes=30,completion_pct=100,quality_score=96,data_quality_pct=100,
    weather_condition='แดดสลับเมฆ',terrain_condition='ปกติ',condition_group='default',submitted_at=now(),verified_at=now(),closed_at=now(),note=p_run_code
  where id=v_result_fert.id;
  update public.work_orders set status='closed',closed_at=now() where id=v_wo_fert;

  update public.work_result_workers set
    work_date=v_d1,actual_hours=8,actual_quantity=4,actual_unit='กระสอบ',rate_type='piece_rate',
    rate_amount=24,earning_amount=96,actual_area_rai=4.8,actual_tree_count=107,
    individual_quality_pct=96,individual_completion_pct=100,quantity_allocation_method='equal',is_quantity_estimated=false,note=p_run_code
  where work_result_id=v_result_fert.id;

  insert into public.work_attendance(work_order_id,employee_id,team_id,check_in_at,check_out_at,attendance_status,note)
  select v_wo_fert,e.id,v_team_id,v_t1_start,v_t1_end,'present',p_run_code
  from public.employees e where e.employee_code like p_run_code||'-E%';

  select * into v_result_harvest from public.get_or_create_work_result(v_wo_harvest,v_d2,null);
  update public.work_results set
    result_no=p_run_code||'-RES-HARV-001',actual_start_at=v_t2_start,actual_end_at=v_t2_end,
    actual_quantity=0,actual_unit='กก.',result_status='verified',source_type='weigh_ticket',
    actual_area_rai=153,actual_tree_count=3835,worker_count=5,total_labor_hours=40,total_labor_days=5,
    working_minutes=180,stoppage_minutes=15,completion_pct=100,quality_score=92,data_quality_pct=100,
    weather_condition='แดด',terrain_condition='ปกติ',condition_group='default',submitted_at=now(),verified_at=now(),note=p_run_code
  where id=v_result_harvest.id;

  update public.work_result_workers set
    work_date=v_d2,actual_hours=8,actual_quantity=4450,actual_unit='กก.',rate_type='piece_rate',
    rate_amount=0.525,earning_amount=2336.25,actual_area_rai=30.6,actual_tree_count=767,
    individual_quality_pct=92,individual_completion_pct=100,quantity_allocation_method='equal',is_quantity_estimated=false,note=p_run_code
  where work_result_id=v_result_harvest.id;

  insert into public.work_attendance(work_order_id,employee_id,team_id,check_in_at,check_out_at,attendance_status,note)
  select v_wo_harvest,e.id,v_team_id,v_t2_start,v_t2_end,'present',p_run_code
  from public.employees e where e.employee_code like p_run_code||'-E%';

  insert into public.transport_source_records(
    record_key,sync_key,source_row,doc_no,in_out_type,doc_date,car_license,yard,standard,
    area_group,supplier_code,supplier_name,source_area_key,net_weight,factory_net_weight,raw_payload
  ) values(
    p_run_code||'-WT-001',p_run_code||'-WT-001',1,p_run_code||'-WT-001','I',v_d2,'TEST-01','ปลายราง','RSPO',
    'คีรีรัฐ','WEBTEST','[TEST] ผลผลิตแปลง 56-A02','56-A02',12500,0,jsonb_build_object('test_run',p_run_code)
  ) returning id into v_transport_1;

  insert into public.transport_source_records(
    record_key,sync_key,source_row,doc_no,in_out_type,doc_date,car_license,yard,standard,
    area_group,supplier_code,supplier_name,source_area_key,net_weight,factory_net_weight,raw_payload
  ) values(
    p_run_code||'-WT-002',p_run_code||'-WT-002',2,p_run_code||'-WT-002','I',v_d2,'TEST-01','ปลายราง','RSPO',
    'คีรีรัฐ','WEBTEST','[TEST] ผลผลิตแปลง 56-A02','56-A02',9750,0,jsonb_build_object('test_run',p_run_code)
  ) returning id into v_transport_2;

  insert into public.work_result_weight_tickets(
    work_result_id,transport_source_record_id,allocated_weight_kg,allocation_percent,allocation_method,
    source_doc_no,source_doc_date,supplier_code,supplier_name,source_area_key,standard,yard,
    source_net_weight_kg,link_status,verified_at,note
  ) values
    (v_result_harvest.id,v_transport_1,12500,100,'manual',p_run_code||'-WT-001',v_d2,'WEBTEST','[TEST] ผลผลิตแปลง 56-A02','56-A02','RSPO','ปลายราง',12500,'verified',now(),p_run_code),
    (v_result_harvest.id,v_transport_2,9750,100,'manual',p_run_code||'-WT-002',v_d2,'WEBTEST','[TEST] ผลผลิตแปลง 56-A02','56-A02','RSPO','ปลายราง',9750,'verified',now(),p_run_code);

  select * into v_result_grass from public.get_or_create_work_result(v_wo_grass_draft,v_d3,null);
  update public.work_results set
    result_no=p_run_code||'-RES-GRASS-DRAFT',actual_start_at=v_t3_start,actual_end_at=v_t3_end,
    actual_quantity=12,actual_unit='ไร่',result_status='draft',source_type='manual',
    actual_area_rai=12,actual_tree_count=0,worker_count=5,total_labor_hours=20,total_labor_days=2.5,
    working_minutes=240,stoppage_minutes=20,completion_pct=40,data_quality_pct=80,
    weather_condition='ฝนเล็กน้อย',terrain_condition='ชื้น',condition_group='default',note=p_run_code||' รอส่งตรวจ'
  where id=v_result_grass.id;

  update public.work_result_workers set
    work_date=v_d3,actual_hours=4,actual_quantity=2.4,actual_unit='ไร่',rate_type='piece_rate',
    rate_amount=100,earning_amount=240,actual_area_rai=2.4,individual_completion_pct=40,
    quantity_allocation_method='equal',is_quantity_estimated=false,note=p_run_code
  where work_result_id=v_result_grass.id;

  insert into public.vehicle_fuel_consumption_periods(
    vehicle_id,period_start_at,opening_balance_liter,allocation_method,status,note
  ) values(
    v_vehicle_id,(v_d1::text||' 07:00:00+07')::timestamptz,20,'engine_hours','draft',p_run_code
  ) returning id into v_fuel_period;

  insert into public.work_result_vehicle_usage(
    work_result_id,work_order_id,vehicle_id,consumption_period_id,driver_employee_id,start_at,end_at,
    start_hour_meter,end_hour_meter,actual_area_rai,actual_tree_count,actual_quantity,actual_unit,
    allocation_method,status,note
  ) values
    (v_result_fert.id,v_wo_fert,v_vehicle_id,v_fuel_period,v_supervisor_id,v_t1_start,v_t1_end,1000,1006,24,534,20,'กระสอบ','engine_hours','draft',p_run_code),
    (v_result_harvest.id,v_wo_harvest,v_vehicle_id,v_fuel_period,v_supervisor_id,v_t2_start,v_t2_end,1006,1009,153,3835,22.25,'ตัน','engine_hours','draft',p_run_code);

  update public.vehicle_fuel_consumption_periods set
    period_end_at=(v_d2::text||' 12:00:00+07')::timestamptz,
    closing_balance_liter=62,status='closed'
  where id=v_fuel_period;

  perform public.recalculate_work_performance(v_result_fert.id);
  perform public.recalculate_work_performance(v_result_harvest.id);
  perform public.recalculate_work_performance(v_result_grass.id);

  insert into public.payroll_periods(period_code,period_name,start_date,end_date,status,configuration_json)
  values(p_run_code||'-PAY-CLOSED','[TEST] งวดปิดแล้ว',v_d1,v_d1,'open',jsonb_build_object('test_run',p_run_code))
  returning id into v_payroll_closed;
  perform public.prepare_payroll_period(v_payroll_closed,null);
  perform public.approve_payroll_period(v_payroll_closed,null);
  perform public.close_payroll_period(v_payroll_closed,null);

  insert into public.payroll_periods(period_code,period_name,start_date,end_date,status,configuration_json)
  values(p_run_code||'-PAY-REVIEW','[TEST] งวดรอตรวจสอบ',v_d2,v_d2,'open',jsonb_build_object('test_run',p_run_code))
  returning id into v_payroll_review;
  perform public.prepare_payroll_period(v_payroll_review,null);
  perform public.sync_web_test_legacy_payroll_lines(p_run_code);

  v_metadata := jsonb_build_object(
    'run_code',p_run_code,
    'date_from',v_d1,'date_to',v_d4,
    'department_id',v_department_id,'team_id',v_team_id,'employee_ids',to_jsonb(v_employee_ids),
    'warehouse_id',v_warehouse_id,'material_id',v_material_id,'vehicle_id',v_vehicle_id,'fuel_tank_id',v_tank_id,
    'plan_id',v_plan_id,
    'work_orders',jsonb_build_array(v_wo_fert,v_wo_harvest,v_wo_grass_draft,v_wo_grass_ready),
    'work_results',jsonb_build_array(v_result_fert.id,v_result_harvest.id,v_result_grass.id),
    'payroll_periods',jsonb_build_array(v_payroll_closed,v_payroll_review),
    'scenarios',jsonb_build_array(
      jsonb_build_object('code',p_run_code||'-WO-FERT-001','status','closed','coverage','inventory,fuel,performance,payroll'),
      jsonb_build_object('code',p_run_code||'-WO-HARV-001','status','in_progress','coverage','weigh_tickets,performance,payroll_review'),
      jsonb_build_object('code',p_run_code||'-WO-GRASS-DRAFT','status','in_progress','coverage','draft_daily_result'),
      jsonb_build_object('code',p_run_code||'-WO-GRASS-READY','status','approved','coverage','dispatch_ready')
    )
  );

  update public.system_test_runs set status='ready',completed_at=now(),metadata=v_metadata,updated_at=now()
  where id=v_run_id;

  return v_metadata || jsonb_build_object(
    'status','ready',
    'counts',jsonb_build_object(
      'employees',(select count(*) from public.employees where employee_code like p_run_code||'-E%'),
      'work_orders',(select count(*) from public.work_orders where work_order_no like p_run_code||'%'),
      'work_results',(select count(*) from public.work_results r join public.work_orders w on w.id=r.work_order_id where w.work_order_no like p_run_code||'%'),
      'weight_tickets',(select count(*) from public.work_result_weight_tickets t join public.work_results r on r.id=t.work_result_id join public.work_orders w on w.id=r.work_order_id where w.work_order_no like p_run_code||'%'),
      'performance_metrics',(select count(*) from public.work_performance_metrics m join public.work_results r on r.id=m.work_result_id join public.work_orders w on w.id=r.work_order_id where w.work_order_no like p_run_code||'%'),
      'payroll_periods',(select count(*) from public.payroll_periods where period_code like p_run_code||'%')
    )
  );
end;
$$;


--
-- Name: delete_canonical_annual_work_plan("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_canonical_annual_work_plan"("p_annual_plan_id" "uuid", "p_actor_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_plan public.annual_work_plans%rowtype;
begin
  if p_actor_profile_id is null or not exists (
    select 1 from public.profiles profile
    where profile.id = p_actor_profile_id and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select annual_plan.*
  into v_plan
  from public.annual_work_plans annual_plan
  where annual_plan.id = p_annual_plan_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;
  if v_plan.source_type is distinct from 'canonical_budget' then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
  end if;
  if v_plan.status is distinct from 'draft' then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;
  if exists (
    select 1
    from public.planned_work_items planned_item
    where planned_item.annual_plan_id = p_annual_plan_id
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_NOT_EMPTY';
  end if;

  perform set_config('app.phase2c_plan_header_rpc', 'on', true);

  delete from public.annual_work_plans
  where id = p_annual_plan_id;

  return jsonb_build_object('annual_work_plan_id', p_annual_plan_id, 'deleted', true);
end
$$;


--
-- Name: FUNCTION "delete_canonical_annual_work_plan"("p_annual_plan_id" "uuid", "p_actor_profile_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."delete_canonical_annual_work_plan"("p_annual_plan_id" "uuid", "p_actor_profile_id" "uuid") IS 'Deletes an empty draft canonical Annual Plan without cascading Planned Items.';


--
-- Name: delete_canonical_planned_work_item("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_canonical_planned_work_item"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_item public.planned_work_items%rowtype;
  v_plan public.annual_work_plans%rowtype;
  v_annual_plan_id uuid;
  v_material_count integer := 0;
  v_request_count integer := 0;
begin
  if p_actor_profile_id is null or not exists (
    select 1 from public.profiles profile
    where profile.id = p_actor_profile_id and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select planned_item.annual_plan_id
  into v_annual_plan_id
  from public.planned_work_items planned_item
  where planned_item.id = p_planned_work_item_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;

  select annual_plan.*
  into v_plan
  from public.annual_work_plans annual_plan
  where annual_plan.id = v_annual_plan_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;

  select planned_item.*
  into v_item
  from public.planned_work_items planned_item
  where planned_item.id = p_planned_work_item_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;
  if v_item.annual_plan_id is distinct from v_plan.id
    or v_plan.source_type is distinct from 'canonical_budget'
    or v_item.source_type is distinct from 'canonical_budget'
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
  end if;
  if v_plan.status is distinct from 'draft' then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;

  if exists (
    select 1
    from public.work_orders work_order
    where work_order.planned_work_item_id = p_planned_work_item_id
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_ITEM_HAS_WORK_ORDER';
  end if;

  perform set_config('app.phase2c_snapshot_rpc', 'on', true);

  delete from public.planning_material_snapshot_requests
  where planned_work_item_id = p_planned_work_item_id;
  get diagnostics v_request_count = row_count;

  delete from public.planned_work_materials
  where planned_work_item_id = p_planned_work_item_id;
  get diagnostics v_material_count = row_count;

  delete from public.planned_work_items
  where id = p_planned_work_item_id;

  return jsonb_build_object(
    'planned_work_item_id', p_planned_work_item_id,
    'deleted', true,
    'material_count', v_material_count,
    'request_count', v_request_count
  );
end
$$;


--
-- Name: FUNCTION "delete_canonical_planned_work_item"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."delete_canonical_planned_work_item"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid") IS 'Deletes one draft canonical Planned Item, its Material snapshot, and refresh ledger after rejecting Work Order references.';


--
-- Name: ensure_budget_rate_rule_set("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."ensure_budget_rate_rule_set"("p_budget_year_id" "text", "p_fiscal_year" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_id uuid;
  v_from date;
  v_to date;
begin
  select default_rule_set_id,effective_from,effective_to into v_id,v_from,v_to
  from public.budget_years where id=p_budget_year_id;
  if v_id is not null then return v_id; end if;

  select id into v_id from public.budget_rate_rule_sets
  where budget_year_id=p_budget_year_id
  order by version_no desc,created_at desc limit 1;

  if v_id is null then
    insert into public.budget_rate_rule_sets(
      budget_year_id,fiscal_year,rule_set_code,rule_set_name,
      effective_from,effective_to,version_no,status
    ) values (
      p_budget_year_id,p_fiscal_year,
      'RULE-'||p_fiscal_year||'-AUTO-'||substr(replace(gen_random_uuid()::text,'-',''),1,8),
      'ชุดกฎอัตรา '||p_fiscal_year,v_from,v_to,1,'draft'
    ) returning id into v_id;
  end if;

  update public.budget_years
  set default_rule_set_id=v_id,
      rule_engine_status=case when rule_engine_status='legacy' then 'draft' else rule_engine_status end,
      updated_at=now()
  where id=p_budget_year_id;
  return v_id;
end $$;


--
-- Name: finalize_budget_activity_rate_rule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."finalize_budget_activity_rate_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_rule_id uuid:=new.rule_id;
  v_rule_code text;
  v_rule_status text;
begin
  if current_setting('app.budget_rate_sync_skip',true)='on' then return new; end if;

  if v_rule_id is null and new.rule_set_id is not null then
    v_rule_code:=new.rate_code||'-V'||coalesce(new.version_no,1)::text||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,6);
    insert into public.budget_rate_rules(
      rule_set_id,source_budget_activity_rate_id,rule_code,rule_name,activity_id,activity_code_snapshot,activity_name_snapshot,
      rate_type,rate_dimension_key,unit_name,calculation_method,comparison_basis,condition_mode,condition_name,
      rate_current,rate_proposed,rate_approved,priority,effective_from,effective_to,status,change_reason,note,source_payload,
      material_id,dose_from,dose_to,dose_unit,package_size_kg,worker_scope,contractor_id
    ) values(
      new.rule_set_id,new.id,v_rule_code,new.activity_name||' - '||new.condition_name,new.activity_id,new.activity_code,new.activity_name,
      coalesce(new.rate_type,'labor'),new.rate_dimension_key,coalesce(new.unit_name,'หน่วย'),new.calculation_method,new.comparison_basis,
      new.condition_mode,new.condition_name,new.rate_current,new.rate_proposed,null,new.priority,new.effective_from,new.effective_to,
      'draft',new.change_reason,new.note,jsonb_build_object('source','budget_activity_rates','rate_id',new.id,'condition',new.condition_json),
      new.material_id,new.dose_from,new.dose_to,new.dose_unit,new.package_size_kg,new.worker_scope,new.contractor_id
    ) returning id into v_rule_id;
    perform set_config('app.budget_rate_sync_skip','on',true);
    update public.budget_activity_rates set rule_id=v_rule_id,rule_sync_status='synced',last_rule_synced_at=now() where id=new.id;
    perform set_config('app.budget_rate_sync_skip','off',true);
  end if;

  select status into v_rule_status from public.budget_rate_rules where id=v_rule_id;
  if v_rule_status in ('draft','reviewing') then
    perform public.sync_budget_rate_rule_conditions_from_existing_rate(new.id,v_rule_id);
  end if;

  if new.approval_status='approved' and v_rule_status not in ('approved','active') then
    update public.budget_rate_rules
    set rate_approved=coalesce(new.rate_approved,new.rate_proposed,new.rate_current,new.rate_amount),
        status='approved',approved_by_profile_id=new.approved_by_profile_id,
        approved_at=coalesce(new.approved_at,now()),updated_at=now()
    where id=v_rule_id;
    perform set_config('app.budget_rate_sync_skip','on',true);
    update public.budget_activity_rates
    set rule_sync_status='synced',approved_at=coalesce(approved_at,now())
    where id=new.id;
    perform set_config('app.budget_rate_sync_skip','off',true);
  end if;
  return new;
end $$;


--
-- Name: fuel_setting_boolean("text", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fuel_setting_boolean"("p_key" "text", "p_default" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  select coalesce(
    (select lower(coalesce(setting_value,'')) in ('true','1','yes','y')
     from public.system_settings where setting_key = p_key limit 1),
    p_default
  );
$$;


--
-- Name: generate_activity_budget_rate_recommendation("uuid", "text", "date", "date", "text", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_activity_budget_rate_recommendation"("p_activity_id" "uuid", "p_budget_year_id" "text", "p_period_start" "date", "p_period_end" "date", "p_condition_group" "text" DEFAULT 'default'::"text", "p_current_budget_rate_id" "text" DEFAULT NULL::"text", "p_prepared_by_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_standard record;
  v_current_rate record;
  v_sample_count integer;
  v_employee_count integer;
  v_team_count integer;
  v_block_count integer;
  v_median_eff numeric;
  v_trimmed_eff numeric;
  v_avg_quality numeric;
  v_avg_data_quality numeric;
  v_observed_eff numeric;
  v_capped_eff numeric;
  v_calculated_rate numeric;
  v_weighted_rate numeric;
  v_recommended_rate numeric;
  v_adjustment_pct numeric;
  v_confidence text;
  v_id uuid;
begin
  if p_period_end < p_period_start then
    raise exception 'period_end must be on or after period_start';
  end if;

  select s.* into v_standard
  from public.activity_performance_standards s
  where s.activity_id = p_activity_id
    and s.status = 'approved'
    and s.condition_group in (p_condition_group,'default')
    and s.effective_from <= p_period_end
    and (s.effective_to is null or s.effective_to >= p_period_start)
  order by case when s.condition_group = p_condition_group then 0 else 1 end,
           case when s.budget_year_id = p_budget_year_id then 0 else 1 end,
           s.version_no desc
  limit 1;

  if not found then
    raise exception 'No approved performance standard found for activity %', p_activity_id;
  end if;

  if p_current_budget_rate_id is not null then
    select * into v_current_rate
    from public.budget_activity_rates
    where id = p_current_budget_rate_id;
  else
    select * into v_current_rate
    from public.budget_activity_rates
    where activity_id = p_activity_id
      and budget_year_id = p_budget_year_id
      and coalesce(is_current,true) = true
      and coalesce(status,'active') = 'active'
    order by updated_at desc nulls last, created_at desc nulls last
    limit 1;
  end if;

  if not found or coalesce(v_current_rate.rate_amount,0) <= 0 then
    raise exception 'No positive current budget rate found for activity % and budget year %', p_activity_id, p_budget_year_id;
  end if;

  with base as (
    select m.*
    from public.work_performance_metrics m
    where m.metric_scope = 'result'
      and m.activity_id = p_activity_id
      and m.condition_group = p_condition_group
      and m.work_date between p_period_start and p_period_end
      and m.is_budget_eligible = true
      and m.composite_efficiency_pct is not null
  ), q as (
    select percentile_cont(0.10) within group (order by composite_efficiency_pct) as p10,
           percentile_cont(0.50) within group (order by composite_efficiency_pct) as median_eff,
           percentile_cont(0.90) within group (order by composite_efficiency_pct) as p90
    from base
  )
  select count(*)::int,
         q.median_eff,
         avg(base.composite_efficiency_pct) filter (
           where base.composite_efficiency_pct between q.p10 and q.p90
         ),
         avg(base.quality_pct),
         avg(base.data_quality_pct),
         count(distinct base.team_id)::int,
         count(distinct base.block_id)::int
    into v_sample_count, v_median_eff, v_trimmed_eff, v_avg_quality,
         v_avg_data_quality, v_team_count, v_block_count
  from base cross join q
  group by q.median_eff, q.p10, q.p90;

  select count(distinct employee_id)::int
    into v_employee_count
  from public.work_performance_metrics
  where metric_scope = 'employee'
    and activity_id = p_activity_id
    and condition_group = p_condition_group
    and work_date between p_period_start and p_period_end;

  if coalesce(v_sample_count,0) = 0 then
    raise exception 'No eligible performance samples found for the selected period';
  end if;

  v_observed_eff := coalesce(v_trimmed_eff, v_median_eff);
  v_capped_eff := least(v_standard.efficiency_ceiling_pct, greatest(v_standard.efficiency_floor_pct, v_observed_eff));
  v_calculated_rate := v_current_rate.rate_amount * 100 / nullif(v_capped_eff,0);
  v_weighted_rate := (v_current_rate.rate_amount * 0.70) + (v_calculated_rate * 0.30);
  v_recommended_rate := least(v_current_rate.rate_amount * 1.10, greatest(v_current_rate.rate_amount * 0.90, v_weighted_rate));
  v_adjustment_pct := ((v_recommended_rate - v_current_rate.rate_amount) / v_current_rate.rate_amount) * 100;

  v_confidence := case
    when v_sample_count >= v_standard.minimum_sample_count
      and coalesce(v_employee_count,0) >= v_standard.minimum_employee_count
      and coalesce(v_team_count,0) >= v_standard.minimum_team_count
      and coalesce(v_block_count,0) >= v_standard.minimum_block_count
      and coalesce(v_avg_data_quality,0) >= v_standard.minimum_data_quality_pct
      and coalesce(v_avg_quality,0) >= 90 then 'high'
    when v_sample_count >= greatest(5, ceil(v_standard.minimum_sample_count / 2.0))
      and coalesce(v_avg_data_quality,0) >= 80 then 'medium'
    else 'low'
  end;

  insert into public.activity_budget_rate_recommendations (
    budget_year_id, activity_id, standard_id, current_budget_rate_id,
    condition_group, current_rate, current_unit, observed_efficiency_pct,
    quality_adjusted_efficiency_pct, calculated_rate, recommended_rate,
    adjustment_pct, sample_count, employee_count, team_count, block_count,
    average_quality_pct, average_data_quality_pct, period_start, period_end,
    confidence_level, prepared_by_profile_id
  ) values (
    p_budget_year_id, p_activity_id, v_standard.id, v_current_rate.id,
    p_condition_group, v_current_rate.rate_amount, v_current_rate.unit_name,
    v_observed_eff, v_observed_eff * least(greatest(coalesce(v_avg_quality,100),0),100) / 100,
    v_calculated_rate, v_recommended_rate, v_adjustment_pct,
    v_sample_count, coalesce(v_employee_count,0), coalesce(v_team_count,0),
    coalesce(v_block_count,0), v_avg_quality, v_avg_data_quality,
    p_period_start, p_period_end, v_confidence, p_prepared_by_profile_id
  ) returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: work_results; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."work_results" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_order_id" "uuid",
    "actual_start_at" timestamp with time zone,
    "actual_end_at" timestamp with time zone,
    "actual_quantity" numeric,
    "actual_unit" "text",
    "result_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "submitted_by" "uuid",
    "verified_by" "uuid",
    "closed_by" "uuid",
    "note" "text",
    "result_no" "text",
    "result_date" "date",
    "sequence_no" integer DEFAULT 1 NOT NULL,
    "source_type" "text" DEFAULT 'manual'::"text" NOT NULL,
    "weigh_ticket_count" integer DEFAULT 0 NOT NULL,
    "quality_score" numeric,
    "submitted_at" timestamp with time zone,
    "verified_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actual_area_rai" numeric(18,4),
    "actual_tree_count" integer,
    "worker_count" integer,
    "total_labor_hours" numeric(18,4),
    "total_labor_days" numeric(18,4),
    "working_minutes" integer,
    "stoppage_minutes" integer,
    "completion_pct" numeric(7,2),
    "rework_quantity" numeric(18,4),
    "weather_condition" "text",
    "terrain_condition" "text",
    "condition_group" "text" DEFAULT 'default'::"text" NOT NULL,
    "data_quality_pct" numeric(7,2),
    "actual_fuel_liter" numeric DEFAULT 0 NOT NULL,
    "actual_fuel_cost" numeric DEFAULT 0 NOT NULL,
    "created_by_profile_id" "uuid",
    "survey_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "survey_score_pct" numeric,
    "survey_response_count" integer DEFAULT 0 NOT NULL,
    "survey_last_at" timestamp with time zone
);


--
-- Name: get_or_create_work_result("uuid", "date", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_or_create_work_result"("p_work_order_id" "uuid", "p_result_date" "date" DEFAULT CURRENT_DATE, "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."work_results"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result public.work_results%rowtype;
  v_order public.work_orders%rowtype;
  v_sequence integer;
  v_source_type text;
  v_result_no text;
begin
  select r.* into v_result
  from public.work_results r
  where r.work_order_id=p_work_order_id
    and r.result_date=p_result_date
    and r.result_status in ('draft','submitted')
  order by r.sequence_no desc, r.created_at desc
  limit 1;

  if found then
    return v_result;
  end if;

  select * into v_order
  from public.work_orders
  where id=p_work_order_id;

  if not found then
    raise exception 'Work order % not found', p_work_order_id;
  end if;

  if v_order.status in ('closed','cancelled','rejected') then
    raise exception 'Cannot create result for work order % with status %',p_work_order_id,v_order.status;
  end if;

  perform public.sync_work_order_team_members(p_work_order_id);

  select coalesce(max(sequence_no),0)+1 into v_sequence
  from public.work_results
  where work_order_id=p_work_order_id and result_date=p_result_date;

  select case when a.requires_weigh_ticket then 'weighbridge' else 'manual' end
  into v_source_type
  from public.activities a
  where a.id=v_order.activity_id;

  v_result_no := 'WR-' || to_char(p_result_date,'YYYYMMDD') || '-' ||
                 right(replace(p_work_order_id::text,'-',''),8) || '-' ||
                 lpad(v_sequence::text,2,'0');

  insert into public.work_results(
    work_order_id, result_no, result_date, sequence_no,
    source_type, actual_unit, result_status,
    created_by_profile_id, created_at, updated_at
  )
  values(
    p_work_order_id, v_result_no, p_result_date, v_sequence,
    coalesce(v_source_type,'manual'), v_order.planned_unit, 'draft',
    p_profile_id, now(), now()
  )
  returning * into v_result;

  insert into public.work_result_workers(
    work_result_id, employee_id, team_id, work_date,
    worker_role, attendance_status, actual_hours, actual_quantity,
    actual_unit, rate_type, rate_amount, earning_amount,
    quantity_allocation_method, is_quantity_estimated,
    created_at, updated_at
  )
  select
    v_result.id, wow.employee_id, v_order.team_id, p_result_date,
    wow.role, 'present', 0, 0,
    v_order.planned_unit, 'planned', wow.rate, 0,
    'manual', false,
    now(), now()
  from public.work_order_workers wow
  where wow.work_order_id=p_work_order_id
  on conflict (work_result_id,employee_id,work_date) do nothing;

  update public.work_orders
  set status=case
      when status in ('approved','scheduled','dispatched') then 'in_progress'
      else status
    end
  where id=p_work_order_id;

  return v_result;
end;
$$;


--
-- Name: guard_canonical_annual_plan_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_canonical_annual_plan_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_old_canonical boolean := false;
  v_new_canonical boolean := false;
begin
  if tg_op <> 'INSERT' then
    v_old_canonical :=
      coalesce(old.source_type = 'canonical_budget', false)
      or old.planning_request_key is not null;
  end if;
  if tg_op <> 'DELETE' then
    v_new_canonical :=
      coalesce(new.source_type = 'canonical_budget', false)
      or new.planning_request_key is not null;
  end if;

  if not (v_old_canonical or v_new_canonical) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if current_setting('app.phase2c_plan_header_rpc', true) is distinct from 'on' then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_ACTION_REQUIRED';
  end if;

  if tg_op = 'INSERT' then
    if new.source_type is distinct from 'canonical_budget'
      or nullif(btrim(new.planning_request_key), '') is null
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
    end if;
    if new.status is distinct from 'draft'
      or new.approved_by is not null
      or new.approved_at is not null
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status is distinct from 'draft' then
      raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
    end if;
    return old;
  end if;

  if old.source_type is distinct from new.source_type then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_SOURCE_IMMUTABLE';
  end if;
  if old.planning_request_key is distinct from new.planning_request_key then
    raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_IMMUTABLE';
  end if;
  if old.plan_year is distinct from new.plan_year then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_YEAR_IMMUTABLE';
  end if;
  if old.status is distinct from 'draft' then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;
  if new.status not in ('draft', 'approved') then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;
  if new.status = 'draft'
    and (new.approved_by is not null or new.approved_at is not null)
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_APPROVAL_INVALID';
  end if;
  if new.status = 'approved'
    and (new.approved_by is null or new.approved_at is null)
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_APPROVAL_INVALID';
  end if;

  return new;
end
$$;


--
-- Name: guard_canonical_planning_item_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_canonical_planning_item_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_expected_plan_count integer := 0;
  v_locked_plan_count integer := 0;
  v_plan record;
  v_item_is_canonical boolean := false;
  v_item_is_complete_canonical boolean := false;
  v_parent_is_canonical boolean := false;
begin
  if tg_op = 'INSERT' then
    v_item_is_canonical :=
      coalesce(new.source_type = 'canonical_budget', false)
      or new.planning_request_key is not null
      or new.source_budget_year_id is not null
      or new.source_budget_activity_rate_id is not null
      or new.source_budget_rate_block_id is not null;
    v_item_is_complete_canonical :=
      new.source_type = 'canonical_budget'
      and new.source_budget_year_id is not null
      and new.source_budget_activity_rate_id is not null
      and new.source_budget_rate_block_id is not null
      and nullif(btrim(new.planning_request_key), '') is not null;
  elsif tg_op = 'DELETE' then
    v_item_is_canonical :=
      coalesce(old.source_type = 'canonical_budget', false)
      or old.planning_request_key is not null
      or old.source_budget_year_id is not null
      or old.source_budget_activity_rate_id is not null
      or old.source_budget_rate_block_id is not null;
    v_item_is_complete_canonical :=
      old.source_type = 'canonical_budget'
      and old.source_budget_year_id is not null
      and old.source_budget_activity_rate_id is not null
      and old.source_budget_rate_block_id is not null
      and nullif(btrim(old.planning_request_key), '') is not null;
  else
    v_item_is_canonical :=
      coalesce(new.source_type = 'canonical_budget', false)
      or coalesce(old.source_type = 'canonical_budget', false)
      or new.planning_request_key is not null
      or new.source_budget_year_id is not null
      or new.source_budget_activity_rate_id is not null
      or new.source_budget_rate_block_id is not null
      or old.planning_request_key is not null
      or old.source_budget_year_id is not null
      or old.source_budget_activity_rate_id is not null
      or old.source_budget_rate_block_id is not null;
    v_item_is_complete_canonical :=
      new.source_type = 'canonical_budget'
      and new.source_budget_year_id is not null
      and new.source_budget_activity_rate_id is not null
      and new.source_budget_rate_block_id is not null
      and nullif(btrim(new.planning_request_key), '') is not null;
  end if;

  select count(distinct plan_id)::integer
  into v_expected_plan_count
  from unnest(array[
    case when tg_op <> 'INSERT' then old.annual_plan_id else null end,
    case when tg_op <> 'DELETE' then new.annual_plan_id else null end
  ]::uuid[]) as selected(plan_id)
  where selected.plan_id is not null;

  if v_expected_plan_count = 0 and not v_item_is_canonical then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  for v_plan in
    select annual_plan.id, annual_plan.status, annual_plan.source_type
    from public.annual_work_plans annual_plan
    where annual_plan.id in (
      select distinct selected.plan_id
      from unnest(array[
        case when tg_op <> 'INSERT' then old.annual_plan_id else null end,
        case when tg_op <> 'DELETE' then new.annual_plan_id else null end
      ]::uuid[]) as selected(plan_id)
      where selected.plan_id is not null
    )
    order by annual_plan.id
    for update
  loop
    v_locked_plan_count := v_locked_plan_count + 1;
    v_parent_is_canonical :=
      v_parent_is_canonical or v_plan.source_type = 'canonical_budget';

    if v_plan.source_type = 'canonical_budget' then
      if not v_item_is_complete_canonical then
        raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_ITEM_REQUIRED';
      end if;
    elsif v_item_is_canonical then
      raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_PLAN_REQUIRED';
    end if;

    if (v_item_is_canonical or v_plan.source_type = 'canonical_budget')
      and v_plan.status <> 'draft'
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
    end if;
  end loop;

  if v_expected_plan_count = 0 or v_locked_plan_count <> v_expected_plan_count then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;

  if not (v_item_is_canonical or v_parent_is_canonical) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if current_setting('app.phase2c_snapshot_rpc', true) is distinct from 'on' then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_ACTION_REQUIRED';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


--
-- Name: guard_canonical_planning_material_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_canonical_planning_material_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_expected_item_count integer := 0;
  v_locked_item_count integer := 0;
  v_child_is_canonical boolean := false;
  v_is_canonical boolean;
  v_parent record;
begin
  if tg_op = 'INSERT' then
    v_child_is_canonical :=
      coalesce(new.snapshot_source_type = 'canonical_budget_block_material', false)
      or new.source_budget_rate_block_material_id is not null
      or new.snapshot_usage_basis is not null
      or new.snapshot_usage_rate is not null
      or new.snapshot_basis_quantity is not null
      or new.snapshot_unit_cost is not null
      or new.snapshot_amount_per_basis is not null
      or new.snapshot_at is not null;
  elsif tg_op = 'DELETE' then
    v_child_is_canonical :=
      coalesce(old.snapshot_source_type = 'canonical_budget_block_material', false)
      or old.source_budget_rate_block_material_id is not null
      or old.snapshot_usage_basis is not null
      or old.snapshot_usage_rate is not null
      or old.snapshot_basis_quantity is not null
      or old.snapshot_unit_cost is not null
      or old.snapshot_amount_per_basis is not null
      or old.snapshot_at is not null;
  else
    v_child_is_canonical :=
      coalesce(new.snapshot_source_type = 'canonical_budget_block_material', false)
      or coalesce(old.snapshot_source_type = 'canonical_budget_block_material', false)
      or new.source_budget_rate_block_material_id is not null
      or old.source_budget_rate_block_material_id is not null
      or new.snapshot_usage_basis is not null
      or old.snapshot_usage_basis is not null
      or new.snapshot_usage_rate is not null
      or old.snapshot_usage_rate is not null
      or new.snapshot_basis_quantity is not null
      or old.snapshot_basis_quantity is not null
      or new.snapshot_unit_cost is not null
      or old.snapshot_unit_cost is not null
      or new.snapshot_amount_per_basis is not null
      or old.snapshot_amount_per_basis is not null
      or new.snapshot_at is not null
      or old.snapshot_at is not null;
  end if;

  v_is_canonical := v_child_is_canonical;

  select count(distinct item_id)::integer
  into v_expected_item_count
  from unnest(array[
    case when tg_op <> 'INSERT' then old.planned_work_item_id else null end,
    case when tg_op <> 'DELETE' then new.planned_work_item_id else null end
  ]::uuid[]) as selected(item_id)
  where selected.item_id is not null;

  for v_parent in
    select
      planned_item.id as item_id,
      annual_plan.id as annual_plan_id,
      annual_plan.status as annual_plan_status,
      (
        coalesce(planned_item.source_type = 'canonical_budget', false)
        or planned_item.planning_request_key is not null
        or planned_item.source_budget_year_id is not null
        or planned_item.source_budget_activity_rate_id is not null
        or planned_item.source_budget_rate_block_id is not null
      ) as is_canonical
    from public.planned_work_items planned_item
    join public.annual_work_plans annual_plan
      on annual_plan.id = planned_item.annual_plan_id
    where planned_item.id in (
      select distinct selected.item_id
      from unnest(array[
        case when tg_op <> 'INSERT' then old.planned_work_item_id else null end,
        case when tg_op <> 'DELETE' then new.planned_work_item_id else null end
      ]::uuid[]) as selected(item_id)
      where selected.item_id is not null
    )
    order by annual_plan.id, planned_item.id
    for update of annual_plan
  loop
    v_locked_item_count := v_locked_item_count + 1;
    v_is_canonical := v_is_canonical or v_parent.is_canonical;

    if tg_op <> 'DELETE'
      and v_parent.item_id = new.planned_work_item_id
      and v_parent.is_canonical
      and new.snapshot_source_type is distinct from 'canonical_budget_block_material'
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_MATERIAL_REQUIRED';
    end if;

    if (v_child_is_canonical or v_parent.is_canonical)
      and v_parent.annual_plan_status <> 'draft'
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
    end if;
  end loop;

  if v_expected_item_count = 0 or v_locked_item_count <> v_expected_item_count then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;

  if not v_is_canonical then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if current_setting('app.phase2c_snapshot_rpc', true) is distinct from 'on' then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_ACTION_REQUIRED';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


--
-- Name: employee_document_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."employee_document_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_document_id" "uuid" NOT NULL,
    "version_no" integer NOT NULL,
    "storage_bucket" "text" DEFAULT 'employee-documents'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "original_file_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "file_extension" "text" NOT NULL,
    "file_size" bigint NOT NULL,
    "checksum_sha256" "text" NOT NULL,
    "uploaded_by_profile_id" "uuid" NOT NULL,
    "uploaded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "valid_from" "date",
    "valid_to" "date",
    "is_current" boolean DEFAULT true NOT NULL,
    "replacement_reason" "text",
    "metadata_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by_profile_id" "uuid",
    CONSTRAINT "employee_document_versions_check" CHECK (("storage_path" ~ (('^employees/[0-9a-f-]{36}/[a-z0-9_\-]+/[0-9a-f-]{36}/v[0-9]+\.'::"text" || "file_extension") || '$'::"text"))),
    CONSTRAINT "employee_document_versions_check1" CHECK ((("valid_to" IS NULL) OR ("valid_from" IS NULL) OR ("valid_to" >= "valid_from"))),
    CONSTRAINT "employee_document_versions_check2" CHECK ((("archived_at" IS NULL) = ("archived_by_profile_id" IS NULL))),
    CONSTRAINT "employee_document_versions_checksum_sha256_check" CHECK (("checksum_sha256" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "employee_document_versions_file_extension_check" CHECK (("file_extension" = ANY (ARRAY['pdf'::"text", 'jpg'::"text", 'jpeg'::"text", 'png'::"text", 'webp'::"text"]))),
    CONSTRAINT "employee_document_versions_file_size_check" CHECK ((("file_size" > 0) AND ("file_size" <= 15728640))),
    CONSTRAINT "employee_document_versions_mime_type_check" CHECK (("mime_type" = ANY (ARRAY['application/pdf'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "employee_document_versions_storage_bucket_check" CHECK (("storage_bucket" = 'employee-documents'::"text")),
    CONSTRAINT "employee_document_versions_version_no_check" CHECK (("version_no" > 0))
);


--
-- Name: TABLE "employee_document_versions"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."employee_document_versions" IS 'Immutable document-version metadata. File replacement creates a new row and storage object.';


--
-- Name: hr_finalize_document_version("uuid", integer, integer, "text", "text", "text", "text", bigint, "text", "uuid", "date", "date", "text", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."hr_finalize_document_version"("p_document_id" "uuid", "p_expected_document_version_no" integer, "p_version_no" integer, "p_storage_path" "text", "p_original_file_name" "text", "p_mime_type" "text", "p_file_extension" "text", "p_file_size" bigint, "p_checksum_sha256" "text", "p_uploaded_by_profile_id" "uuid", "p_valid_from" "date" DEFAULT NULL::"date", "p_valid_to" "date" DEFAULT NULL::"date", "p_replacement_reason" "text" DEFAULT NULL::"text", "p_issue_date" "date" DEFAULT NULL::"date", "p_expiry_date" "date" DEFAULT NULL::"date") RETURNS "public"."employee_document_versions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  locked_document public.employee_documents%rowtype;
  created_version public.employee_document_versions%rowtype;
  actual_next_version integer;
begin
  select *
    into locked_document
    from public.employee_documents
   where id = p_document_id
   for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'DOCUMENT_NOT_FOUND';
  end if;
  if locked_document.version_no <> p_expected_document_version_no then
    raise exception using errcode = '40001', message = 'DOCUMENT_VERSION_CONFLICT';
  end if;

  select coalesce(max(version_no), 0) + 1
    into actual_next_version
    from public.employee_document_versions
   where employee_document_id = p_document_id;
  if p_version_no <> actual_next_version then
    raise exception using errcode = '40001', message = 'DOCUMENT_FILE_VERSION_CONFLICT';
  end if;

  update public.employee_document_versions
     set is_current = false
   where employee_document_id = p_document_id
     and is_current is true
     and archived_at is null;

  insert into public.employee_document_versions (
    employee_document_id, version_no, storage_bucket, storage_path,
    original_file_name, mime_type, file_extension, file_size,
    checksum_sha256, uploaded_by_profile_id, valid_from, valid_to,
    is_current, replacement_reason, metadata_json
  ) values (
    p_document_id, p_version_no, 'employee-documents', p_storage_path,
    p_original_file_name, p_mime_type, p_file_extension, p_file_size,
    p_checksum_sha256, p_uploaded_by_profile_id, p_valid_from, p_valid_to,
    true, p_replacement_reason, jsonb_build_object('client_mime', p_mime_type)
  )
  returning * into created_version;

  update public.employee_documents
     set current_version_id = created_version.id,
         status = 'active',
         issue_date = coalesce(p_issue_date, issue_date),
         expiry_date = coalesce(p_expiry_date, expiry_date),
         version_no = version_no + 1,
         updated_at = now()
   where id = p_document_id;

  return created_version;
end
$$;


--
-- Name: log_work_order_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."log_work_order_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_changed_by uuid;
begin
  if tg_op='INSERT' then
    v_changed_by := coalesce(new.created_by_profile_id, new.approved_by_profile_id, new.dispatched_by_profile_id, new.closed_by_profile_id);
    insert into public.work_order_status_logs(work_order_id, from_status, to_status, changed_by, note, changed_at)
    values(new.id, null, new.status, v_changed_by, 'สร้างใบสั่งงาน', coalesce(new.created_at, now()));
  elsif new.status is distinct from old.status then
    v_changed_by := coalesce(new.closed_by_profile_id, new.dispatched_by_profile_id, new.approved_by_profile_id, new.created_by_profile_id);
    insert into public.work_order_status_logs(work_order_id, from_status, to_status, changed_by, note, changed_at)
    values(new.id, old.status, new.status, v_changed_by, 'เปลี่ยนสถานะจาก Workflow', now());
  end if;
  return new;
end;
$$;


--
-- Name: material_conversion_rate("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."material_conversion_rate"("p_material_id" "uuid", "p_from_unit_id" "uuid", "p_to_unit_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare v_rate numeric;
begin
  if p_from_unit_id is null or p_to_unit_id is null then return null; end if;
  if p_from_unit_id=p_to_unit_id then return 1; end if;

  select conversion_rate into v_rate
  from public.sku_conversions
  where material_id=p_material_id and from_unit_id=p_from_unit_id and to_unit_id=p_to_unit_id and status='active'
  limit 1;
  if v_rate is not null then return v_rate; end if;

  select conversion_rate into v_rate
  from public.unit_conversions
  where from_unit_id=p_from_unit_id and to_unit_id=p_to_unit_id and status='active'
  limit 1;
  if v_rate is not null then return v_rate; end if;

  select 1/conversion_rate into v_rate
  from public.sku_conversions
  where material_id=p_material_id and from_unit_id=p_to_unit_id and to_unit_id=p_from_unit_id and status='active' and conversion_rate<>0
  limit 1;
  if v_rate is not null then return v_rate; end if;

  select 1/conversion_rate into v_rate
  from public.unit_conversions
  where from_unit_id=p_to_unit_id and to_unit_id=p_from_unit_id and status='active' and conversion_rate<>0
  limit 1;
  return v_rate;
end;
$$;


--
-- Name: normalize_transport_source_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_transport_source_record"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  new.supplier_code := coalesce(nullif(new.supplier_code,''),nullif(new.raw_payload->>'wpctCode',''));
  new.source_area_key := coalesce(nullif(new.source_area_key,''),nullif(new.area_group,''));
  return new;
end;
$$;


--
-- Name: palm_size_for_budget_year("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."palm_size_for_budget_year"("p_fiscal_year" "text", "p_planting_year" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_age integer := public.calculate_palm_age_for_budget_year(p_fiscal_year,p_planting_year);
begin
  if v_age is null then return 'unknown';
  elsif v_age <= 6 then return 'small';
  elsif v_age <= 14 then return 'medium';
  else return 'large';
  end if;
end;
$$;


--
-- Name: performance_efficiency_pct(numeric, numeric, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."performance_efficiency_pct"("p_observed" numeric, "p_standard" numeric, "p_direction" "text" DEFAULT 'higher_better'::"text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_observed is null or p_standard is null or p_observed <= 0 or p_standard <= 0 then null
    when p_direction = 'lower_better' then round((p_standard / p_observed) * 100, 4)
    else round((p_observed / p_standard) * 100, 4)
  end;
$$;


--
-- Name: performance_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."performance_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: populate_canonical_planning_material_snapshot("uuid", "text", "text", "text", "uuid", "uuid", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."populate_canonical_planning_material_snapshot"("p_planned_work_item_id" "uuid", "p_budget_year_id" "text", "p_budget_activity_rate_id" "text", "p_budget_rate_block_id" "text", "p_block_id" "uuid", "p_activity_id" "uuid", "p_snapshot_at" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_block public.blocks%rowtype;
  v_material_count integer := 0;
begin
  perform 1
  from public.budget_years budget_year
  where budget_year.id = p_budget_year_id
    and budget_year.status = 'active'
    and budget_year.snapshot_required is true
  for share;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_YEAR_NOT_ELIGIBLE';
  end if;

  perform 1
  from public.budget_activity_rates budget_rate
  where budget_rate.id = p_budget_activity_rate_id
    and budget_rate.budget_year_id = p_budget_year_id
    and budget_rate.activity_id = p_activity_id
    and budget_rate.approval_status = 'approved'
    and budget_rate.status = 'active'
    and budget_rate.is_current is true
  for share;
  if not found then
    if exists (
      select 1
      from public.budget_activity_rates budget_rate
      where budget_rate.id = p_budget_activity_rate_id
        and budget_rate.budget_year_id = p_budget_year_id
        and budget_rate.activity_id is distinct from p_activity_id
    ) then
      raise exception using errcode = 'P0001', message = 'PLANNING_ACTIVITY_LINEAGE_MISMATCH';
    end if;
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_ACTIVITY_RATE_NOT_ELIGIBLE';
  end if;

  perform 1
  from public.budget_rate_blocks budget_block
  where budget_block.id = p_budget_rate_block_id
    and budget_block.budget_rate_id = p_budget_activity_rate_id
    and budget_block.block_id = p_block_id
    and budget_block.status = 'active'
  for update;
  if not found then
    if exists (
      select 1
      from public.budget_rate_blocks budget_block
      where budget_block.id = p_budget_rate_block_id
        and budget_block.budget_rate_id = p_budget_activity_rate_id
        and budget_block.block_id is distinct from p_block_id
    ) then
      raise exception using errcode = 'P0001', message = 'PLANNING_BLOCK_LINEAGE_MISMATCH';
    end if;
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_RATE_BLOCK_NOT_ELIGIBLE';
  end if;

  select block_row.*
  into v_block
  from public.blocks block_row
  where block_row.id = p_block_id
  for share;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_BLOCK_NOT_FOUND';
  end if;
  if v_block.status <> 'active' then
    raise exception using errcode = 'P0001', message = 'PLANNING_BLOCK_INACTIVE';
  end if;

  perform 1
  from public.budget_rate_block_materials source_row
  where source_row.budget_rate_block_id = p_budget_rate_block_id
  order by source_row.id
  for share;

  if not exists (
    select 1
    from public.budget_rate_block_materials source_row
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_MATERIAL_SNAPSHOT_EMPTY';
  end if;

  if exists (
    select 1
    from public.budget_rate_block_materials source_row
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
      and source_row.usage_basis in ('manual_qty', 'bag_count')
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_BASIS_NOT_SUPPORTED';
  end if;

  if exists (
    select 1
    from public.budget_rate_block_materials source_row
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
      and source_row.usage_basis not in ('tree_count', 'area_rai', 'manual_qty', 'bag_count')
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_BASIS_NOT_SUPPORTED';
  end if;

  perform 1
  from public.materials material
  where material.id in (
    select source_row.material_id
    from public.budget_rate_block_materials source_row
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
  )
  order by material.id
  for share;

  if exists (
    select 1
    from public.budget_rate_block_materials source_row
    join public.materials material on material.id = source_row.material_id
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
      and material.status <> 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'MATERIAL_INACTIVE';
  end if;

  perform 1
  from public.units unit_row
  where unit_row.id in (
    select source_row.unit_id
    from public.budget_rate_block_materials source_row
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
  )
  order by unit_row.id
  for share;

  if exists (
    select 1
    from public.budget_rate_block_materials source_row
    join public.units unit_row on unit_row.id = source_row.unit_id
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
      and unit_row.status <> 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'UNIT_INACTIVE';
  end if;

  if exists (
    select 1
    from public.budget_rate_block_materials source_row
    where source_row.budget_rate_block_id = p_budget_rate_block_id
      and source_row.status = 'active'
      and (
        (source_row.usage_basis = 'tree_count' and v_block.tree_count < 0)
        or (source_row.usage_basis = 'area_rai' and v_block.area_rai < 0)
      )
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_BASIS_QUANTITY_INVALID';
  end if;

  insert into public.planned_work_materials (
    planned_work_item_id,
    material_id,
    planned_quantity,
    unit_id,
    estimated_unit_cost,
    status,
    source_budget_rate_block_material_id,
    snapshot_source_type,
    snapshot_usage_basis,
    snapshot_usage_rate,
    snapshot_basis_quantity,
    snapshot_unit_cost,
    snapshot_amount_per_basis,
    snapshot_at
  )
  select
    p_planned_work_item_id,
    source_row.material_id,
    (
      case source_row.usage_basis
        when 'tree_count' then v_block.tree_count::numeric
        when 'area_rai' then v_block.area_rai
      end
    ) * source_row.usage_rate,
    source_row.unit_id,
    0,
    'planned',
    source_row.id,
    'canonical_budget_block_material',
    source_row.usage_basis,
    source_row.usage_rate,
    case source_row.usage_basis
      when 'tree_count' then v_block.tree_count::numeric
      when 'area_rai' then v_block.area_rai
    end,
    source_row.unit_cost,
    source_row.amount_per_basis,
    p_snapshot_at
  from public.budget_rate_block_materials source_row
  join public.materials material on material.id = source_row.material_id
  join public.units unit_row on unit_row.id = source_row.unit_id
  where source_row.budget_rate_block_id = p_budget_rate_block_id
    and source_row.status = 'active'
    and material.status = 'active'
    and unit_row.status = 'active'
  order by source_row.id;

  get diagnostics v_material_count = row_count;
  if v_material_count = 0 then
    raise exception using errcode = 'P0001', message = 'PLANNING_MATERIAL_SNAPSHOT_EMPTY';
  end if;

  return v_material_count;
end
$$;


--
-- Name: FUNCTION "populate_canonical_planning_material_snapshot"("p_planned_work_item_id" "uuid", "p_budget_year_id" "text", "p_budget_activity_rate_id" "text", "p_budget_rate_block_id" "text", "p_block_id" "uuid", "p_activity_id" "uuid", "p_snapshot_at" timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."populate_canonical_planning_material_snapshot"("p_planned_work_item_id" "uuid", "p_budget_year_id" "text", "p_budget_activity_rate_id" "text", "p_budget_rate_block_id" "text", "p_block_id" "uuid", "p_activity_id" "uuid", "p_snapshot_at" timestamp with time zone) IS 'Internal service-only canonical Planning Material validation, locking, calculation, and insertion helper.';


--
-- Name: post_goods_issue("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_goods_issue"("p_issue_id" "uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."goods_issues"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_issue public.goods_issues%rowtype;
  v_line record;
  v_balance record;
  v_need numeric;
  v_take numeric;
  v_available numeric;
begin
  select * into v_issue from public.goods_issues where id=p_issue_id for update;
  if not found then raise exception 'Issue % not found',p_issue_id; end if;
  if v_issue.status='posted' then return v_issue; end if;
  if v_issue.status<>'approved' then raise exception 'Issue % must be approved before posting',p_issue_id; end if;

  for v_line in select * from public.goods_issue_lines where issue_id=p_issue_id order by id loop
    select coalesce(sum(quantity_on_hand),0) into v_available
    from public.stock_balances
    where warehouse_id=v_issue.warehouse_id
      and material_id=v_line.material_id
      and (v_line.material_lot_id is null or material_lot_id=v_line.material_lot_id)
      and (v_line.bin_id is null or bin_id=v_line.bin_id);

    if v_available<v_line.quantity then
      raise exception 'Insufficient stock for material %, required %, available %',v_line.material_id,v_line.quantity,v_available;
    end if;

    v_need:=v_line.quantity;
    for v_balance in
      select sb.id,sb.material_lot_id,sb.bin_id,sb.unit_id,sb.quantity_on_hand,ml.expiry_date
      from public.stock_balances sb
      left join public.material_lots ml on ml.id=sb.material_lot_id
      where sb.warehouse_id=v_issue.warehouse_id
        and sb.material_id=v_line.material_id
        and sb.quantity_on_hand>0
        and (v_line.material_lot_id is null or sb.material_lot_id=v_line.material_lot_id)
        and (v_line.bin_id is null or sb.bin_id=v_line.bin_id)
      order by ml.expiry_date nulls last,sb.updated_at,sb.id
      for update of sb
    loop
      exit when v_need<=0;
      v_take:=least(v_need,v_balance.quantity_on_hand);

      update public.stock_balances
      set quantity_on_hand=quantity_on_hand-v_take,updated_at=now()
      where id=v_balance.id;

      if v_balance.material_lot_id is not null then
        update public.material_lots
        set remaining_quantity=greatest(remaining_quantity-v_take,0)
        where id=v_balance.material_lot_id;
      end if;

      insert into public.stock_transactions(
        material_id,warehouse_id,work_order_id,transaction_type,
        quantity,quantity_in,quantity_out,unit_cost,unit_id,
        transaction_date,status,created_by,created_at,
        source_table,source_id,source_line_id,note
      ) values(
        v_line.material_id,v_issue.warehouse_id,v_issue.work_order_id,'issue',
        -v_take,0,v_take,coalesce(v_line.unit_cost,0),coalesce(v_line.unit_id,v_balance.unit_id),
        v_issue.issue_date,'posted',p_profile_id,now(),
        'goods_issues',v_issue.id,v_line.id,'ตัดสต๊อกจากใบจ่าย '||v_issue.issue_no
      ) on conflict do nothing;

      v_need:=v_need-v_take;
    end loop;

    update public.work_order_materials
    set issued_quantity=issued_quantity+v_line.quantity,
        status='issued',updated_at=now()
    where work_order_id=v_issue.work_order_id and material_id=v_line.material_id;
  end loop;

  update public.goods_issues
  set status='posted',posted_by_profile_id=p_profile_id,posted_at=now(),updated_at=now()
  where id=p_issue_id
  returning * into v_issue;

  return v_issue;
end;
$$;


--
-- Name: post_goods_return("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."post_goods_return"("p_return_id" "uuid", "p_profile_id" "uuid") RETURNS "public"."goods_returns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_return public.goods_returns;
  v_base_qty numeric;
  r record;
begin
  select * into v_return
  from public.goods_returns
  where id=p_return_id
  for update;
  if not found then raise exception 'GOODS_RETURN_NOT_FOUND'; end if;
  if v_return.status='posted' then return v_return; end if;
  if v_return.status<>'approved' then
    raise exception 'GOODS_RETURN_NOT_APPROVED';
  end if;

  perform public.validate_goods_return_integrity(p_return_id);

  for r in
    select grl.*,m.base_unit_id as material_base_unit_id
    from public.goods_return_lines grl
    join public.materials m on m.id=grl.material_id
    where grl.return_id=p_return_id
    order by grl.goods_issue_line_id,grl.id
  loop
    v_base_qty:=public.convert_material_quantity(
      r.material_id,r.quantity,r.unit_id,r.material_base_unit_id
    );

    insert into public.stock_balances(
      warehouse_id,bin_id,material_id,material_lot_id,
      quantity_on_hand,unit_id,updated_at
    ) values(
      v_return.warehouse_id,r.destination_bin_id,r.material_id,r.material_lot_id,
      v_base_qty,r.material_base_unit_id,now()
    )
    on conflict(
      warehouse_id,
      (coalesce(bin_id,'00000000-0000-0000-0000-000000000000'::uuid)),
      material_id,
      (coalesce(material_lot_id,'00000000-0000-0000-0000-000000000000'::uuid)),
      unit_id
    )
    do update set
      quantity_on_hand=public.stock_balances.quantity_on_hand+excluded.quantity_on_hand,
      updated_at=now();

    if r.material_lot_id is not null then
      update public.material_lots
      set remaining_quantity=remaining_quantity+v_base_qty
      where id=r.material_lot_id;
      if not found then raise exception 'MATERIAL_LOT_NOT_MATCH_ISSUE'; end if;
    end if;

    insert into public.stock_transactions(
      material_id,warehouse_id,work_order_id,transaction_type,quantity,
      quantity_in,quantity_out,unit_id,unit_cost,transaction_date,status,
      created_by,source_table,source_id,source_line_id,note
    ) values(
      r.material_id,v_return.warehouse_id,v_return.work_order_id,'return',v_base_qty,
      v_base_qty,0,r.material_base_unit_id,r.unit_cost,v_return.return_date,'posted',
      p_profile_id,'goods_returns',v_return.id,r.id,'เธเธทเธเธเธฑเธชเธ”เธธเน€เธเนเธฒเธเธฅเธฑเธ'
    );
  end loop;

  update public.goods_returns
  set status='posted',
      posted_by_profile_id=p_profile_id,
      posted_at=now(),
      updated_at=now()
  where id=p_return_id
  returning * into v_return;

  update public.work_order_materials wom
  set returned_quantity=coalesce((
      select sum(public.convert_material_quantity(
        grl.material_id,grl.quantity,grl.unit_id,wom.unit_id
      ))
      from public.goods_return_lines grl
      join public.goods_returns gr on gr.id=grl.return_id
      where gr.work_order_id=wom.work_order_id
        and grl.material_id=wom.material_id
        and gr.status='posted'
    ),0),
    updated_at=now()
  where wom.work_order_id=v_return.work_order_id;

  return v_return;
end;
$$;


--
-- Name: prepare_budget_activity_rate_rule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prepare_budget_activity_rate_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_rule_status text;
  v_changed boolean:=false;
  v_workflow_changed boolean:=false;
  v_new_rule_id uuid;
  v_rule_code text;
begin
  if current_setting('app.budget_rate_sync_skip',true)='on' then return new; end if;

  if new.rule_set_id is null and new.budget_year_id is not null then
    new.rule_set_id:=public.ensure_budget_rate_rule_set(new.budget_year_id,new.fiscal_year);
  end if;

  new.rate_current:=coalesce(new.rate_current,new.rate_amount,0);
  new.rate_proposed:=coalesce(new.rate_proposed,new.rate_current,new.rate_amount,0);
  new.rate_approved:=coalesce(new.rate_approved,new.rate_proposed,new.rate_current,new.rate_amount,0);
  new.condition_name:=coalesce(nullif(new.condition_name,''),nullif(new.ap_code,''),nullif(new.terrain_code,''),'ทุกบล็อก');
  new.condition_json:=coalesce(new.condition_json,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
    'planting_year',case when new.planting_year_from is not null or new.planting_year_to is not null then jsonb_build_object('from',new.planting_year_from,'to',new.planting_year_to) end,
    'palm_age',case when new.palm_age_from is not null or new.palm_age_to is not null then jsonb_build_object('from',new.palm_age_from,'to',new.palm_age_to,'basis',new.age_basis_mode) end,
    'palm_size',new.palm_size,'ap_code',new.ap_code,'block_id',new.block_id,'rspo_status',new.rspo_status,
    'material_id',new.material_id,
    'dose',case when new.dose_from is not null or new.dose_to is not null then jsonb_build_object('from',new.dose_from,'to',new.dose_to,'unit',new.dose_unit) end,
    'package_size_kg',new.package_size_kg,'worker_scope',new.worker_scope,'contractor_id',new.contractor_id
  ));

  if tg_op='INSERT' then
    new.rule_sync_status:=case when new.rule_set_id is null then 'waiting_rule_set' else 'pending_create' end;
    return new;
  end if;

  v_changed:=
    new.activity_id is distinct from old.activity_id or new.activity_code is distinct from old.activity_code or
    new.activity_name is distinct from old.activity_name or new.rate_type is distinct from old.rate_type or
    new.rate_dimension_key is distinct from old.rate_dimension_key or new.unit_name is distinct from old.unit_name or
    new.calculation_method is distinct from old.calculation_method or new.comparison_basis is distinct from old.comparison_basis or
    new.condition_mode is distinct from old.condition_mode or new.condition_name is distinct from old.condition_name or
    new.priority is distinct from old.priority or new.rate_current is distinct from old.rate_current or
    new.rate_proposed is distinct from old.rate_proposed or new.rate_approved is distinct from old.rate_approved or
    new.effective_from is distinct from old.effective_from or new.effective_to is distinct from old.effective_to or
    new.planting_year_from is distinct from old.planting_year_from or new.planting_year_to is distinct from old.planting_year_to or
    new.palm_age_from is distinct from old.palm_age_from or new.palm_age_to is distinct from old.palm_age_to or
    new.palm_size is distinct from old.palm_size or new.ap_code is distinct from old.ap_code or
    new.block_id is distinct from old.block_id or new.rspo_status is distinct from old.rspo_status or
    new.material_id is distinct from old.material_id or new.dose_from is distinct from old.dose_from or
    new.dose_to is distinct from old.dose_to or new.dose_unit is distinct from old.dose_unit or
    new.package_size_kg is distinct from old.package_size_kg or new.worker_scope is distinct from old.worker_scope or
    new.contractor_id is distinct from old.contractor_id;
  v_workflow_changed:=new.approval_status is distinct from old.approval_status or new.approved_by_profile_id is distinct from old.approved_by_profile_id;

  if new.rule_id is not null then select status into v_rule_status from public.budget_rate_rules where id=new.rule_id; end if;

  if v_changed and v_rule_status in ('approved','active') then
    v_rule_code:=new.rate_code||'-V'||substr(replace(gen_random_uuid()::text,'-',''),1,8);
    insert into public.budget_rate_rules(
      rule_set_id,copied_from_rule_id,source_budget_activity_rate_id,rule_code,rule_name,
      activity_id,activity_code_snapshot,activity_name_snapshot,rate_type,rate_dimension_key,unit_name,
      calculation_method,comparison_basis,condition_mode,condition_name,rate_current,rate_proposed,rate_approved,
      priority,needs_mapping,effective_from,effective_to,status,change_reason,note,source_payload,
      material_id,dose_from,dose_to,dose_unit,package_size_kg,worker_scope,contractor_id
    ) values (
      new.rule_set_id,old.rule_id,new.id,v_rule_code,new.activity_name||' - '||new.condition_name,
      new.activity_id,new.activity_code,new.activity_name,coalesce(new.rate_type,'labor'),new.rate_dimension_key,coalesce(new.unit_name,'หน่วย'),
      new.calculation_method,new.comparison_basis,new.condition_mode,new.condition_name,new.rate_current,new.rate_proposed,null,
      new.priority,false,new.effective_from,new.effective_to,'draft',coalesce(new.change_reason,'แก้ไขจากอัตราที่อนุมัติแล้ว'),new.note,
      jsonb_build_object('source','budget_activity_rates','rate_id',new.id,'condition',new.condition_json),
      new.material_id,new.dose_from,new.dose_to,new.dose_unit,new.package_size_kg,new.worker_scope,new.contractor_id
    ) returning id into v_new_rule_id;
    new.rule_id:=v_new_rule_id;
    new.version_no:=coalesce(old.version_no,1)+1;
    new.approval_status:='draft';
    new.approved_by_profile_id:=null;
    new.approved_at:=null;
    new.rule_sync_status:='version_created';
  elsif (v_changed or v_workflow_changed) and new.rule_id is not null then
    update public.budget_rate_rules
    set rule_set_id=new.rule_set_id,
        rule_name=new.activity_name||' - '||new.condition_name,
        activity_id=new.activity_id,activity_code_snapshot=new.activity_code,activity_name_snapshot=new.activity_name,
        rate_type=coalesce(new.rate_type,'labor'),rate_dimension_key=new.rate_dimension_key,unit_name=coalesce(new.unit_name,'หน่วย'),
        calculation_method=new.calculation_method,comparison_basis=new.comparison_basis,
        condition_mode=new.condition_mode,condition_name=new.condition_name,
        rate_current=new.rate_current,rate_proposed=new.rate_proposed,
        rate_approved=case when new.approval_status='approved' then new.rate_approved else rate_approved end,
        priority=new.priority,effective_from=new.effective_from,effective_to=new.effective_to,
        status=case when new.approval_status='approved' then 'reviewing'
                    when new.approval_status in ('draft','reviewing','rejected','cancelled') then new.approval_status
                    else status end,
        change_reason=new.change_reason,note=new.note,
        source_payload=coalesce(source_payload,'{}'::jsonb)||jsonb_build_object('condition',new.condition_json),
        material_id=new.material_id,dose_from=new.dose_from,dose_to=new.dose_to,dose_unit=new.dose_unit,
        package_size_kg=new.package_size_kg,worker_scope=new.worker_scope,contractor_id=new.contractor_id,
        updated_at=now()
    where id=new.rule_id;
    new.rule_sync_status:=case when new.approval_status='approved' then 'pending_approval' else 'synced' end;
  end if;

  new.last_rule_synced_at:=now();
  return new;
end $$;


--
-- Name: prepare_goods_issue_from_work_order("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prepare_goods_issue_from_work_order"("p_work_order_id" "uuid", "p_warehouse_id" "uuid" DEFAULT NULL::"uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."goods_issues"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_issue public.goods_issues%rowtype;
  v_order public.work_orders%rowtype;
  v_warehouse_id uuid;
  v_issue_no text;
  v_line_count integer;
begin
  select * into v_order from public.work_orders where id=p_work_order_id;
  if not found then raise exception 'Work order % not found',p_work_order_id; end if;

  v_warehouse_id:=p_warehouse_id;
  if v_warehouse_id is null then
    select id into v_warehouse_id from public.warehouses
    where status='active' and is_default order by warehouse_code limit 1;
  end if;
  if v_warehouse_id is null and (select count(*) from public.warehouses where status='active')=1 then
    select id into v_warehouse_id from public.warehouses where status='active' limit 1;
  end if;
  if v_warehouse_id is null then raise exception 'No active/default warehouse configured'; end if;

  select * into v_issue
  from public.goods_issues
  where work_order_id=p_work_order_id and warehouse_id=v_warehouse_id
    and status in ('draft','pending_approval','approved')
  order by created_at desc limit 1;
  if found then return v_issue; end if;

  select count(*) into v_line_count
  from public.work_order_materials
  where work_order_id=p_work_order_id and greatest(planned_quantity-issued_quantity,0)>0;
  if v_line_count=0 then raise exception 'Work order % has no outstanding material to issue',p_work_order_id; end if;

  v_issue_no:='GI-'||to_char(current_date,'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));

  insert into public.goods_issues(
    issue_no,warehouse_id,work_order_id,issue_date,issued_to_employee_id,
    status,created_by,created_at,updated_at,request_source,
    requested_by_profile_id,note,source_snapshot
  ) values(
    v_issue_no,v_warehouse_id,p_work_order_id,current_date,
    coalesce(v_order.supervisor_employee_id,v_order.manager_employee_id),
    'draft',p_profile_id,now(),now(),'work_order',p_profile_id,
    'สร้างจากวัสดุคงค้างในใบสั่งงาน',
    jsonb_build_object('work_order_no',v_order.work_order_no,'scheduled_date',v_order.scheduled_date)
  ) returning * into v_issue;

  insert into public.goods_issue_lines(
    issue_id,material_id,quantity,unit_id,unit_cost
  )
  select v_issue.id,m.material_id,
         greatest(m.planned_quantity-m.issued_quantity,0),
         m.unit_id,0
  from public.work_order_materials m
  where m.work_order_id=p_work_order_id
    and greatest(m.planned_quantity-m.issued_quantity,0)>0;

  return v_issue;
end;
$$;


--
-- Name: prepare_goods_return_from_issue("uuid", "uuid", "date", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prepare_goods_return_from_issue"("p_issue_id" "uuid", "p_profile_id" "uuid", "p_return_date" "date" DEFAULT CURRENT_DATE, "p_work_result_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."goods_returns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_issue public.goods_issues;
  v_return public.goods_returns;
  v_no text;
  v_destination_bin_id uuid;
  r record;
  v_used numeric;
  v_returned numeric;
  v_available numeric;
begin
  select * into v_issue
  from public.goods_issues
  where id=p_issue_id
  for update;
  if not found then raise exception 'GOODS_ISSUE_NOT_FOUND'; end if;
  if v_issue.status<>'posted' then raise exception 'GOODS_ISSUE_NOT_POSTED'; end if;
  if v_issue.usage_status='closed' then raise exception 'GOODS_ISSUE_USAGE_CLOSED'; end if;

  if p_work_result_id is not null
     and not exists(
       select 1 from public.work_results wr
       where wr.id=p_work_result_id
         and wr.work_order_id is not distinct from v_issue.work_order_id
     ) then
    raise exception 'WORK_RESULT_NOT_MATCH_ISSUE';
  end if;

  select * into v_return
  from public.goods_returns
  where goods_issue_id=p_issue_id
    and status in ('draft','pending_approval','approved')
  order by created_at desc,id
  limit 1;
  if found then return v_return; end if;

  v_no:='GR-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');
  insert into public.goods_returns(
    return_no,warehouse_id,work_order_id,work_result_id,goods_issue_id,
    return_date,status,created_by,requested_by_profile_id,created_at,updated_at
  ) values(
    v_no,v_issue.warehouse_id,v_issue.work_order_id,p_work_result_id,p_issue_id,
    p_return_date,'draft',p_profile_id,p_profile_id,now(),now()
  ) returning * into v_return;

  for r in
    select *
    from public.goods_issue_lines
    where issue_id=p_issue_id
    order by id
    for update
  loop
    select coalesce(sum(issue_unit_quantity),0) into v_used
    from public.goods_issue_daily_usage
    where goods_issue_line_id=r.id
      and status='posted';

    select coalesce(sum(public.convert_material_quantity(
      r.material_id,grl.quantity,grl.unit_id,r.unit_id
    )),0) into v_returned
    from public.goods_return_lines grl
    join public.goods_returns gr on gr.id=grl.return_id
    where grl.goods_issue_line_id=r.id
      and gr.status='posted';

    v_available:=greatest(r.quantity-v_used-v_returned,0);
    if v_available>0 then
      v_destination_bin_id:=r.bin_id;
      if v_destination_bin_id is null then
        select bl.id into v_destination_bin_id
        from public.bin_locations bl
        where bl.warehouse_id=v_issue.warehouse_id
          and bl.status='active'
        order by bl.bin_code,bl.id
        limit 1;
      end if;

      insert into public.goods_return_lines(
        return_id,material_id,material_lot_id,goods_issue_line_id,
        destination_bin_id,quantity,unit_id,base_quantity,base_unit_id,
        unit_cost,amount,condition_status
      )
      select
        v_return.id,r.material_id,r.material_lot_id,r.id,
        v_destination_bin_id,v_available,r.unit_id,
        public.convert_material_quantity(
          r.material_id,v_available,r.unit_id,m.base_unit_id
        ),
        m.base_unit_id,r.unit_cost,round(v_available*r.unit_cost,2),'good'
      from public.materials m
      where m.id=r.material_id;
    end if;
  end loop;

  return v_return;
end;
$$;


--
-- Name: prepare_payroll_period("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prepare_payroll_period"("p_period_id" "uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_period public.payroll_periods%rowtype;
  v_inserted_summaries integer:=0;
  v_inserted_earnings integer:=0;
  v_eligible integer:=0;
  v_unverified integer:=0;
  v_summary record;
begin
  select * into v_period from public.payroll_periods where id=p_period_id for update;
  if not found then raise exception 'Payroll period % not found',p_period_id; end if;
  if v_period.status in ('closed','cancelled') then
    raise exception 'Payroll period % cannot be recalculated with status %',p_period_id,v_period.status;
  end if;
  if v_period.start_date is null or v_period.end_date is null then
    raise exception 'Payroll period % requires start and end dates',p_period_id;
  end if;

  select count(*) into v_unverified
  from public.work_result_workers wrw
  join public.work_results wr on wr.id=wrw.work_result_id
  where wrw.work_date between v_period.start_date and v_period.end_date
    and wr.result_status not in ('verified','closed');
  if v_unverified>0 then
    raise exception 'Payroll period has % unverified work-result worker lines',v_unverified;
  end if;

  select count(*) into v_eligible
  from public.work_result_workers wrw
  join public.work_results wr on wr.id=wrw.work_result_id
  where wrw.work_date between v_period.start_date and v_period.end_date
    and wr.result_status in ('verified','closed');
  if v_eligible=0 then
    raise exception 'Payroll period has no verified/closed work results';
  end if;

  insert into public.payroll_employee_summaries(
    payroll_period_id,employee_id,status,created_at,updated_at
  )
  select distinct p_period_id,wrw.employee_id,'draft',now(),now()
  from public.work_result_workers wrw
  join public.work_results wr on wr.id=wrw.work_result_id
  where wr.result_status in ('verified','closed')
    and wrw.work_date between v_period.start_date and v_period.end_date
  on conflict (payroll_period_id,employee_id) do nothing;
  get diagnostics v_inserted_summaries=row_count;

  insert into public.payroll_earning_lines(
    payroll_summary_id,work_result_worker_id,work_result_id,
    earning_type,work_date,work_order_no,activity_code,
    quantity,unit,rate,amount,source_snapshot,status,
    calculation_version,is_locked,prepared_by_profile_id,created_at
  )
  select
    s.id,wrw.id,wr.id,
    case
      when lower(coalesce(wrw.rate_type,'')) like '%ot%' or lower(coalesce(wrw.rate_type,''))='overtime' then 'overtime'
      when wrw.actual_quantity>0 then 'piece_rate'
      else 'regular'
    end,
    wrw.work_date,wo.work_order_no,a.activity_code,
    case when wrw.actual_quantity>0 then wrw.actual_quantity else wrw.actual_hours end,
    case when wrw.actual_quantity>0 then wrw.actual_unit else 'ชั่วโมง' end,
    wrw.rate_amount,
    case
      when wrw.earning_amount>0 then wrw.earning_amount
      when wrw.actual_quantity>0 then wrw.actual_quantity*wrw.rate_amount
      else wrw.actual_hours*wrw.rate_amount
    end,
    jsonb_build_object(
      'work_result_worker_id',wrw.id,'employee_id',wrw.employee_id,
      'work_result_id',wr.id,'work_order_id',wo.id,
      'result_status',wr.result_status,'actual_hours',wrw.actual_hours,
      'actual_quantity',wrw.actual_quantity,'rate_type',wrw.rate_type,
      'rate_amount',wrw.rate_amount
    ),
    'draft',v_period.calculation_version,false,p_profile_id,now()
  from public.work_result_workers wrw
  join public.work_results wr on wr.id=wrw.work_result_id
  join public.work_orders wo on wo.id=wr.work_order_id
  left join public.activities a on a.id=wo.activity_id
  join public.payroll_employee_summaries s
    on s.payroll_period_id=p_period_id and s.employee_id=wrw.employee_id
  where wr.result_status in ('verified','closed')
    and wrw.work_date between v_period.start_date and v_period.end_date
  on conflict (work_result_worker_id) where work_result_worker_id is not null do nothing;
  get diagnostics v_inserted_earnings=row_count;

  for v_summary in select id from public.payroll_employee_summaries where payroll_period_id=p_period_id loop
    perform public.recalculate_payroll_employee_summary(v_summary.id);
  end loop;

  update public.payroll_periods
  set status=case when status='open' then 'calculated' else status end,
      prepared_by_profile_id=coalesce(prepared_by_profile_id,p_profile_id),
      prepared_at=coalesce(prepared_at,now()),
      calculated_by_profile_id=p_profile_id,calculated_at=now(),updated_at=now()
  where id=p_period_id;

  return jsonb_build_object(
    'payroll_period_id',p_period_id,'eligible_worker_lines',v_eligible,
    'inserted_summaries',v_inserted_summaries,'inserted_earnings',v_inserted_earnings,
    'summary_count',(select count(*) from public.payroll_employee_summaries where payroll_period_id=p_period_id),
    'earning_count',(select count(*) from public.payroll_earning_lines e join public.payroll_employee_summaries s on s.id=e.payroll_summary_id where s.payroll_period_id=p_period_id),
    'status','calculated'
  );
end;
$$;


--
-- Name: prevent_approved_budget_rule_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_approved_budget_rule_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_rule_set_id uuid;
  v_status text;
begin
  if tg_table_name='budget_rate_rule_sets' then
    v_rule_set_id:=coalesce(old.id,new.id);
  elsif tg_table_name='budget_rate_rules' then
    v_rule_set_id:=coalesce(old.rule_set_id,new.rule_set_id);
  elsif tg_table_name='budget_rate_rule_conditions' then
    select rule_set_id into v_rule_set_id from public.budget_rate_rules where id=coalesce(old.rule_id,new.rule_id);
  elsif tg_table_name='budget_rate_rule_blocks' then
    select rule_set_id into v_rule_set_id from public.budget_rate_rules where id=coalesce(old.rule_id,new.rule_id);
  end if;
  select status into v_status from public.budget_rate_rule_sets where id=v_rule_set_id;
  if v_status in ('approved','active','superseded') then
    if tg_table_name='budget_rate_rule_sets' and tg_op='UPDATE'
       and new.status is distinct from old.status
       and new.status in ('active','superseded') then
      return new;
    end if;
    raise exception 'Approved/active budget rule sets are immutable; create a new version';
  end if;
  return coalesce(new,old);
end;
$$;


--
-- Name: prevent_locked_payroll_earning_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_locked_payroll_earning_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if old.is_locked and coalesce(current_setting('app.allow_test_cleanup',true),'false')<>'true' then
    raise exception 'Locked payroll earning line % cannot be changed',old.id;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: preview_budget_rate_year_movement("uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."preview_budget_rate_year_movement"("p_source_rule_set_id" "uuid", "p_target_fiscal_year" integer) RETURNS TABLE("block_id" "uuid", "block_code" "text", "planting_year" integer, "source_fiscal_year" integer, "source_age" integer, "target_fiscal_year" integer, "target_age" integer, "source_palm_size" "text", "target_palm_size" "text", "movement_status" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with src as (
    select nullif(rs.fiscal_year,'')::integer source_year
    from public.budget_rate_rule_sets rs
    where rs.id = p_source_rule_set_id
  ), base as (
    select
      b.id,
      b.block_code,
      b.planting_year,
      src.source_year,
      case when b.planting_year is null then null else src.source_year - b.planting_year end source_age,
      case when b.planting_year is null then null else p_target_fiscal_year - b.planting_year end target_age
    from public.blocks b cross join src
    where b.status = 'active'
  )
  select
    base.id,
    base.block_code,
    base.planting_year,
    base.source_year,
    base.source_age,
    p_target_fiscal_year,
    base.target_age,
    case
      when base.source_age is null then null
      when base.source_age <= 6 then 'small'
      when base.source_age between 7 and 14 then 'medium'
      else 'large'
    end,
    case
      when base.target_age is null then null
      when base.target_age <= 6 then 'small'
      when base.target_age between 7 and 14 then 'medium'
      else 'large'
    end,
    case
      when base.planting_year is null then 'missing_planting_year'
      when (case when base.source_age <= 6 then 'small' when base.source_age between 7 and 14 then 'medium' else 'large' end)
         <> (case when base.target_age <= 6 then 'small' when base.target_age between 7 and 14 then 'medium' else 'large' end)
        then 'moved_age_group'
      else 'same_group'
    end
  from base
  order by base.block_code, base.id;
$$;


--
-- Name: preview_budget_rule_set_movement("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."preview_budget_rule_set_movement"("p_target_rule_set_id" "uuid") RETURNS TABLE("movement_status" "text", "block_id" "uuid", "block_code" "text", "activity_id" "uuid", "rate_type" "text", "rate_dimension_key" "text", "unit_name" "text", "source_rule_code" "text", "target_rule_code" "text", "source_condition" "text", "target_condition" "text", "source_age" integer, "target_age" integer, "source_rate" numeric, "target_rate" numeric)
    LANGUAGE "sql" STABLE
    AS $$
with target_set as (
  select * from public.budget_rate_rule_sets where id=p_target_rule_set_id
), source_rows as (
  select m.* from public.v_budget_rate_rule_resolution m join target_set t on m.rule_set_id=t.parent_rule_set_id
), target_rows as (
  select m.* from public.v_budget_rate_rule_resolution m where m.rule_set_id=p_target_rule_set_id
)
select
  case
    when s.block_id is null then 'new'
    when t.block_id is null then 'removed'
    when s.rule_id<>coalesce((select copied_from_rule_id from public.budget_rate_rules where id=t.rule_id),t.rule_id) then 'moved_group'
    when s.resolved_rate is distinct from t.resolved_rate then 'rate_changed'
    else 'unchanged'
  end,
  coalesce(t.block_id,s.block_id),coalesce(t.block_code,s.block_code),coalesce(t.activity_id,s.activity_id),
  coalesce(t.rate_type,s.rate_type),coalesce(t.rate_dimension_key,s.rate_dimension_key),coalesce(t.unit_name,s.unit_name),
  s.rule_code,t.rule_code,s.condition_name,t.condition_name,s.calculated_age,t.calculated_age,s.resolved_rate,t.resolved_rate
from source_rows s
full join target_rows t
  on t.block_id=s.block_id
 and t.activity_id is not distinct from s.activity_id
 and t.rate_type=s.rate_type
 and t.rate_dimension_key=s.rate_dimension_key
 and t.unit_name=s.unit_name;
$$;


--
-- Name: profile_has_permission("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."profile_has_permission"("requested_profile_id" "uuid", "requested_permission_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.v_profile_permissions v
    where v.profile_id=requested_profile_id
      and v.permission_key=requested_permission_key
  );
$$;


--
-- Name: area_map_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."area_map_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "version_no" bigint NOT NULL,
    "deployment_context" "text" DEFAULT 'production'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "source_version_id" "uuid",
    "original_file_name" "text" NOT NULL,
    "raw_storage_path" "text",
    "processed_storage_path" "text",
    "sha256" "text" NOT NULL,
    "file_size_bytes" bigint NOT NULL,
    "feature_count" integer DEFAULT 0 NOT NULL,
    "matched_count" integer DEFAULT 0 NOT NULL,
    "unmatched_count" integer DEFAULT 0 NOT NULL,
    "master_without_map_count" integer DEFAULT 0 NOT NULL,
    "duplicate_count" integer DEFAULT 0 NOT NULL,
    "conflict_count" integer DEFAULT 0 NOT NULL,
    "bounds" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "source_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reconciliation_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "validation_errors" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "unmatched_acknowledged" boolean DEFAULT false NOT NULL,
    "uploaded_by_profile_id" "uuid",
    "published_by_profile_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    CONSTRAINT "area_map_versions_conflict_count_check" CHECK (("conflict_count" >= 0)),
    CONSTRAINT "area_map_versions_duplicate_count_check" CHECK (("duplicate_count" >= 0)),
    CONSTRAINT "area_map_versions_feature_count_check" CHECK (("feature_count" >= 0)),
    CONSTRAINT "area_map_versions_file_size_bytes_check" CHECK ((("file_size_bytes" > 0) AND ("file_size_bytes" <= 3145728))),
    CONSTRAINT "area_map_versions_master_without_map_count_check" CHECK (("master_without_map_count" >= 0)),
    CONSTRAINT "area_map_versions_matched_count_check" CHECK (("matched_count" >= 0)),
    CONSTRAINT "area_map_versions_sha256_check" CHECK (("sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "area_map_versions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'validated'::"text", 'published'::"text", 'rejected'::"text", 'archived'::"text"]))),
    CONSTRAINT "area_map_versions_storage_paths" CHECK ((("status" = ANY (ARRAY['draft'::"text", 'rejected'::"text"])) OR (("raw_storage_path" IS NOT NULL) AND ("processed_storage_path" IS NOT NULL)))),
    CONSTRAINT "area_map_versions_unmatched_count_check" CHECK (("unmatched_count" >= 0))
);


--
-- Name: TABLE "area_map_versions"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."area_map_versions" IS 'Immutable KMZ/processed GeoJSON version metadata. Canonical business identity remains public.blocks.id.';


--
-- Name: COLUMN "area_map_versions"."deployment_context"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."area_map_versions"."deployment_context" IS 'Server-derived context (production or isolated preview/UAT branch) so preview publication cannot change the production active map.';


--
-- Name: publish_area_map_version("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."publish_area_map_version"("p_version_id" "uuid", "p_deployment_context" "text", "p_actor_profile_id" "uuid") RETURNS "public"."area_map_versions"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target public.area_map_versions;
begin
  if nullif(trim(p_deployment_context), '') is null then
    raise exception using errcode = '22023', message = 'deployment context is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('area-map:' || p_deployment_context, 0));

  select * into target
  from public.area_map_versions
  where id = p_version_id and deployment_context = p_deployment_context
  for update;

  if target.id is null then
    raise exception using errcode = 'P0002', message = 'Area map version not found';
  end if;
  if target.status = 'published' then
    return target;
  end if;
  if target.status <> 'validated' then
    raise exception using errcode = '22023', message = 'Only a validated Area map version can be published';
  end if;
  if target.feature_count <= 0
     or target.processed_storage_path is null
     or jsonb_typeof(target.bounds) <> 'array'
     or jsonb_array_length(target.bounds) <> 4
     or jsonb_typeof(target.validation_errors) <> 'array'
     or jsonb_array_length(target.validation_errors) > 0
     or target.duplicate_count > 0
     or target.conflict_count > 0
     or (target.unmatched_count > 0 and not target.unmatched_acknowledged) then
    raise exception using errcode = '22023', message = 'Area map version does not pass the publish gate';
  end if;

  update public.area_map_versions
  set status = 'archived', archived_at = now()
  where deployment_context = p_deployment_context and status = 'published' and id <> target.id;

  update public.area_map_versions
  set status = 'published',
      published_by_profile_id = p_actor_profile_id,
      published_at = now(),
      archived_at = null
  where id = target.id
  returning * into target;

  return target;
end;
$$;


--
-- Name: payroll_employee_summaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."payroll_employee_summaries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "payroll_period_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "regular_earning" numeric DEFAULT 0 NOT NULL,
    "overtime_earning" numeric DEFAULT 0 NOT NULL,
    "piece_rate_earning" numeric DEFAULT 0 NOT NULL,
    "allowance_amount" numeric DEFAULT 0 NOT NULL,
    "deduction_amount" numeric DEFAULT 0 NOT NULL,
    "gross_amount" numeric DEFAULT 0 NOT NULL,
    "net_amount" numeric DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "calculated_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: recalculate_payroll_employee_summary("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_payroll_employee_summary"("p_summary_id" "uuid") RETURNS "public"."payroll_employee_summaries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_summary public.payroll_employee_summaries%rowtype;
begin
  update public.payroll_employee_summaries s
  set regular_earning=coalesce((select sum(amount) from public.payroll_earning_lines e where e.payroll_summary_id=s.id and e.earning_type='regular' and e.status not in ('cancelled','rejected')),0),
      overtime_earning=coalesce((select sum(amount) from public.payroll_earning_lines e where e.payroll_summary_id=s.id and e.earning_type='overtime' and e.status not in ('cancelled','rejected')),0),
      piece_rate_earning=coalesce((select sum(amount) from public.payroll_earning_lines e where e.payroll_summary_id=s.id and e.earning_type='piece_rate' and e.status not in ('cancelled','rejected')),0),
      allowance_amount=coalesce((select sum(amount) from public.payroll_allowance_lines a where a.payroll_summary_id=s.id and a.status not in ('cancelled','rejected')),0),
      deduction_amount=coalesce((select sum(amount) from public.payroll_deduction_lines d where d.payroll_summary_id=s.id and d.status not in ('cancelled','rejected')),0),
      calculated_at=now(),updated_at=now(),
      status=case when s.status='draft' then 'calculated' else s.status end
  where s.id=p_summary_id
  returning * into v_summary;

  if not found then raise exception 'Payroll summary % not found',p_summary_id; end if;

  update public.payroll_employee_summaries
  set gross_amount=regular_earning+overtime_earning+piece_rate_earning+allowance_amount,
      net_amount=regular_earning+overtime_earning+piece_rate_earning+allowance_amount-deduction_amount,
      updated_at=now()
  where id=p_summary_id
  returning * into v_summary;

  return v_summary;
end;
$$;


--
-- Name: recalculate_survey_response("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_survey_response"("p_response_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_response public.survey_responses%rowtype;
  v_template public.survey_templates%rowtype;
  v_total numeric:=0;
  v_max numeric:=0;
  v_weighted numeric:=0;
  v_weight_sum numeric:=0;
  v_pct numeric;
  v_required integer:=0;
  v_answered integer:=0;
  v_quality numeric:=100;
  v_pass text:='not_evaluated';
begin
  select * into v_response from public.survey_responses where id=p_response_id;
  if not found then return; end if;
  select * into v_template from public.survey_templates where id=v_response.template_id;

  select coalesce(sum(coalesce(a.score_awarded,0)) filter(where q.is_scored and not coalesce(a.is_not_applicable,false)),0),
         coalesce(sum(q.max_score) filter(where q.is_scored),0),
         coalesce(sum(case when q.is_scored and q.max_score>0 and not coalesce(a.is_not_applicable,false)
                           then (coalesce(a.score_awarded,0)/q.max_score)*case when q.weight_pct>0 then q.weight_pct else q.max_score end
                           else 0 end),0),
         coalesce(sum(case when q.is_scored and not coalesce(a.is_not_applicable,false)
                           then case when q.weight_pct>0 then q.weight_pct else q.max_score end else 0 end),0),
         count(*) filter(where q.required),
         count(*) filter(where q.required and a.id is not null and not coalesce(a.is_not_applicable,false))
    into v_total,v_max,v_weighted,v_weight_sum,v_required,v_answered
  from public.survey_questions q
  left join public.survey_answers a on a.question_id=q.id and a.response_id=p_response_id
  where q.template_id=v_response.template_id and q.status='active';

  if v_template.scoring_method='none' then
    v_pct:=null;
  elsif v_template.scoring_method='weighted_average' and v_weight_sum>0 then
    v_pct:=round(v_weighted/v_weight_sum*100,2);
  elsif v_max>0 then
    v_pct:=round(v_total/v_max*100,2);
  else
    v_pct:=null;
  end if;

  if v_required>0 then v_quality:=round(v_answered::numeric/v_required*100,2); end if;
  if v_pct is not null then
    if v_pct>=v_template.minimum_pass_pct then v_pass:='passed';
    elsif v_pct>=greatest(v_template.minimum_pass_pct-10,0) then v_pass:='warning';
    else v_pass:='failed'; end if;
  end if;

  update public.survey_responses
  set template_version_snapshot=v_template.version_no,
      survey_scope=v_template.survey_scope,
      score_total=round(v_total,2),score_max=round(v_max,2),score_pct=v_pct,
      pass_status=v_pass,data_quality_pct=v_quality,updated_at=now()
  where id=p_response_id;

  perform public.refresh_survey_target_summary(v_response.work_order_id,v_response.work_result_id);
end;
$$;


--
-- Name: recalculate_work_performance("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."recalculate_work_performance"("p_work_result_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_wr record;
  v_std record;
  v_worker record;
  v_worker_count integer := 0;
  v_total_worker_hours numeric := 0;
  v_quantity numeric := 0;
  v_area numeric := 0;
  v_trees numeric := 0;
  v_labor_hours numeric := 0;
  v_labor_days numeric := 0;
  v_quality numeric := 100;
  v_completion numeric := 100;
  v_person_output numeric;
  v_tree_output numeric;
  v_area_output numeric;
  v_hour_output numeric;
  v_person_eff numeric;
  v_tree_eff numeric;
  v_area_eff numeric;
  v_time_eff numeric;
  v_output_weight numeric;
  v_quantity_eff numeric;
  v_composite_weight numeric;
  v_composite_eff numeric;
  v_quality_adjusted numeric;
  v_capped_eff numeric;
  v_data_quality numeric;
  v_outlier boolean;
  v_outlier_reason text;
  v_share numeric;
  v_worker_quantity numeric;
  v_worker_area numeric;
  v_worker_trees numeric;
  v_worker_labor_days numeric;
  v_worker_quality numeric;
  v_worker_completion numeric;
  v_worker_estimated boolean;
  v_worker_data_quality numeric;
  v_worker_quantity_eff numeric;
  v_worker_composite_eff numeric;
  v_worker_adjusted numeric;
  v_worker_capped numeric;
  v_worker_output_weight numeric;
  v_worker_composite_weight numeric;
begin
  delete from public.work_performance_metrics where work_result_id = p_work_result_id;

  select wr.*,
         wo.activity_id,
         wo.block_id,
         wo.team_id as work_order_team_id,
         b.terrain_type as block_terrain_type,
         b.rspo_status as block_rspo_status
    into v_wr
  from public.work_results wr
  join public.work_orders wo on wo.id = wr.work_order_id
  left join public.blocks b on b.id = wo.block_id
  where wr.id = p_work_result_id;

  if not found or v_wr.activity_id is null or v_wr.result_date is null then
    return;
  end if;

  select s.*
    into v_std
  from public.activity_performance_standards s
  left join public.budget_years byear on byear.id = s.budget_year_id
  where s.activity_id = v_wr.activity_id
    and s.status = 'approved'
    and s.effective_from <= v_wr.result_date
    and (s.effective_to is null or s.effective_to >= v_wr.result_date)
    and (s.condition_group = v_wr.condition_group or s.condition_group = 'default')
    and (
      s.budget_year_id is null
      or (coalesce(byear.effective_from, s.effective_from) <= v_wr.result_date
          and coalesce(byear.effective_to, s.effective_to, v_wr.result_date) >= v_wr.result_date)
    )
  order by
    case when s.condition_group = v_wr.condition_group then 0 else 1 end,
    case when s.budget_year_id is not null then 0 else 1 end,
    s.version_no desc,
    s.effective_from desc
  limit 1;

  if not found then
    return;
  end if;

  select count(*), coalesce(sum(actual_hours),0)
    into v_worker_count, v_total_worker_hours
  from public.work_result_workers
  where work_result_id = p_work_result_id;

  v_quantity := coalesce(v_wr.actual_quantity,0);
  v_area := coalesce(v_wr.actual_area_rai,0);
  v_trees := coalesce(v_wr.actual_tree_count,0);
  v_labor_hours := coalesce(nullif(v_wr.total_labor_hours,0), v_total_worker_hours, 0);
  v_labor_days := coalesce(
    nullif(v_wr.total_labor_days,0),
    case when v_labor_hours > 0 then v_labor_hours / v_std.standard_hours_per_person_day end,
    case when coalesce(v_wr.worker_count, v_worker_count, 0) > 0 then coalesce(v_wr.worker_count, v_worker_count)::numeric end,
    0
  );
  v_quality := coalesce(v_wr.quality_score,100);
  v_completion := coalesce(v_wr.completion_pct,100);

  v_person_output := case when v_labor_days > 0 then v_quantity / v_labor_days end;
  v_tree_output := case when v_trees > 0 then v_quantity / v_trees end;
  v_area_output := case when v_area > 0 then v_quantity / v_area end;
  v_hour_output := case when v_labor_hours > 0 then v_quantity / v_labor_hours end;

  v_person_eff := public.performance_efficiency_pct(v_person_output, v_std.standard_per_person, v_std.person_direction);
  v_tree_eff := public.performance_efficiency_pct(v_tree_output, v_std.standard_per_tree, v_std.tree_direction);
  v_area_eff := public.performance_efficiency_pct(v_area_output, v_std.standard_per_rai, v_std.area_direction);
  v_time_eff := public.performance_efficiency_pct(v_hour_output, v_std.standard_per_hour, v_std.time_direction);

  v_output_weight :=
    case when v_person_eff is not null then v_std.person_weight_pct else 0 end +
    case when v_tree_eff is not null then v_std.tree_weight_pct else 0 end +
    case when v_area_eff is not null then v_std.area_weight_pct else 0 end +
    case when v_time_eff is not null then v_std.time_weight_pct else 0 end;

  v_quantity_eff := case when v_output_weight > 0 then (
    coalesce(v_person_eff * v_std.person_weight_pct,0) +
    coalesce(v_tree_eff * v_std.tree_weight_pct,0) +
    coalesce(v_area_eff * v_std.area_weight_pct,0) +
    coalesce(v_time_eff * v_std.time_weight_pct,0)
  ) / v_output_weight end;

  v_composite_weight := v_output_weight + case when v_quality is not null then v_std.quality_weight_pct else 0 end;
  v_composite_eff := case when v_composite_weight > 0 then (
    coalesce(v_person_eff * v_std.person_weight_pct,0) +
    coalesce(v_tree_eff * v_std.tree_weight_pct,0) +
    coalesce(v_area_eff * v_std.area_weight_pct,0) +
    coalesce(v_time_eff * v_std.time_weight_pct,0) +
    coalesce(v_quality * v_std.quality_weight_pct,0)
  ) / v_composite_weight end;

  v_quality_adjusted := case when v_quantity_eff is not null then v_quantity_eff * least(greatest(v_quality,0),100) / 100 end;
  v_capped_eff := case when v_composite_eff is not null then least(v_std.efficiency_ceiling_pct, greatest(v_std.efficiency_floor_pct, v_composite_eff)) end;

  v_data_quality := 100;
  if v_quantity <= 0 then v_data_quality := v_data_quality - 40; end if;
  if v_std.standard_per_person is not null and v_labor_days <= 0 then v_data_quality := v_data_quality - 20; end if;
  if v_std.standard_per_tree is not null and v_trees <= 0 then v_data_quality := v_data_quality - 15; end if;
  if v_std.standard_per_rai is not null and v_area <= 0 then v_data_quality := v_data_quality - 15; end if;
  if v_wr.quality_score is null then v_data_quality := v_data_quality - 10; end if;
  v_data_quality := least(100, greatest(0, coalesce(v_wr.data_quality_pct, v_data_quality)));

  v_outlier := coalesce(v_composite_eff < 50 or v_composite_eff > 150 or v_quality < 60, false);
  v_outlier_reason := case
    when v_quality < 60 then 'quality_below_60'
    when v_composite_eff > 150 then 'efficiency_above_150'
    when v_composite_eff < 50 then 'efficiency_below_50'
    else null
  end;

  insert into public.work_performance_metrics (
    metric_scope, work_result_id, activity_id, team_id, block_id, work_date,
    standard_id, condition_group, actual_quantity, actual_unit, labor_hours,
    labor_days, area_rai, tree_count, person_output, tree_output, area_output,
    hour_output, person_efficiency_pct, tree_efficiency_pct, area_efficiency_pct,
    time_efficiency_pct, quantity_efficiency_pct, quality_pct, completion_pct,
    quality_adjusted_efficiency_pct, composite_efficiency_pct, capped_efficiency_pct,
    data_quality_pct, is_estimated, outlier_flag, outlier_reason, is_budget_eligible
  ) values (
    'result', p_work_result_id, v_wr.activity_id, v_wr.work_order_team_id, v_wr.block_id, v_wr.result_date,
    v_std.id, v_wr.condition_group, v_quantity, v_wr.actual_unit, v_labor_hours,
    v_labor_days, v_area, v_trees, v_person_output, v_tree_output, v_area_output,
    v_hour_output, v_person_eff, v_tree_eff, v_area_eff,
    v_time_eff, v_quantity_eff, v_quality, v_completion,
    v_quality_adjusted, v_composite_eff, v_capped_eff,
    v_data_quality, false, v_outlier, v_outlier_reason,
    (v_wr.result_status in ('verified','closed','approved','completed')
      and not v_outlier
      and v_data_quality >= v_std.minimum_data_quality_pct)
  );

  for v_worker in
    select * from public.work_result_workers where work_result_id = p_work_result_id
  loop
    v_share := case
      when v_total_worker_hours > 0 and v_worker.actual_hours > 0 then v_worker.actual_hours / v_total_worker_hours
      when v_worker_count > 0 then 1::numeric / v_worker_count
      else 1
    end;

    v_worker_estimated := coalesce(v_worker.is_quantity_estimated,false) or coalesce(v_worker.actual_quantity,0) <= 0;
    v_worker_quantity := case when coalesce(v_worker.actual_quantity,0) > 0 then v_worker.actual_quantity else v_quantity * v_share end;
    v_worker_area := case when coalesce(v_worker.actual_area_rai,0) > 0 then v_worker.actual_area_rai else v_area * v_share end;
    v_worker_trees := case when coalesce(v_worker.actual_tree_count,0) > 0 then v_worker.actual_tree_count else v_trees * v_share end;
    v_worker_labor_days := case
      when coalesce(v_worker.actual_hours,0) > 0 then v_worker.actual_hours / v_std.standard_hours_per_person_day
      else greatest(v_labor_days * v_share,0)
    end;
    v_worker_quality := coalesce(v_worker.individual_quality_pct, v_quality);
    v_worker_completion := coalesce(v_worker.individual_completion_pct, v_completion);

    v_person_output := case when v_worker_labor_days > 0 then v_worker_quantity / v_worker_labor_days end;
    v_tree_output := case when v_worker_trees > 0 then v_worker_quantity / v_worker_trees end;
    v_area_output := case when v_worker_area > 0 then v_worker_quantity / v_worker_area end;
    v_hour_output := case when coalesce(v_worker.actual_hours,0) > 0 then v_worker_quantity / v_worker.actual_hours end;

    v_person_eff := public.performance_efficiency_pct(v_person_output, v_std.standard_per_person, v_std.person_direction);
    v_tree_eff := public.performance_efficiency_pct(v_tree_output, v_std.standard_per_tree, v_std.tree_direction);
    v_area_eff := public.performance_efficiency_pct(v_area_output, v_std.standard_per_rai, v_std.area_direction);
    v_time_eff := public.performance_efficiency_pct(v_hour_output, v_std.standard_per_hour, v_std.time_direction);

    v_worker_output_weight :=
      case when v_person_eff is not null then v_std.person_weight_pct else 0 end +
      case when v_tree_eff is not null then v_std.tree_weight_pct else 0 end +
      case when v_area_eff is not null then v_std.area_weight_pct else 0 end +
      case when v_time_eff is not null then v_std.time_weight_pct else 0 end;

    v_worker_quantity_eff := case when v_worker_output_weight > 0 then (
      coalesce(v_person_eff * v_std.person_weight_pct,0) +
      coalesce(v_tree_eff * v_std.tree_weight_pct,0) +
      coalesce(v_area_eff * v_std.area_weight_pct,0) +
      coalesce(v_time_eff * v_std.time_weight_pct,0)
    ) / v_worker_output_weight end;

    v_worker_composite_weight := v_worker_output_weight + case when v_worker_quality is not null then v_std.quality_weight_pct else 0 end;
    v_worker_composite_eff := case when v_worker_composite_weight > 0 then (
      coalesce(v_person_eff * v_std.person_weight_pct,0) +
      coalesce(v_tree_eff * v_std.tree_weight_pct,0) +
      coalesce(v_area_eff * v_std.area_weight_pct,0) +
      coalesce(v_time_eff * v_std.time_weight_pct,0) +
      coalesce(v_worker_quality * v_std.quality_weight_pct,0)
    ) / v_worker_composite_weight end;

    v_worker_adjusted := case when v_worker_quantity_eff is not null then v_worker_quantity_eff * least(greatest(v_worker_quality,0),100) / 100 end;
    v_worker_capped := case when v_worker_composite_eff is not null then least(v_std.efficiency_ceiling_pct, greatest(v_std.efficiency_floor_pct, v_worker_composite_eff)) end;
    v_worker_data_quality := greatest(0, v_data_quality - case when v_worker_estimated then 15 else 0 end);

    insert into public.work_performance_metrics (
      metric_scope, work_result_id, work_result_worker_id, activity_id, employee_id,
      team_id, block_id, work_date, standard_id, condition_group, actual_quantity,
      actual_unit, labor_hours, labor_days, area_rai, tree_count, person_output,
      tree_output, area_output, hour_output, person_efficiency_pct,
      tree_efficiency_pct, area_efficiency_pct, time_efficiency_pct,
      quantity_efficiency_pct, quality_pct, completion_pct,
      quality_adjusted_efficiency_pct, composite_efficiency_pct,
      capped_efficiency_pct, data_quality_pct, is_estimated, outlier_flag,
      outlier_reason, is_budget_eligible
    ) values (
      'employee', p_work_result_id, v_worker.id, v_wr.activity_id, v_worker.employee_id,
      coalesce(v_worker.team_id, v_wr.work_order_team_id), v_wr.block_id, v_worker.work_date,
      v_std.id, v_wr.condition_group, v_worker_quantity, coalesce(v_worker.actual_unit,v_wr.actual_unit),
      coalesce(v_worker.actual_hours,0), v_worker_labor_days, v_worker_area, v_worker_trees,
      v_person_output, v_tree_output, v_area_output, v_hour_output, v_person_eff,
      v_tree_eff, v_area_eff, v_time_eff, v_worker_quantity_eff, v_worker_quality,
      v_worker_completion, v_worker_adjusted, v_worker_composite_eff,
      v_worker_capped, v_worker_data_quality, v_worker_estimated,
      coalesce(v_worker_composite_eff < 50 or v_worker_composite_eff > 150 or v_worker_quality < 60,false),
      case
        when v_worker_quality < 60 then 'quality_below_60'
        when v_worker_composite_eff > 150 then 'efficiency_above_150'
        when v_worker_composite_eff < 50 then 'efficiency_below_50'
        when v_worker_estimated then 'quantity_estimated'
        else null
      end,
      false
    );
  end loop;
end;
$$;


--
-- Name: goods_issue_daily_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."goods_issue_daily_usage" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "goods_issue_id" "uuid" NOT NULL,
    "goods_issue_line_id" "uuid" NOT NULL,
    "work_order_id" "uuid",
    "work_result_id" "uuid",
    "usage_date" "date" NOT NULL,
    "material_id" "uuid" NOT NULL,
    "quantity" numeric NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "issue_unit_quantity" numeric NOT NULL,
    "issue_unit_id" "uuid" NOT NULL,
    "base_quantity" numeric NOT NULL,
    "base_unit_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'posted'::"text" NOT NULL,
    "idempotency_key" "text",
    "recorded_by_profile_id" "uuid",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "request_hash" "text",
    CONSTRAINT "goods_issue_daily_usage_base_quantity_check" CHECK (("base_quantity" > (0)::numeric)),
    CONSTRAINT "goods_issue_daily_usage_issue_unit_quantity_check" CHECK (("issue_unit_quantity" > (0)::numeric)),
    CONSTRAINT "goods_issue_daily_usage_quantity_check" CHECK (("quantity" > (0)::numeric))
);


