-- Name: TABLE "goods_issue_daily_usage"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE "public"."goods_issue_daily_usage" IS 'การใช้วัสดุรายวันภายใต้ใบจ่ายเดียว รองรับงานต่อเนื่องหลายวัน';


--
-- Name: record_goods_issue_daily_usage("uuid", "uuid", "date", "uuid", "uuid", numeric, "uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_goods_issue_daily_usage"("p_issue_id" "uuid", "p_issue_line_id" "uuid", "p_usage_date" "date", "p_work_result_id" "uuid", "p_material_id" "uuid", "p_quantity" numeric, "p_unit_id" "uuid", "p_profile_id" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "public"."goods_issue_daily_usage"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_issue public.goods_issues;
  v_line public.goods_issue_lines;
  v_material public.materials;
  v_result public.work_results;
  v_issue_qty numeric;
  v_base_qty numeric;
  v_used numeric;
  v_returned numeric;
  v_hash text;
  v_row public.goods_issue_daily_usage;
begin
  if p_quantity is null or p_quantity<=0 then
    raise exception 'INVALID_USAGE_QUANTITY';
  end if;

  select * into v_issue
  from public.goods_issues
  where id=p_issue_id
  for update;
  if not found then raise exception 'GOODS_ISSUE_NOT_FOUND'; end if;
  if v_issue.status<>'posted' then raise exception 'GOODS_ISSUE_NOT_POSTED'; end if;
  if v_issue.usage_status='closed' then raise exception 'GOODS_ISSUE_USAGE_CLOSED'; end if;
  if p_usage_date<coalesce(v_issue.issue_start_date,v_issue.issue_date)
     or p_usage_date>coalesce(v_issue.issue_end_date,v_issue.issue_date) then
    raise exception 'USAGE_DATE_OUTSIDE_ISSUE_PERIOD';
  end if;

  select * into v_line
  from public.goods_issue_lines
  where id=p_issue_line_id
  for update;
  if not found or v_line.issue_id is distinct from p_issue_id then
    raise exception 'GOODS_ISSUE_LINE_NOT_MATCH_ISSUE';
  end if;
  if v_line.material_id is distinct from p_material_id then
    raise exception 'MATERIAL_NOT_IN_GOODS_ISSUE';
  end if;

  if p_work_result_id is not null then
    select * into v_result
    from public.work_results
    where id=p_work_result_id;
    if not found then raise exception 'WORK_RESULT_NOT_FOUND'; end if;
    if v_result.work_order_id is distinct from v_issue.work_order_id then
      raise exception 'WORK_RESULT_NOT_MATCH_ISSUE';
    end if;
  end if;

  select * into v_material
  from public.materials
  where id=p_material_id;
  if not found then raise exception 'MATERIAL_NOT_FOUND'; end if;

  v_issue_qty:=public.convert_material_quantity(
    p_material_id,p_quantity,p_unit_id,v_line.unit_id
  );
  v_base_qty:=public.convert_material_quantity(
    p_material_id,p_quantity,p_unit_id,v_material.base_unit_id
  );
  v_hash:=md5(jsonb_build_object(
    'issue_id',p_issue_id,
    'issue_line_id',p_issue_line_id,
    'usage_date',p_usage_date,
    'work_result_id',p_work_result_id,
    'material_id',p_material_id,
    'quantity',p_quantity,
    'unit_id',p_unit_id,
    'note',p_note
  )::text);

  if p_idempotency_key is not null then
    select * into v_row
    from public.goods_issue_daily_usage
    where goods_issue_id=p_issue_id
      and idempotency_key=p_idempotency_key;
    if found then
      if v_row.request_hash is distinct from v_hash then
        raise exception 'IDEMPOTENCY_PAYLOAD_MISMATCH';
      end if;
      return v_row;
    end if;
  end if;

  select coalesce(sum(issue_unit_quantity),0) into v_used
  from public.goods_issue_daily_usage
  where goods_issue_line_id=v_line.id
    and status='posted';

  select coalesce(sum(
    public.convert_material_quantity(
      p_material_id,grl.quantity,grl.unit_id,v_line.unit_id
    )
  ),0) into v_returned
  from public.goods_return_lines grl
  join public.goods_returns gr on gr.id=grl.return_id
  where grl.goods_issue_line_id=v_line.id
    and gr.status='posted';

  if v_used+v_returned+v_issue_qty>v_line.quantity+0.000001 then
    raise exception 'USAGE_EXCEEDS_AVAILABLE_ISSUED_QUANTITY';
  end if;

  insert into public.goods_issue_daily_usage(
    goods_issue_id,goods_issue_line_id,work_order_id,work_result_id,
    usage_date,material_id,quantity,unit_id,issue_unit_quantity,
    issue_unit_id,base_quantity,base_unit_id,idempotency_key,
    request_hash,recorded_by_profile_id,note
  ) values(
    p_issue_id,v_line.id,v_issue.work_order_id,p_work_result_id,
    p_usage_date,p_material_id,p_quantity,p_unit_id,v_issue_qty,
    v_line.unit_id,v_base_qty,v_material.base_unit_id,p_idempotency_key,
    v_hash,p_profile_id,p_note
  ) returning * into v_row;

  update public.work_order_materials wom
  set used_quantity=coalesce((
      select sum(public.convert_material_quantity(
        u.material_id,u.quantity,u.unit_id,wom.unit_id
      ))
      from public.goods_issue_daily_usage u
      where u.work_order_id=wom.work_order_id
        and u.material_id=wom.material_id
        and u.status='posted'
    ),0),
    updated_at=now()
  where wom.work_order_id=v_issue.work_order_id
    and wom.material_id=p_material_id;

  return v_row;
exception
  when unique_violation then
    if p_idempotency_key is not null then
      select * into v_row
      from public.goods_issue_daily_usage
      where goods_issue_id=p_issue_id
        and idempotency_key=p_idempotency_key;
      if found and v_row.request_hash is not distinct from v_hash then
        return v_row;
      end if;
      if found then raise exception 'IDEMPOTENCY_PAYLOAD_MISMATCH'; end if;
    end if;
    raise;
end;
$$;


--
-- Name: refresh_canonical_planned_work_item_snapshot("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_canonical_planned_work_item_snapshot"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid", "p_refresh_request_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_item public.planned_work_items%rowtype;
  v_request public.planning_material_snapshot_requests%rowtype;
  v_annual_plan_id uuid;
  v_material_count integer := 0;
  v_snapshot_at timestamptz := transaction_timestamp();
  v_request_key text := nullif(btrim(p_refresh_request_key), '');
  v_plan_year integer;
  v_budget_fiscal_year text;
begin
  if v_request_key is null or char_length(v_request_key) > 200 then
    raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_INVALID';
  end if;

  if p_actor_profile_id is null or not exists (
    select 1
    from public.profiles profile
    where profile.id = p_actor_profile_id
      and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select planned_item.annual_plan_id
  into v_annual_plan_id
  from public.planned_work_items planned_item
  where planned_item.id = p_planned_work_item_id;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;

  insert into public.planning_material_snapshot_requests (
    request_key,
    planned_work_item_id,
    actor_profile_id,
    snapshot_at,
    material_count,
    completed_at
  )
  values (
    v_request_key,
    p_planned_work_item_id,
    p_actor_profile_id,
    v_snapshot_at,
    0,
    v_snapshot_at
  )
  on conflict (request_key) do nothing
  returning * into v_request;

  if not found then
    select request_row.*
    into v_request
    from public.planning_material_snapshot_requests request_row
    where request_row.request_key = v_request_key
    for key share;

    if not found
      or v_request.planned_work_item_id is distinct from p_planned_work_item_id
      or v_request.actor_profile_id is distinct from p_actor_profile_id
    then
      raise exception using errcode = 'P0001', message = 'PLANNING_REQUEST_KEY_REUSED';
    end if;

    select planned_item.*
    into v_item
    from public.planned_work_items planned_item
    where planned_item.id = p_planned_work_item_id;

    return jsonb_build_object(
      'planned_work_item', to_jsonb(v_item),
      'material_count', v_request.material_count,
      'snapshot_at', v_request.snapshot_at,
      'already_exists', true
    );
  end if;

  select annual_plan.plan_year
  into v_plan_year
  from public.annual_work_plans annual_plan
  where annual_plan.id = v_annual_plan_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;
  if not exists (
    select 1
    from public.annual_work_plans annual_plan
    where annual_plan.id = v_annual_plan_id
      and annual_plan.status = 'draft'
  ) then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;

  select planned_item.*
  into v_item
  from public.planned_work_items planned_item
  where planned_item.id = p_planned_work_item_id
    and planned_item.annual_plan_id = v_annual_plan_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;

  if v_item.source_type is distinct from 'canonical_budget'
    or v_item.source_budget_year_id is null
    or v_item.source_budget_activity_rate_id is null
    or v_item.source_budget_rate_block_id is null
    or v_item.block_id is null
    or v_item.activity_id is null
    or v_item.planning_request_key is null
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
  end if;

  select budget_year.fiscal_year
  into v_budget_fiscal_year
  from public.budget_years budget_year
  where budget_year.id = v_item.source_budget_year_id
  for share;
  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_YEAR_NOT_ELIGIBLE';
  end if;
  if nullif(btrim(v_budget_fiscal_year), '') is null
    or btrim(v_budget_fiscal_year) !~ '^[0-9]+$'
    or v_plan_year::text <> btrim(v_budget_fiscal_year)
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_BUDGET_YEAR_PLAN_MISMATCH';
  end if;

  perform set_config('app.phase2c_snapshot_rpc', 'on', true);

  delete from public.planned_work_materials material_snapshot
  where material_snapshot.planned_work_item_id = v_item.id
    and material_snapshot.snapshot_source_type = 'canonical_budget_block_material';

  v_material_count := public.populate_canonical_planning_material_snapshot(
    v_item.id,
    v_item.source_budget_year_id,
    v_item.source_budget_activity_rate_id,
    v_item.source_budget_rate_block_id,
    v_item.block_id,
    v_item.activity_id,
    v_snapshot_at
  );

  update public.planned_work_items
  set updated_at = v_snapshot_at
  where id = v_item.id
  returning * into v_item;

  update public.planning_material_snapshot_requests request_row
  set material_count = v_material_count
  where request_row.request_key = v_request_key
  returning * into v_request;

  return jsonb_build_object(
    'planned_work_item', to_jsonb(v_item),
    'material_count', v_material_count,
    'snapshot_at', v_snapshot_at,
    'already_exists', false
  );
end
$_$;


--
-- Name: FUNCTION "refresh_canonical_planned_work_item_snapshot"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid", "p_refresh_request_key" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."refresh_canonical_planned_work_item_snapshot"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid", "p_refresh_request_key" "text") IS 'Atomic service-only replacement of a draft canonical Planning Material snapshot with durable request-key idempotency.';


--
-- Name: refresh_fuel_tank_purchase_requisition("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_fuel_tank_purchase_requisition"("p_tank_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_balance numeric;
  v_capacity numeric;
  v_reorder numeric;
  v_safety numeric;
  v_target_pct numeric;
  v_target numeric;
  v_projected numeric;
  v_recommended numeric;
  v_existing uuid;
  v_new_id uuid;
begin
  if not public.fuel_setting_boolean('fuel.auto_tank_purchase_requisition_enabled', true) then
    return null;
  end if;

  select current_balance_liter, capacity_liter, reorder_point_liter,
         safety_stock_liter, target_fill_percent
  into v_balance, v_capacity, v_reorder, v_safety, v_target_pct
  from public.fuel_tanks
  where id = p_tank_id and status = 'active';

  if not found or coalesce(v_capacity,0) <= 0 then return null; end if;

  select coalesce(sum(greatest(coalesce(approved_liter,requested_liter) - coalesce(issued_liter,0),0)),0)
  into v_projected
  from public.fuel_requisitions
  where source_tank_id = p_tank_id
    and status in ('approved','partially_issued');

  v_target := least(v_capacity, v_capacity * coalesce(v_target_pct,90) / 100.0);
  v_recommended := greatest(v_target - coalesce(v_balance,0),
                             v_projected + coalesce(v_safety,0) - coalesce(v_balance,0),0);
  v_recommended := least(v_recommended, greatest(v_capacity - coalesce(v_balance,0),0));

  if not (coalesce(v_balance,0) <= coalesce(v_reorder,0)
          or coalesce(v_balance,0) - v_projected < coalesce(v_safety,0))
     or v_recommended <= 0 then
    return null;
  end if;

  select id into v_existing
  from public.fuel_tank_purchase_requisitions
  where tank_id = p_tank_id
    and status in ('suggested','draft','pending','approved','ordered','partially_received')
  order by created_at desc limit 1;

  if v_existing is not null then
    update public.fuel_tank_purchase_requisitions
    set current_balance_liter = coalesce(v_balance,0),
        projected_issue_liter = coalesce(v_projected,0),
        safety_stock_liter_snapshot = coalesce(v_safety,0),
        target_balance_liter = v_target,
        recommended_liter = round(v_recommended,2),
        requested_liter = case when status = 'suggested' then round(v_recommended,2) else requested_liter end,
        updated_at = now()
    where id = v_existing;
    return v_existing;
  end if;

  insert into public.fuel_tank_purchase_requisitions(
    purchase_requisition_no, tank_id, request_source,
    current_balance_liter, projected_issue_liter,
    safety_stock_liter_snapshot, target_balance_liter,
    recommended_liter, requested_liter, status, reason
  ) values (
    'FPUR-' || to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS') || '-' || left(replace(p_tank_id::text,'-',''),6),
    p_tank_id, 'auto_reorder', coalesce(v_balance,0), coalesce(v_projected,0),
    coalesce(v_safety,0), v_target, round(v_recommended,2), round(v_recommended,2),
    'suggested', 'น้ำมันถังกลางต่ำกว่าจุดสั่งซื้อหรือไม่พอกับคำขอที่อนุมัติแล้ว'
  ) returning id into v_new_id;

  return v_new_id;
end;
$$;


--
-- Name: refresh_survey_target_summary("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_survey_target_summary"("p_work_order_id" "uuid", "p_work_result_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_work_result_id is not null then
    update public.work_results wr
    set survey_response_count=x.response_count,
        survey_score_pct=x.average_score,
        survey_status=x.summary_status,
        survey_last_at=x.last_at,
        updated_at=now()
    from (
      select count(*) filter(where status<>'cancelled')::integer response_count,
             round(avg(score_pct) filter(where status in ('submitted','verified','closed') and score_pct is not null),2) average_score,
             case
               when count(*) filter(where status in ('draft','submitted'))>0 then 'pending'
               when count(*) filter(where pass_status='failed' and status in ('verified','closed'))>0 then 'failed'
               when count(*) filter(where status in ('verified','closed'))>0 then 'completed'
               else 'not_required'
             end summary_status,
             max(updated_at) last_at
      from public.survey_responses where work_result_id=p_work_result_id
    ) x
    where wr.id=p_work_result_id;
  end if;

  if p_work_order_id is not null then
    update public.work_orders wo
    set survey_response_count=x.response_count,
        survey_score_pct=x.average_score,
        survey_status=x.summary_status,
        survey_last_at=x.last_at,
        updated_at=now()
    from (
      select count(*) filter(where status<>'cancelled')::integer response_count,
             round(avg(score_pct) filter(where status in ('submitted','verified','closed') and score_pct is not null),2) average_score,
             case
               when count(*) filter(where status in ('draft','submitted'))>0 then 'pending'
               when count(*) filter(where pass_status='failed' and status in ('verified','closed'))>0 then 'failed'
               when count(*) filter(where status in ('verified','closed'))>0 then 'completed'
               when bool_or(required) then 'required'
               else 'not_required'
             end summary_status,
             max(updated_at) last_at
      from (
        select r.*,coalesce(a.required,false) required
        from public.survey_responses r
        left join public.survey_template_assignments a on a.template_id=r.template_id
        where r.work_order_id=p_work_order_id
      ) q
    ) x
    where wo.id=p_work_order_id;
  end if;
end;
$$;


--
-- Name: refresh_vehicle_fuel_requisition("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_vehicle_fuel_requisition"("p_vehicle_id" "uuid", "p_work_order_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_balance numeric;
  v_capacity numeric;
  v_reorder numeric;
  v_safety numeric;
  v_target_pct numeric;
  v_target numeric;
  v_projected numeric;
  v_projected_balance numeric;
  v_recommended numeric;
  v_existing uuid;
  v_new_id uuid;
begin
  if not public.fuel_setting_boolean('fuel.auto_vehicle_requisition_enabled', true) then
    return null;
  end if;

  select b.current_estimated_liter,
         v.tank_capacity_liter,
         v.reorder_point_liter,
         v.safety_stock_liter,
         v.target_fill_percent
  into v_balance, v_capacity, v_reorder, v_safety, v_target_pct
  from public.vehicles v
  join public.vehicle_fuel_balances b on b.vehicle_id = v.id
  where v.id = p_vehicle_id and v.status = 'active';

  if not found or coalesce(v_capacity,0) <= 0 then
    return null;
  end if;

  select coalesce(sum(greatest(coalesce(m.fuel_plan_liter,0) - coalesce(m.fuel_actual_liter,0),0)),0)
  into v_projected
  from public.work_order_machines m
  join public.work_orders w on w.id = m.work_order_id
  where m.vehicle_id = p_vehicle_id
    and m.status not in ('cancelled','closed')
    and w.status not in ('cancelled','closed','completed','done');

  v_target := least(v_capacity, v_capacity * coalesce(v_target_pct,90) / 100.0);
  v_projected_balance := coalesce(v_balance,0) - coalesce(v_projected,0);
  v_recommended := greatest(
    v_target - coalesce(v_balance,0),
    coalesce(v_projected,0) + coalesce(v_safety,0) - coalesce(v_balance,0),
    0
  );
  v_recommended := least(v_recommended, greatest(v_capacity - coalesce(v_balance,0),0));

  if not (coalesce(v_balance,0) <= coalesce(v_reorder,0)
          or v_projected_balance < coalesce(v_safety,0))
     or v_recommended <= 0 then
    return null;
  end if;

  select id into v_existing
  from public.fuel_requisitions
  where vehicle_id = p_vehicle_id
    and status in ('suggested','draft','pending','approved','partially_issued')
  order by created_at desc
  limit 1;

  if v_existing is not null then
    update public.fuel_requisitions
    set current_vehicle_fuel_liter = coalesce(v_balance,0),
        projected_usage_liter = coalesce(v_projected,0),
        projected_balance_liter = v_projected_balance,
        safety_stock_liter_snapshot = coalesce(v_safety,0),
        target_balance_liter = v_target,
        recommended_liter = round(v_recommended,2),
        requested_liter = case when status = 'suggested' then round(v_recommended,2) else requested_liter end,
        work_order_id = coalesce(work_order_id,p_work_order_id),
        updated_at = now()
    where id = v_existing;
    return v_existing;
  end if;

  insert into public.fuel_requisitions(
    requisition_no, work_order_id, vehicle_id, requested_for_date,
    request_source, reason, current_vehicle_fuel_liter,
    projected_usage_liter, projected_balance_liter,
    safety_stock_liter_snapshot, target_balance_liter,
    recommended_liter, requested_liter, status
  ) values (
    'FREQ-' || to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS') || '-' || left(replace(p_vehicle_id::text,'-',''),6),
    p_work_order_id, p_vehicle_id, current_date,
    'auto_reorder', 'น้ำมันคงเหลือต่ำกว่าจุดสั่งเติมหรือไม่พอกับงานที่แจกแล้ว',
    coalesce(v_balance,0), coalesce(v_projected,0), v_projected_balance,
    coalesce(v_safety,0), v_target, round(v_recommended,2), round(v_recommended,2), 'suggested'
  ) returning id into v_new_id;

  return v_new_id;
end;
$$;


--
-- Name: refresh_work_result_weight_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_work_result_weight_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  target_result_id uuid;
begin
  target_result_id := coalesce(new.work_result_id,old.work_result_id);

  update public.work_results wr
  set actual_quantity=coalesce(x.total_weight,0),
      actual_unit='kg',
      weigh_ticket_count=coalesce(x.ticket_count,0),
      source_type=case when coalesce(x.ticket_count,0)>0 then 'weighbridge' else 'manual' end,
      updated_at=now()
  from (
    select
      target_result_id as work_result_id,
      coalesce(sum(allocated_weight_kg) filter (where link_status <> 'cancelled'),0) total_weight,
      count(*) filter (where link_status <> 'cancelled') ticket_count
    from public.work_result_weight_tickets
    where work_result_id=target_result_id
  ) x
  where wr.id=x.work_result_id;

  if tg_op='UPDATE' and old.work_result_id is distinct from new.work_result_id then
    update public.work_results wr
    set actual_quantity=coalesce(x.total_weight,0),
        actual_unit=case when coalesce(x.ticket_count,0)>0 then 'kg' else wr.actual_unit end,
        weigh_ticket_count=coalesce(x.ticket_count,0),
        source_type=case when coalesce(x.ticket_count,0)>0 then 'weighbridge' else 'manual' end,
        updated_at=now()
    from (
      select
        old.work_result_id as work_result_id,
        coalesce(sum(allocated_weight_kg) filter (where link_status <> 'cancelled'),0) total_weight,
        count(*) filter (where link_status <> 'cancelled') ticket_count
      from public.work_result_weight_tickets
      where work_result_id=old.work_result_id
    ) x
    where wr.id=x.work_result_id;
  end if;

  return coalesce(new,old);
end;
$$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


--
-- Name: rollback_area_map_version("uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rollback_area_map_version"("p_source_version_id" "uuid", "p_deployment_context" "text", "p_actor_profile_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."area_map_versions"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  source public.area_map_versions;
  restored public.area_map_versions;
begin
  if nullif(trim(p_deployment_context), '') is null then
    raise exception using errcode = '22023', message = 'deployment context is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('area-map:' || p_deployment_context, 0));

  select * into source
  from public.area_map_versions
  where id = p_source_version_id and deployment_context = p_deployment_context
  for update;

  if source.id is null then
    raise exception using errcode = 'P0002', message = 'Rollback source version not found';
  end if;
  if source.processed_storage_path is null
     or source.feature_count <= 0
     or jsonb_typeof(source.validation_errors) <> 'array'
     or jsonb_array_length(source.validation_errors) > 0
     or source.duplicate_count > 0
     or source.conflict_count > 0 then
    raise exception using errcode = '22023', message = 'Rollback source is not a valid published artifact';
  end if;

  insert into public.area_map_versions (
    deployment_context, status, source_version_id, original_file_name,
    raw_storage_path, processed_storage_path, sha256, file_size_bytes,
    feature_count, matched_count, unmatched_count, master_without_map_count,
    duplicate_count, conflict_count, bounds, source_metadata,
    reconciliation_summary, validation_errors, unmatched_acknowledged,
    uploaded_by_profile_id
  ) values (
    p_deployment_context, 'validated', source.id, source.original_file_name,
    source.raw_storage_path, source.processed_storage_path, source.sha256, source.file_size_bytes,
    source.feature_count, source.matched_count, source.unmatched_count, source.master_without_map_count,
    source.duplicate_count, source.conflict_count, source.bounds,
    source.source_metadata || jsonb_build_object(
      'rollbackOfVersionId', source.id,
      'rollbackOfVersionNo', source.version_no,
      'rollbackReason', coalesce(p_reason, '')
    ),
    source.reconciliation_summary, source.validation_errors, true,
    p_actor_profile_id
  )
  returning * into restored;

  update public.area_map_versions
  set status = 'archived', archived_at = now()
  where deployment_context = p_deployment_context and status = 'published';

  update public.area_map_versions
  set status = 'published',
      published_by_profile_id = p_actor_profile_id,
      published_at = now(),
      archived_at = null
  where id = restored.id
  returning * into restored;

  return restored;
end;
$$;


--
-- Name: sku_conversions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."sku_conversions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "material_id" "uuid" NOT NULL,
    "from_unit_id" "uuid" NOT NULL,
    "to_unit_id" "uuid" NOT NULL,
    "conversion_rate" numeric DEFAULT 1 NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: save_material_conversion("uuid", "uuid", "uuid", numeric, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_material_conversion"("p_material_id" "uuid", "p_from_unit_id" "uuid", "p_to_unit_id" "uuid", "p_conversion_rate" numeric, "p_status" "text", "p_profile_id" "uuid") RETURNS "public"."sku_conversions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.sku_conversions;
begin
  if p_conversion_rate is null or p_conversion_rate<=0 then
    raise exception 'INVALID_CONVERSION_RATE';
  end if;
  if p_status not in ('active','inactive') then
    raise exception 'INVALID_CONVERSION_STATUS';
  end if;
  if not exists(select 1 from public.materials where id=p_material_id)
     or not exists(select 1 from public.units where id=p_from_unit_id)
     or not exists(select 1 from public.units where id=p_to_unit_id) then
    raise exception 'MATERIAL_UNIT_CONVERSION_NOT_CONFIGURED';
  end if;

  insert into public.sku_conversions(
    material_id,from_unit_id,to_unit_id,conversion_rate,status
  ) values(
    p_material_id,p_from_unit_id,p_to_unit_id,p_conversion_rate,p_status
  )
  on conflict(material_id,from_unit_id,to_unit_id)
  do update set
    conversion_rate=excluded.conversion_rate,
    status=excluded.status
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: seed_full_web_test_surveys("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."seed_full_web_test_surveys"("p_run_code" "text" DEFAULT 'WEBTEST-2569'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_wo_fert uuid; v_wo_harv uuid; v_wo_grass_draft uuid; v_wo_grass_ready uuid;
  v_res_fert uuid; v_res_harv uuid; v_res_grass uuid;
  v_act_fert uuid; v_act_harv uuid; v_act_grass uuid;
  v_block_fert uuid; v_block_harv uuid; v_team uuid; v_vehicle uuid; v_supervisor uuid;
  v_d1 date; v_d2 date; v_d3 date; v_d4 date;
  v_tf uuid; v_th uuid; v_ts uuid; v_tt uuid;
  v_rf uuid; v_rh uuid; v_rs uuid; v_rt uuid;
  v_att uuid; v_answer uuid;
  v_result jsonb;
begin
  perform public.cleanup_full_web_test_surveys(p_run_code);

  select id,activity_id,block_id,team_id,scheduled_date into v_wo_fert,v_act_fert,v_block_fert,v_team,v_d1
  from public.work_orders where work_order_no=p_run_code||'-WO-FERT-001';
  select id,activity_id,block_id,scheduled_date into v_wo_harv,v_act_harv,v_block_harv,v_d2
  from public.work_orders where work_order_no=p_run_code||'-WO-HARV-001';
  select id,activity_id,scheduled_date into v_wo_grass_draft,v_act_grass,v_d3
  from public.work_orders where work_order_no=p_run_code||'-WO-GRASS-DRAFT';
  select id,scheduled_date into v_wo_grass_ready,v_d4
  from public.work_orders where work_order_no=p_run_code||'-WO-GRASS-READY';
  if v_wo_fert is null or v_wo_harv is null or v_wo_grass_draft is null or v_wo_grass_ready is null then
    raise exception 'WEB_TEST_BASE_DATA_NOT_FOUND: create_full_web_test_run(%) first',p_run_code;
  end if;

  select id into v_res_fert from public.work_results where work_order_id=v_wo_fert order by result_date,sequence_no limit 1;
  select id into v_res_harv from public.work_results where work_order_id=v_wo_harv order by result_date,sequence_no limit 1;
  select id into v_res_grass from public.work_results where work_order_id=v_wo_grass_draft order by result_date,sequence_no limit 1;
  select id into v_vehicle from public.vehicles where vehicle_code=p_run_code||'-VEH01';
  select id into v_supervisor from public.employees where employee_code=p_run_code||'-E01';

  insert into public.survey_templates(template_code,template_base_code,version_no,template_name,activity_id,status,note,
     survey_scope,survey_category,scoring_method,minimum_pass_pct,allow_attachments,requires_attachment_on_failure,
     effective_from,configuration_json)
  values
   (p_run_code||'-SURV-FERT-V1',p_run_code||'-SURV-FERT',1,'[TEST] ตรวจคุณภาพงานใส่ปุ๋ย',v_act_fert,'active',p_run_code,
    'work_result','quality','weighted_average',85,true,true,v_d1,
    jsonb_build_object('test_run',p_run_code,'analysis_dimensions',jsonb_build_array('activity','block','team','employee'))),
   (p_run_code||'-SURV-HARV-V1',p_run_code||'-SURV-HARV',1,'[TEST] ตรวจคุณภาพการเก็บเกี่ยวและใบชั่ง',v_act_harv,'active',p_run_code,
    'work_result','harvest_quality','weighted_average',85,true,true,v_d1,
    jsonb_build_object('test_run',p_run_code,'analysis_dimensions',jsonb_build_array('ripe_percent','raw_percent','block','team'))),
   (p_run_code||'-SURV-SAFETY-V1',p_run_code||'-SURV-SAFETY',1,'[TEST] ตรวจความปลอดภัยรถก่อนเริ่มงาน',v_act_grass,'active',p_run_code,
    'work_order','safety','weighted_average',90,true,true,v_d1,
    jsonb_build_object('test_run',p_run_code,'frequency','before_each_use')),
   (p_run_code||'-SURV-TEAM-V1',p_run_code||'-SURV-TEAM',1,'[TEST] ประเมินประสิทธิภาพทีมคนงาน',null,'active',p_run_code,
    'team','people_performance','weighted_average',80,true,false,v_d1,
    jsonb_build_object('test_run',p_run_code,'frequency','monthly','analysis_dimensions',jsonb_build_array('team','activity')))
;

  select id into v_tf from public.survey_templates where template_code=p_run_code||'-SURV-FERT-V1';
  select id into v_th from public.survey_templates where template_code=p_run_code||'-SURV-HARV-V1';
  select id into v_ts from public.survey_templates where template_code=p_run_code||'-SURV-SAFETY-V1';
  select id into v_tt from public.survey_templates where template_code=p_run_code||'-SURV-TEAM-V1';

  insert into public.survey_questions(template_id,question_code,question_text,answer_type,required,sort_order,choice_json,
    section_code,section_name,analysis_key,unit_name,min_value,max_value,max_score,weight_pct,is_scored,
    expected_answer_json,scoring_json,attachment_required,failure_severity,status)
  values
   (v_tf,'FERT-Q01','จำนวนต้นที่สุ่มตรวจ','number',true,10,'[]','S1','ข้อมูลการตรวจ','fert.inspected_trees','ต้น',1,null,0,0,false,'{}','{}',false,null,'active'),
   (v_tf,'FERT-Q02','ใส่ปุ๋ยตามอัตราที่กำหนดหรือไม่','boolean',true,20,'[]','S2','คุณภาพงาน','fert.correct_dose',null,null,null,20,20,true,'{"value":true}','{}',true,'high','active'),
   (v_tf,'FERT-Q03','ความสม่ำเสมอในการกระจายปุ๋ย','rating',true,30,'[{"value":1,"label":"ต่ำมาก"},{"value":5,"label":"ดีมาก"}]','S2','คุณภาพงาน','fert.distribution_quality','คะแนน',1,5,20,20,true,'{}','{}',false,'medium','active'),
   (v_tf,'FERT-Q04','จำนวนต้นตกหล่น','number',true,40,'[]','S2','คุณภาพงาน','fert.missed_trees','ต้น',0,null,15,15,true,'{"operator":"lte","value":2}','{}',true,'medium','active'),
   (v_tf,'FERT-Q05','ผู้ปฏิบัติงานใช้อุปกรณ์ PPE ครบ','boolean',true,50,'[]','S3','ความปลอดภัย','safety.ppe',null,null,null,15,15,true,'{"value":true}','{}',true,'high','active'),
   (v_tf,'FERT-Q06','ยอดวัสดุเบิก ใช้ และคงเหลือตรงกัน','boolean',true,60,'[]','S4','วัสดุ','material.balance_match',null,null,null,15,15,true,'{"value":true}','{}',true,'high','active'),
   (v_tf,'FERT-Q07','รูปหลักฐานก่อนและหลังปฏิบัติงาน','photo',true,70,'[]','S5','หลักฐาน','evidence.photo',null,null,null,0,0,false,'{}','{}',true,null,'active'),
   (v_tf,'FERT-Q08','หมายเหตุผู้ตรวจ','text',false,80,'[]','S5','หลักฐาน','inspection.note',null,null,null,0,0,false,'{}','{}',false,null,'active'),
   (v_tf,'FERT-Q09','ความเรียบร้อยโดยรวม','rating',true,90,'[{"value":1,"label":"ต่ำมาก"},{"value":5,"label":"ดีมาก"}]','S2','คุณภาพงาน','fert.overall_quality','คะแนน',1,5,15,15,true,'{}','{}',false,'medium','active'),

   (v_th,'HARV-Q01','ปาล์มสุกตามเกณฑ์','number',true,10,'[]','H1','คุณภาพผลผลิต','harvest.ripe_percent','%',0,100,25,25,true,'{"operator":"gte","value":95}','{}',false,'high','active'),
   (v_th,'HARV-Q02','ทะลายดิบ','number',true,20,'[]','H1','คุณภาพผลผลิต','harvest.raw_percent','%',0,100,20,20,true,'{"operator":"lte","value":3}','{}',true,'high','active'),
   (v_th,'HARV-Q03','การเก็บผลร่วงและความสะอาดพื้นที่','rating',true,30,'[{"value":1,"label":"ต่ำมาก"},{"value":5,"label":"ดีมาก"}]','H1','คุณภาพผลผลิต','harvest.loose_fruit_cleanliness','คะแนน',1,5,15,15,true,'{}','{}',false,'medium','active'),
   (v_th,'HARV-Q04','ความยาวก้านเป็นไปตามมาตรฐาน','boolean',true,40,'[]','H1','คุณภาพผลผลิต','harvest.stalk_standard',null,null,null,15,15,true,'{"value":true}','{}',true,'high','active'),
   (v_th,'HARV-Q05','น้ำหนักใบชั่งตรงกับยอดจัดสรรในผลงาน','boolean',true,50,'[]','H2','ใบชั่ง','weighbridge.weight_match',null,null,null,15,15,true,'{"value":true}','{}',true,'critical','active'),
   (v_th,'HARV-Q06','ปฏิบัติงานตามข้อกำหนดความปลอดภัย','boolean',true,60,'[]','H3','ความปลอดภัย','safety.compliance',null,null,null,10,10,true,'{"value":true}','{}',true,'high','active'),
   (v_th,'HARV-Q07','รูปทะลาย ผลร่วง และหลักฐานใบชั่ง','photo',true,70,'[]','H4','หลักฐาน','evidence.harvest_photo',null,null,null,0,0,false,'{}','{}',true,null,'active'),
