    'questions',(select count(*) from public.survey_questions q join public.survey_templates t on t.id=q.template_id where t.template_code like p_run_code||'%'),
    'responses',(select count(*) from public.survey_responses where response_no like p_run_code||'%'),
    'answers',(select count(*) from public.survey_answers a join public.survey_responses r on r.id=a.response_id where r.response_no like p_run_code||'%'),
    'attachments',(select count(*) from public.survey_response_attachments x join public.survey_responses r on r.id=x.response_id where r.response_no like p_run_code||'%'),
    'findings',(select count(*) from public.survey_findings f join public.survey_responses r on r.id=f.response_id where r.response_no like p_run_code||'%'),
    'response_statuses',(select jsonb_agg(jsonb_build_object('response_no',response_no,'status',status,'score_pct',score_pct,'pass_status',pass_status,'data_quality_pct',data_quality_pct) order by response_no)
