  );
  return v_result;
end;
$$;


--
-- Name: set_row_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."set_row_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: snapshot_budget_rate_rule_set("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."snapshot_budget_rate_rule_set"("p_rule_set_id" "uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'approval'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
  v_status text;
begin
  select status into v_status from public.budget_rate_rule_sets where id=p_rule_set_id for update;
  if v_status is null then raise exception 'Rule set not found'; end if;
  if exists(select 1 from public.v_budget_rate_rule_validation_issues where rule_set_id=p_rule_set_id) then
    raise exception 'Rule set has validation issues';
  end if;
  delete from public.budget_rate_block_snapshots where rule_set_id=p_rule_set_id;
  insert into public.budget_rate_block_snapshots(
    rule_set_id,rule_id,block_id,fiscal_year,activity_id,rate_type,rate_dimension_key,unit_name,
    block_code_snapshot,ap_code_snapshot,planting_year_snapshot,calculated_age_snapshot,palm_size_snapshot,
    rspo_status_snapshot,area_rai_snapshot,tree_count_snapshot,condition_name_snapshot,
    matched_condition_snapshot,resolved_rate,priority_snapshot,snapshot_reason,snapshot_by_profile_id
  )
  select
    m.rule_set_id,m.rule_id,m.block_id,m.fiscal_year,m.activity_id,m.rate_type,m.rate_dimension_key,m.unit_name,
    m.block_code,m.ap_code,m.planting_year,m.calculated_age,m.palm_size,m.rspo_status,m.area_rai,m.tree_count,m.condition_name,
    coalesce((select jsonb_agg(jsonb_build_object('scope',c.condition_scope,'key',c.condition_key,'operator',c.operator,'value_text',c.value_text,'from',c.value_from_numeric,'to',c.value_to_numeric,'values',c.value_json) order by c.sort_order,c.id) from public.budget_rate_rule_conditions c where c.rule_id=m.rule_id),'[]'::jsonb),
    m.resolved_rate,m.priority,p_reason,p_profile_id
  from public.v_budget_rate_rule_resolution m
  where m.rule_set_id=p_rule_set_id;
  get diagnostics v_count=row_count;
  update public.budget_rate_rule_sets
  set status=case when status='active' then 'active' else 'approved' end,
      approved_by_profile_id=coalesce(p_profile_id,approved_by_profile_id),
      approved_at=coalesce(approved_at,now()),updated_at=now()
  where id=p_rule_set_id;
  return v_count;
end;
$$;


--
-- Name: sync_budget_rate_rule_conditions_from_existing_rate("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_budget_rate_rule_conditions_from_existing_rate"("p_rate_id" "text", "p_rule_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  r public.budget_activity_rates%rowtype;
  v_status text;
begin
  select * into r from public.budget_activity_rates where id=p_rate_id;
  if not found or p_rule_id is null then return; end if;
  select status into v_status from public.budget_rate_rules where id=p_rule_id;
  if v_status in ('approved','active') then return; end if;

  delete from public.budget_rate_rule_conditions where rule_id=p_rule_id and condition_key in (
    'planting_year','palm_age','palm_size','ap_code','rspo_status','material_id','dose','package_size_kg',
    'worker_scope','contractor_id','legacy_terrain_code','mapping_rule','rate_text'
  );

  if r.planting_year_from is not null or r.planting_year_to is not null then
    insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_from_numeric,value_to_numeric,display_value)
    values(p_rule_id,'block','planting_year','between',r.planting_year_from,r.planting_year_to,concat_ws('–',r.planting_year_from,r.planting_year_to));
  end if;
  if r.palm_age_from is not null or r.palm_age_to is not null then
    insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_from_numeric,value_to_numeric,value_json,display_value)
    values(p_rule_id,'block','palm_age','between',r.palm_age_from,r.palm_age_to,jsonb_build_object('basis',r.age_basis_mode),concat_ws('–',r.palm_age_from,r.palm_age_to));
  end if;
  if nullif(r.palm_size,'') is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'block','palm_size','eq',r.palm_size,r.palm_size); end if;
  if nullif(r.ap_code,'') is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,value_json,display_value) values(p_rule_id,'block','ap_code','in',r.ap_code,to_jsonb(regexp_split_to_array(regexp_replace(r.ap_code,'\s+','','g'),',')),r.ap_code); end if;
  if r.block_id is not null then
    insert into public.budget_rate_rule_blocks(rule_id,block_id,is_included,note)
    values(p_rule_id,r.block_id,true,'synced from budget_activity_rates')
    on conflict(rule_id,block_id) do update set is_included=true,note=excluded.note;
  end if;
  if nullif(r.rspo_status,'') is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'block','rspo_status','eq',r.rspo_status,r.rspo_status); end if;
  if r.material_id is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'material','material_id','eq',r.material_id::text,r.material_id::text); end if;
  if r.dose_from is not null or r.dose_to is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_from_numeric,value_to_numeric,value_json,display_value) values(p_rule_id,'material','dose','between',r.dose_from,r.dose_to,jsonb_build_object('unit',r.dose_unit),concat_ws('–',r.dose_from,r.dose_to)||coalesce(' '||r.dose_unit,'')); end if;
  if r.package_size_kg is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_from_numeric,display_value) values(p_rule_id,'material','package_size_kg','eq',r.package_size_kg,r.package_size_kg::text||' kg'); end if;
  if nullif(r.worker_scope,'') is not null and r.worker_scope<>'all' then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'worker','worker_scope','eq',r.worker_scope,r.worker_scope); end if;
  if r.contractor_id is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'worker','contractor_id','eq',r.contractor_id::text,r.contractor_id::text); end if;
  if nullif(r.terrain_code,'') is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'display','legacy_terrain_code','eq',r.terrain_code,r.terrain_code); end if;
  if nullif(r.mapping_rule,'') is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'display','mapping_rule','eq',r.mapping_rule,r.mapping_rule); end if;
  if nullif(r.rate_text,'') is not null then insert into public.budget_rate_rule_conditions(rule_id,condition_scope,condition_key,operator,value_text,display_value) values(p_rule_id,'display','rate_text','eq',r.rate_text,r.rate_text); end if;
end $$;


--
-- Name: sync_employee_current_employment_term(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_employee_current_employment_term"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_term public.employee_employment_terms%rowtype;
  v_position_id uuid;
  v_changed boolean := false;
begin
  select p.id into v_position_id
  from public.positions p
  where p.status='active' and lower(trim(p.position_name))=lower(trim(coalesce(new.position,'')))
  order by p.created_at
  limit 1;

  select * into v_term
  from public.employee_employment_terms
  where employee_id=new.id and is_current
  for update;

  if not found then
    if coalesce(new.is_current,true) then
      insert into public.employee_employment_terms(
        employee_id,department_id,position_id,worker_type,payment_type,
        daily_wage,hourly_wage_rate,monthly_salary,contract_rate,
        normal_hours_per_day,effective_from,effective_to,is_current,
        change_reason,created_at,updated_at
      ) values(
        new.id,new.department_id,v_position_id,new.worker_type,new.payment_type,
        coalesce(new.daily_wage,0),new.hourly_wage_rate,coalesce(new.monthly_salary,0),coalesce(new.contract_rate,0),
        coalesce(new.normal_hours_per_day,8),coalesce(new.effective_from,new.start_date,current_date),new.effective_to,true,
        coalesce(new.change_reason,'สร้างจากข้อมูลพนักงาน'),now(),now()
      );
    end if;
    return new;
  end if;

  if not coalesce(new.is_current,true) then
    update public.employee_employment_terms
    set effective_to=coalesce(new.effective_to,new.end_date,current_date),
        is_current=false,
        change_reason=coalesce(new.change_reason,'สิ้นสุดการจ้าง'),
        updated_at=now()
    where id=v_term.id;
    return new;
  end if;

  v_changed :=
    v_term.department_id is distinct from new.department_id or
    v_term.position_id is distinct from v_position_id or
    v_term.worker_type is distinct from new.worker_type or
    v_term.payment_type is distinct from new.payment_type or
    v_term.daily_wage is distinct from coalesce(new.daily_wage,0) or
    v_term.hourly_wage_rate is distinct from new.hourly_wage_rate or
    v_term.monthly_salary is distinct from coalesce(new.monthly_salary,0) or
    v_term.contract_rate is distinct from coalesce(new.contract_rate,0) or
    v_term.normal_hours_per_day is distinct from coalesce(new.normal_hours_per_day,8);

  if not v_changed then
    return new;
  end if;

  if coalesce(new.effective_from,current_date)>v_term.effective_from then
    update public.employee_employment_terms
    set effective_to=coalesce(new.effective_from,current_date)-1,
        is_current=false,
        change_reason=coalesce(new.change_reason,'เปลี่ยนเงื่อนไขการจ้าง'),
        updated_at=now()
    where id=v_term.id;

    insert into public.employee_employment_terms(
      employee_id,department_id,position_id,worker_type,payment_type,
      daily_wage,hourly_wage_rate,monthly_salary,contract_rate,
      normal_hours_per_day,effective_from,effective_to,is_current,
      change_reason,created_at,updated_at
    ) values(
      new.id,new.department_id,v_position_id,new.worker_type,new.payment_type,
      coalesce(new.daily_wage,0),new.hourly_wage_rate,coalesce(new.monthly_salary,0),coalesce(new.contract_rate,0),
      coalesce(new.normal_hours_per_day,8),coalesce(new.effective_from,current_date),new.effective_to,true,
      coalesce(new.change_reason,'เปลี่ยนเงื่อนไขการจ้าง'),now(),now()
    );
  else
    update public.employee_employment_terms
    set department_id=new.department_id,
        position_id=v_position_id,
        worker_type=new.worker_type,
        payment_type=new.payment_type,
        daily_wage=coalesce(new.daily_wage,0),
        hourly_wage_rate=new.hourly_wage_rate,
        monthly_salary=coalesce(new.monthly_salary,0),
        contract_rate=coalesce(new.contract_rate,0),
        normal_hours_per_day=coalesce(new.normal_hours_per_day,8),
        effective_to=new.effective_to,
        change_reason=coalesce(new.change_reason,v_term.change_reason),
        updated_at=now()
    where id=v_term.id;
  end if;

  return new;
end;
$$;


--
-- Name: sync_web_test_legacy_payroll_lines("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_web_test_legacy_payroll_lines"("p_run_code" "text" DEFAULT 'WEBTEST-2569'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  delete from public.payroll_period_lines
  where payroll_period_id in (select id from public.payroll_periods where period_code like p_run_code||'%');

  insert into public.payroll_period_lines(
    payroll_period_id,employee_id,work_result_id,gross_amount,deduction_amount,allowance_amount,status,created_at
  )
  select
    s.payroll_period_id,
    s.employee_id,
    min(e.work_result_id::text)::uuid,
    s.gross_amount,
    s.deduction_amount,
    s.allowance_amount,
    s.status,
    now()
  from public.payroll_employee_summaries s
  join public.payroll_periods p on p.id=s.payroll_period_id
  left join public.payroll_earning_lines e on e.payroll_summary_id=s.id
  where p.period_code like p_run_code||'%'
  group by s.id,s.payroll_period_id,s.employee_id,s.gross_amount,s.deduction_amount,s.allowance_amount,s.status;
  get diagnostics v_count=row_count;

  update public.payroll_earning_lines e
  set legacy_payroll_period_line_id=l.id
  from public.payroll_employee_summaries s
  join public.payroll_period_lines l
    on l.payroll_period_id=s.payroll_period_id and l.employee_id=s.employee_id
  join public.payroll_periods p on p.id=s.payroll_period_id
  where e.payroll_summary_id=s.id and p.period_code like p_run_code||'%' and not coalesce(e.is_locked,false);

  return v_count;
end;
$$;


--
-- Name: sync_work_order_team_members("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_work_order_team_members"("p_work_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_team_id uuid;
  v_supervisor uuid;
  v_inserted integer := 0;
begin
  select wo.team_id, t.supervisor_employee_id
  into v_team_id, v_supervisor
  from public.work_orders wo
  left join public.teams t on t.id=wo.team_id
  where wo.id=p_work_order_id;

  if not found then
    raise exception 'Work order % not found', p_work_order_id;
  end if;

  if v_team_id is null then
    return jsonb_build_object(
      'work_order_id',p_work_order_id,
      'team_id',null,
      'inserted_workers',0,
      'status','no_team'
    );
  end if;

  update public.work_orders
  set supervisor_employee_id=coalesce(supervisor_employee_id,v_supervisor)
  where id=p_work_order_id;

  insert into public.work_order_workers(
    work_order_id, employee_id, role,
    planned_hours, actual_hours, rate, status, created_at
  )
  select
    p_work_order_id,
    tm.employee_id,
    coalesce(nullif(tm.member_role,''),'worker'),
    coalesce(et.normal_hours_per_day,e.normal_hours_per_day,8),
    0,
    case
      when lower(coalesce(et.payment_type,e.payment_type,'')) in ('รายวัน','daily')
        then coalesce(nullif(et.daily_wage,0),nullif(e.daily_wage,0),0)
      when lower(coalesce(et.payment_type,e.payment_type,'')) in ('รายเดือน','monthly')
        then coalesce(nullif(et.monthly_salary,0),nullif(e.monthly_salary,0),0)
      when lower(coalesce(et.payment_type,e.payment_type,'')) in ('รายชั่วโมง','hourly')
        then coalesce(nullif(et.hourly_wage_rate,0),nullif(e.hourly_wage_rate,0),0)
      else coalesce(
        nullif(et.contract_rate,0),nullif(e.contract_rate,0),
        nullif(et.daily_wage,0),nullif(e.daily_wage,0),0
      )
    end,
    'assigned',
    now()
  from public.team_members tm
  join public.employees e on e.id=tm.employee_id and e.status='active'
  left join public.employee_employment_terms et
    on et.employee_id=e.id and et.is_current
  where tm.team_id=v_team_id
    and tm.is_active
    and (tm.start_date is null or tm.start_date<=current_date)
    and (tm.end_date is null or tm.end_date>=current_date)
  on conflict (work_order_id,employee_id) do nothing;

  get diagnostics v_inserted = row_count;

  return jsonb_build_object(
    'work_order_id',p_work_order_id,
    'team_id',v_team_id,
    'supervisor_employee_id',v_supervisor,
    'inserted_workers',v_inserted,
    'status','ready'
  );
end;
$$;


