--
-- Name: trg_apply_fuel_issue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_apply_fuel_issue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_old_liter numeric;
  v_old_cost numeric;
  v_new_balance numeric;
begin
  if new.status = 'issued' and new.applied_at is not null
     and (tg_op = 'INSERT' or old.applied_at is null) then
    update public.fuel_tanks
    set current_balance_liter = current_balance_liter - new.issued_liter,
        updated_at = now()
    where id = new.tank_id;

    select current_estimated_liter, average_unit_cost
    into v_old_liter, v_old_cost
    from public.vehicle_fuel_balances
    where vehicle_id = new.vehicle_id for update;

    v_new_balance := v_old_liter + new.issued_liter;
    update public.vehicle_fuel_balances
    set current_estimated_liter = v_new_balance,
        average_unit_cost = case when v_new_balance > 0
          then ((v_old_liter * v_old_cost) + (new.issued_liter * new.price_per_liter)) / v_new_balance
          else 0 end,
        fuel_type = coalesce(fuel_type,new.fuel_type),
        last_refill_at = new.issue_at,
        last_odometer = coalesce(new.odometer_reading,last_odometer),
        last_hour_meter = coalesce(new.hour_meter_reading,last_hour_meter),
        updated_at = now()
    where vehicle_id = new.vehicle_id;

    update public.fuel_requisitions r
    set issued_liter = r.issued_liter + new.issued_liter,
        status = case
          when r.issued_liter + new.issued_liter + 0.05 >= case when r.approved_liter > 0 then r.approved_liter else r.requested_liter end
            then 'refilled'
          else 'partially_issued'
        end,
        fulfilled_at = case
          when r.issued_liter + new.issued_liter + 0.05 >= case when r.approved_liter > 0 then r.approved_liter else r.requested_liter end
            then now() else r.fulfilled_at end,
        updated_at = now()
    where r.id = new.fuel_requisition_id;
  end if;
  return null;
end;
$$;


--
-- Name: trg_apply_tank_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_apply_tank_receipt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_old_liter numeric;
  v_old_cost numeric;
  v_new_balance numeric;
begin
  if new.status = 'received' and new.applied_at is not null
     and (tg_op = 'INSERT' or old.applied_at is null) then
    select current_balance_liter, current_unit_cost
    into v_old_liter, v_old_cost
    from public.fuel_tanks where id = new.tank_id for update;
    v_new_balance := v_old_liter + new.received_liter;
    update public.fuel_tanks
    set current_balance_liter = v_new_balance,
        current_unit_cost = case when v_new_balance > 0
          then ((v_old_liter * v_old_cost) + (new.received_liter * new.price_per_liter)) / v_new_balance
          else 0 end,
        updated_at = now()
    where id = new.tank_id;

    if new.purchase_requisition_id is not null then
      update public.fuel_tank_purchase_requisitions p
      set received_liter = p.received_liter + new.received_liter,
          status = case
            when p.received_liter + new.received_liter + 0.05 >= case when p.approved_liter > 0 then p.approved_liter else p.requested_liter end
              then 'received' else 'partially_received' end,
          fulfilled_at = case
            when p.received_liter + new.received_liter + 0.05 >= case when p.approved_liter > 0 then p.approved_liter else p.requested_liter end
              then now() else p.fulfilled_at end,
          updated_at = now()
      where p.id = new.purchase_requisition_id;
    end if;
  end if;
  return null;
end;
$$;


--
-- Name: trg_apply_vehicle_fuel_measurement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_apply_vehicle_fuel_measurement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_current numeric;
  v_capacity numeric;
begin
  new.updated_at := now();
  if new.status <> 'approved' or new.applied_at is not null then return new; end if;
  if new.approved_by_profile_id is null then raise exception 'Approved measurement requires approver'; end if;
  select b.current_estimated_liter, v.tank_capacity_liter
  into v_current, v_capacity
  from public.vehicle_fuel_balances b join public.vehicles v on v.id=b.vehicle_id
  where b.vehicle_id = new.vehicle_id for update;
  if not found then raise exception 'Vehicle fuel balance not found'; end if;
  if v_capacity > 0 and new.measured_liter > v_capacity + 0.05 then
    raise exception 'Measured fuel exceeds vehicle tank capacity';
  end if;
  new.balance_before_liter := v_current;
  new.difference_liter := new.measured_liter - v_current;
  new.approved_at := coalesce(new.approved_at,now());
  new.applied_at := now();
  update public.vehicle_fuel_balances
  set current_estimated_liter = new.measured_liter,
      last_measurement_at = new.measured_at,
      last_odometer = coalesce(new.odometer_reading,last_odometer),
      last_hour_meter = coalesce(new.hour_meter_reading,last_hour_meter),
      updated_at = now()
  where vehicle_id = new.vehicle_id;
  return new;
end;
$$;


--
-- Name: trg_apply_vehicle_fuel_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_apply_vehicle_fuel_period"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.applied_at is not null and (tg_op='INSERT' or old.applied_at is null) then
    update public.vehicle_fuel_balances
    set current_estimated_liter = greatest(current_estimated_liter-new.consumed_liter,0),
        updated_at=now()
    where vehicle_id=new.vehicle_id;
    perform public.allocate_vehicle_fuel_period(new.id);
  end if;
  return null;
end;
$$;


