end;$$;


--
-- Name: trg_close_vehicle_fuel_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_close_vehicle_fuel_period"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_balance numeric;
  v_cost numeric;
  v_refill numeric;
  v_tolerance numeric := 0.05;
begin
  new.updated_at := now();
  if tg_op='UPDATE' and old.applied_at is not null then
    if new.opening_balance_liter is distinct from old.opening_balance_liter
       or new.closing_balance_liter is distinct from old.closing_balance_liter
       or new.period_start_at is distinct from old.period_start_at
       or new.period_end_at is distinct from old.period_end_at
       or new.vehicle_id is distinct from old.vehicle_id then
      raise exception 'Applied fuel consumption period is locked';
    end if;
    return new;
  end if;
  if new.status not in ('closed','allocated','verified') or new.applied_at is not null then return new; end if;
  if new.period_end_at is null or new.closing_balance_liter is null then
    raise exception 'Closing time and closing fuel balance are required';
  end if;
  if new.period_end_at <= new.period_start_at then raise exception 'Period end must be after period start'; end if;

  select coalesce(sum(issued_liter),0) into v_refill
  from public.fuel_issues
  where vehicle_id=new.vehicle_id and status='issued'
    and issue_at >= new.period_start_at and issue_at <= new.period_end_at;
  new.refill_liter := v_refill;
  new.consumed_liter := new.opening_balance_liter + new.refill_liter - new.closing_balance_liter;
  if new.consumed_liter < -v_tolerance then raise exception 'Closing balance is greater than opening plus refills'; end if;
  new.consumed_liter := greatest(new.consumed_liter,0);

  select current_estimated_liter, average_unit_cost into v_balance,v_cost
  from public.vehicle_fuel_balances where vehicle_id=new.vehicle_id for update;
  if not found then raise exception 'Vehicle fuel balance not found'; end if;
  if new.consumed_liter > v_balance + v_tolerance then raise exception 'Consumed fuel exceeds vehicle balance'; end if;
  new.average_unit_cost := v_cost;
  new.fuel_cost_amount := round(new.consumed_liter*v_cost,2);
  new.applied_at := now();
  new.closed_at := coalesce(new.closed_at,now());
  return new;
end;
$$;


--
-- Name: trg_reallocate_vehicle_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_reallocate_vehicle_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_period_id uuid;
begin
  if pg_trigger_depth() > 1 then return null; end if;
  v_period_id := coalesce(new.consumption_period_id, old.consumption_period_id);
  if v_period_id is not null and exists(select 1 from public.vehicle_fuel_consumption_periods where id=v_period_id and applied_at is not null) then
    perform public.allocate_vehicle_fuel_period(v_period_id);
  end if;
  return null;
end;
$$;


