--
-- Name: trg_validate_fuel_issue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_validate_fuel_issue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_req public.fuel_requisitions%rowtype;
  v_tank public.fuel_tanks%rowtype;
  v_vehicle public.vehicles%rowtype;
  v_balance public.vehicle_fuel_balances%rowtype;
  v_prior_issued numeric;
  v_authorized numeric;
begin
  new.updated_at := now();

  if tg_op = 'UPDATE' and old.applied_at is not null then
    if new.issued_liter is distinct from old.issued_liter
       or new.tank_id is distinct from old.tank_id
       or new.vehicle_id is distinct from old.vehicle_id
       or new.fuel_requisition_id is distinct from old.fuel_requisition_id
       or new.status is distinct from old.status then
      raise exception 'Issued fuel transaction is locked and cannot be edited';
    end if;
    return new;
  end if;

  if new.status <> 'issued' then return new; end if;

  select * into v_req from public.fuel_requisitions
  where id = new.fuel_requisition_id for update;
  if not found then raise exception 'Fuel requisition not found'; end if;
  if public.fuel_setting_boolean('fuel.require_approved_requisition_before_issue', true)
     and v_req.status not in ('approved','partially_issued') then
    raise exception 'Fuel requisition must be approved before issue';
  end if;
  if v_req.vehicle_id is null then raise exception 'Approved fuel requisition has no vehicle'; end if;
  new.vehicle_id := coalesce(new.vehicle_id, v_req.vehicle_id);
  if new.vehicle_id <> v_req.vehicle_id then raise exception 'Issued vehicle does not match requisition'; end if;
  new.work_order_id := coalesce(new.work_order_id, v_req.work_order_id);
  new.work_result_id := coalesce(new.work_result_id, v_req.work_result_id);
  new.tank_id := coalesce(new.tank_id, v_req.source_tank_id);
  if new.tank_id is null then raise exception 'Source fuel tank is required'; end if;
  if new.received_by_profile_id is null and new.driver_employee_id is null then
    raise exception 'Fuel receiver or driver is required';
  end if;
  if coalesce(new.issued_liter,0) <= 0 then raise exception 'Issued liter must be greater than zero'; end if;

  select * into v_tank from public.fuel_tanks where id = new.tank_id for update;
  if not found then raise exception 'Fuel tank not found'; end if;
  if v_tank.current_balance_liter < new.issued_liter then raise exception 'Insufficient central tank balance'; end if;

  select * into v_vehicle from public.vehicles where id = new.vehicle_id;
  select * into v_balance from public.vehicle_fuel_balances where vehicle_id = new.vehicle_id for update;
  if not found then raise exception 'Vehicle fuel balance not found'; end if;
  if coalesce(v_vehicle.tank_capacity_liter,0) > 0
     and v_balance.current_estimated_liter + new.issued_liter > v_vehicle.tank_capacity_liter + 0.05 then
    raise exception 'Refill exceeds vehicle tank capacity';
  end if;

  select coalesce(sum(i.issued_liter),0) into v_prior_issued
  from public.fuel_issues i
  where i.fuel_requisition_id = new.fuel_requisition_id
    and i.status = 'issued'
    and (tg_op = 'INSERT' or i.id <> new.id);
  v_authorized := case when v_req.approved_liter > 0 then v_req.approved_liter else v_req.requested_liter end;
  if v_prior_issued + new.issued_liter > v_authorized + 0.05 then
    raise exception 'Issued amount exceeds approved amount';
  end if;

  new.fuel_type := coalesce(new.fuel_type, v_tank.fuel_type, v_vehicle.fuel_type);
  new.price_per_liter := case when coalesce(new.price_per_liter,0) > 0 then new.price_per_liter else v_tank.current_unit_cost end;
  new.total_amount := round(new.issued_liter * coalesce(new.price_per_liter,0),2);
  new.tank_balance_before_liter := v_tank.current_balance_liter;
  new.tank_balance_after_liter := v_tank.current_balance_liter - new.issued_liter;
  new.vehicle_balance_before_liter := v_balance.current_estimated_liter;
  new.vehicle_balance_after_liter := v_balance.current_estimated_liter + new.issued_liter;
  new.applied_at := now();
  return new;
end;
$$;


--
-- Name: trg_validate_tank_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_validate_tank_receipt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_tank public.fuel_tanks%rowtype;
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' and old.applied_at is not null then
    if new.received_liter is distinct from old.received_liter
       or new.price_per_liter is distinct from old.price_per_liter
       or new.tank_id is distinct from old.tank_id
       or new.status is distinct from old.status then
      raise exception 'Applied tank receipt is locked and cannot be edited';
    end if;
    return new;
  end if;
  if new.status <> 'received' then return new; end if;
  select * into v_tank from public.fuel_tanks where id = new.tank_id for update;
  if not found then raise exception 'Fuel tank not found'; end if;
  if v_tank.capacity_liter > 0 and v_tank.current_balance_liter + new.received_liter > v_tank.capacity_liter + 0.05 then
    raise exception 'Receipt exceeds central tank capacity';
  end if;
  new.total_amount := round(new.received_liter * new.price_per_liter,2);
  new.tank_balance_before_liter := v_tank.current_balance_liter;
  new.tank_balance_after_liter := v_tank.current_balance_liter + new.received_liter;
  new.applied_at := now();
  return new;
end;
$$;


--
-- Name: trg_validate_work_result_vehicle_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trg_validate_work_result_vehicle_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_order_id uuid;
  v_overlap boolean;
begin
  new.updated_at := now();
  select work_order_id into v_order_id from public.work_results where id = new.work_result_id;
  if v_order_id is null then raise exception 'Work result has no work order'; end if;
  new.work_order_id := v_order_id;
  if not exists (
    select 1 from public.work_order_machines m
    where m.work_order_id = new.work_order_id and m.vehicle_id = new.vehicle_id
  ) then
    raise exception 'Vehicle is not assigned to this work order';
  end if;
  if new.end_odometer is not null and new.start_odometer is not null and new.end_odometer < new.start_odometer then
    raise exception 'End odometer cannot be lower than start odometer';
  end if;
  if new.end_hour_meter is not null and new.start_hour_meter is not null and new.end_hour_meter < new.start_hour_meter then
    raise exception 'End hour meter cannot be lower than start hour meter';
  end if;
  new.distance_km := case when new.end_odometer is not null and new.start_odometer is not null then new.end_odometer-new.start_odometer else coalesce(new.distance_km,0) end;
  new.engine_hours := case when new.end_hour_meter is not null and new.start_hour_meter is not null then new.end_hour_meter-new.start_hour_meter else coalesce(new.engine_hours,0) end;
  new.working_hours := case when new.start_at is not null and new.end_at is not null then greatest(extract(epoch from (new.end_at-new.start_at))/3600.0,0) else coalesce(new.working_hours,0) end;
  new.idle_hours := greatest(coalesce(new.engine_hours,0)-coalesce(new.working_hours,0),0);

  if new.start_at is not null and new.end_at is not null then
    select exists(
      select 1 from public.work_result_vehicle_usage u
      where u.vehicle_id = new.vehicle_id
        and u.id <> coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid)
        and u.status not in ('cancelled','rejected')
        and u.start_at is not null and u.end_at is not null
        and tstzrange(u.start_at,u.end_at,'[)') && tstzrange(new.start_at,new.end_at,'[)')
    ) into v_overlap;
    if v_overlap then raise exception 'Vehicle usage overlaps another work period'; end if;
  end if;
  return new;
end;
$$;


--
-- Name: update_canonical_annual_work_plan("uuid", "uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_canonical_annual_work_plan"("p_annual_plan_id" "uuid", "p_actor_profile_id" "uuid", "p_plan_name" "text", "p_estate_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_plan public.annual_work_plans%rowtype;
  v_plan_name text := nullif(btrim(p_plan_name), '');
  v_note text := nullif(btrim(p_note), '');
begin
  if v_plan_name is null then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_NAME_INVALID';
  end if;
  if p_actor_profile_id is null or not exists (
    select 1 from public.profiles profile
    where profile.id = p_actor_profile_id and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select annual_plan.*
  into v_plan
  from public.annual_work_plans annual_plan
  where annual_plan.id = p_annual_plan_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;
  if v_plan.source_type is distinct from 'canonical_budget' then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
  end if;
  if v_plan.status is distinct from 'draft' then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;

  perform set_config('app.phase2c_plan_header_rpc', 'on', true);

  update public.annual_work_plans
  set plan_name = v_plan_name,
      estate_id = p_estate_id,
      note = v_note,
      updated_at = transaction_timestamp()
  where id = p_annual_plan_id
  returning * into v_plan;

  return jsonb_build_object('annual_work_plan', to_jsonb(v_plan));
end
$$;


--
-- Name: FUNCTION "update_canonical_annual_work_plan"("p_annual_plan_id" "uuid", "p_actor_profile_id" "uuid", "p_plan_name" "text", "p_estate_id" "uuid", "p_note" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."update_canonical_annual_work_plan"("p_annual_plan_id" "uuid", "p_actor_profile_id" "uuid", "p_plan_name" "text", "p_estate_id" "uuid", "p_note" "text") IS 'Updates only non-workflow header fields of a draft canonical Annual Plan.';


--
-- Name: update_canonical_planned_work_item("uuid", "uuid", "date", "date", "text", integer, integer, numeric, "text", numeric, "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_canonical_planned_work_item"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid", "p_planned_start_date" "date" DEFAULT NULL::"date", "p_planned_end_date" "date" DEFAULT NULL::"date", "p_recurrence_type" "text" DEFAULT NULL::"text", "p_recurrence_interval" integer DEFAULT NULL::integer, "p_repeat_after_last_done_days" integer DEFAULT NULL::integer, "p_target_quantity" numeric DEFAULT NULL::numeric, "p_target_unit" "text" DEFAULT NULL::"text", "p_planned_budget" numeric DEFAULT NULL::numeric, "p_suggested_team_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text", "p_ap_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_item public.planned_work_items%rowtype;
  v_plan public.annual_work_plans%rowtype;
  v_annual_plan_id uuid;
  v_material_count integer := 0;
begin
  if p_actor_profile_id is null or not exists (
    select 1 from public.profiles profile
    where profile.id = p_actor_profile_id and profile.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'ACTOR_PROFILE_NOT_FOUND';
  end if;

  select planned_item.annual_plan_id
  into v_annual_plan_id
  from public.planned_work_items planned_item
  where planned_item.id = p_planned_work_item_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;

  select annual_plan.*
  into v_plan
  from public.annual_work_plans annual_plan
  where annual_plan.id = v_annual_plan_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_ANNUAL_PLAN_NOT_FOUND';
  end if;

  select planned_item.*
  into v_item
  from public.planned_work_items planned_item
  where planned_item.id = p_planned_work_item_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLANNED_ITEM_NOT_FOUND';
  end if;
  if v_item.annual_plan_id is distinct from v_plan.id then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
  end if;
  if v_plan.source_type is distinct from 'canonical_budget'
    or v_item.source_type is distinct from 'canonical_budget'
  then
    raise exception using errcode = 'P0001', message = 'PLANNING_CANONICAL_LINEAGE_REQUIRED';
  end if;
  if v_plan.status is distinct from 'draft' then
    raise exception using errcode = 'P0001', message = 'PLANNING_PLAN_FROZEN';
  end if;

  perform set_config('app.phase2c_snapshot_rpc', 'on', true);

  update public.planned_work_items
  set planned_start_date = p_planned_start_date,
      planned_end_date = p_planned_end_date,
      recurrence_type = p_recurrence_type,
      recurrence_interval = p_recurrence_interval,
      repeat_after_last_done_days = p_repeat_after_last_done_days,
      target_quantity = p_target_quantity,
      target_unit = p_target_unit,
      planned_budget = p_planned_budget,
      suggested_team_id = p_suggested_team_id,
      note = nullif(btrim(p_note), ''),
      ap_code = p_ap_code,
      updated_at = transaction_timestamp()
  where id = p_planned_work_item_id
  returning * into v_item;

  select count(*)::integer
  into v_material_count
  from public.planned_work_materials material_snapshot
  where material_snapshot.planned_work_item_id = p_planned_work_item_id;

  return jsonb_build_object(
    'planned_work_item', to_jsonb(v_item),
    'material_count', v_material_count,
    'materials_refreshed', false
  );
end
$$;


--
-- Name: FUNCTION "update_canonical_planned_work_item"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid", "p_planned_start_date" "date", "p_planned_end_date" "date", "p_recurrence_type" "text", "p_recurrence_interval" integer, "p_repeat_after_last_done_days" integer, "p_target_quantity" numeric, "p_target_unit" "text", "p_planned_budget" numeric, "p_suggested_team_id" "uuid", "p_note" "text", "p_ap_code" "text"); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION "public"."update_canonical_planned_work_item"("p_planned_work_item_id" "uuid", "p_actor_profile_id" "uuid", "p_planned_start_date" "date", "p_planned_end_date" "date", "p_recurrence_type" "text", "p_recurrence_interval" integer, "p_repeat_after_last_done_days" integer, "p_target_quantity" numeric, "p_target_unit" "text", "p_planned_budget" numeric, "p_suggested_team_id" "uuid", "p_note" "text", "p_ap_code" "text") IS 'Updates mutable metadata of a draft canonical Planned Item without refreshing its Material snapshot.';


