    CONSTRAINT "activity_performance_standard_hours_chk" CHECK (("standard_hours_per_person_day" > (0)::numeric)),
    CONSTRAINT "activity_performance_standard_status_chk" CHECK (("status" = ANY (ARRAY['draft'::"text", 'reviewed'::"text", 'approved'::"text", 'inactive'::"text", 'rejected'::"text"]))),
    CONSTRAINT "activity_performance_standard_values_chk" CHECK (((COALESCE("standard_per_person", (0)::numeric) >= (0)::numeric) AND (COALESCE("standard_per_tree", (0)::numeric) >= (0)::numeric) AND (COALESCE("standard_per_rai", (0)::numeric) >= (0)::numeric) AND (COALESCE("standard_per_hour", (0)::numeric) >= (0)::numeric))),
    CONSTRAINT "activity_performance_standard_weights_chk" CHECK ((("person_weight_pct" >= (0)::numeric) AND ("tree_weight_pct" >= (0)::numeric) AND ("area_weight_pct" >= (0)::numeric) AND ("time_weight_pct" >= (0)::numeric) AND ("quality_weight_pct" >= (0)::numeric) AND ("round"((((("person_weight_pct" + "tree_weight_pct") + "area_weight_pct") + "time_weight_pct") + "quality_weight_pct"), 2) = (100)::numeric)))
);


