    CONSTRAINT "annual_work_plans_canonical_request_consistent" CHECK (((("source_type" IS DISTINCT FROM 'canonical_budget'::"text") AND ("planning_request_key" IS NULL)) OR (("source_type" = 'canonical_budget'::"text") AND (NULLIF("btrim"("planning_request_key"), ''::"text") IS NOT NULL) AND ("planning_request_key" = "btrim"("planning_request_key")) AND (("char_length"("btrim"("planning_request_key")) >= 1) AND ("char_length"("btrim"("planning_request_key")) <= 200)))))
);


