    "department_id" "uuid",
    "default_housing_unit_id" "uuid",
    "normal_hours_per_day" numeric DEFAULT 8 NOT NULL,
    "hourly_wage_rate" numeric GENERATED ALWAYS AS (
CASE
    WHEN ("normal_hours_per_day" > (0)::numeric) THEN ("daily_wage" / "normal_hours_per_day")
    ELSE (0)::numeric
END) STORED,
    "worker_type" "text",
    "payment_type" "text",
    "monthly_salary" numeric DEFAULT 0 NOT NULL,
    "contract_rate" numeric DEFAULT 0 NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "effective_to" "date",
    "version_no" integer DEFAULT 1 NOT NULL,
    "is_current" boolean DEFAULT true NOT NULL,
    "previous_version_id" "uuid",
    "change_reason" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


