    "planning_request_key" "text",
    CONSTRAINT "planned_work_items_canonical_lineage_complete" CHECK (((("source_type" IS DISTINCT FROM 'canonical_budget'::"text") AND ("source_budget_year_id" IS NULL) AND ("source_budget_activity_rate_id" IS NULL) AND ("source_budget_rate_block_id" IS NULL) AND ("planning_request_key" IS NULL)) OR (("source_type" = 'canonical_budget'::"text") AND ("source_budget_year_id" IS NOT NULL) AND ("source_budget_activity_rate_id" IS NOT NULL) AND ("source_budget_rate_block_id" IS NOT NULL) AND (NULLIF("btrim"("planning_request_key"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "planned_work_items_planning_request_key_not_blank" CHECK ((("planning_request_key" IS NULL) OR (("char_length"("btrim"("planning_request_key")) >= 1) AND ("char_length"("btrim"("planning_request_key")) <= 200))))
);


