    "snapshot_at" timestamp with time zone,
    CONSTRAINT "planned_work_materials_canonical_snapshot_complete" CHECK ((("snapshot_source_type" IS DISTINCT FROM 'canonical_budget_block_material'::"text") OR (("source_budget_rate_block_material_id" IS NOT NULL) AND ("snapshot_usage_basis" IS NOT NULL) AND ("snapshot_usage_rate" IS NOT NULL) AND ("snapshot_usage_rate" > (0)::numeric) AND ("snapshot_basis_quantity" IS NOT NULL) AND ("snapshot_basis_quantity" >= (0)::numeric) AND ("unit_id" IS NOT NULL) AND ("planned_quantity" >= (0)::numeric) AND ("snapshot_at" IS NOT NULL)))),
    CONSTRAINT "planned_work_materials_estimated_amount_nonnegative" CHECK (("estimated_amount" >= (0)::numeric)),
    CONSTRAINT "planned_work_materials_estimated_unit_cost_nonnegative" CHECK (("estimated_unit_cost" >= (0)::numeric)),
    CONSTRAINT "planned_work_materials_planned_quantity_nonnegative" CHECK (("planned_quantity" >= (0)::numeric)),
    CONSTRAINT "planned_work_materials_snapshot_amount_nonnegative" CHECK ((("snapshot_amount_per_basis" IS NULL) OR ("snapshot_amount_per_basis" >= (0)::numeric))),
    CONSTRAINT "planned_work_materials_snapshot_source_consistent" CHECK (((("snapshot_source_type" IS NULL) AND ("source_budget_rate_block_material_id" IS NULL) AND ("snapshot_usage_basis" IS NULL) AND ("snapshot_usage_rate" IS NULL) AND ("snapshot_basis_quantity" IS NULL) AND ("snapshot_unit_cost" IS NULL) AND ("snapshot_amount_per_basis" IS NULL) AND ("snapshot_at" IS NULL)) OR ("snapshot_source_type" = 'canonical_budget_block_material'::"text"))),
    CONSTRAINT "planned_work_materials_snapshot_unit_cost_nonnegative" CHECK ((("snapshot_unit_cost" IS NULL) OR ("snapshot_unit_cost" >= (0)::numeric))),
    CONSTRAINT "planned_work_materials_snapshot_usage_basis_valid" CHECK ((("snapshot_usage_basis" IS NULL) OR ("snapshot_usage_basis" = ANY (ARRAY['tree_count'::"text", 'area_rai'::"text", 'manual_qty'::"text", 'bag_count'::"text"]))))
);


