);


--
-- Name: v_activity_budget_performance_basis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_activity_budget_performance_basis" WITH ("security_invoker"='true') AS
 WITH "result_base" AS (
         SELECT "work_performance_metrics"."id",
            "work_performance_metrics"."metric_scope",
            "work_performance_metrics"."work_result_id",
            "work_performance_metrics"."work_result_worker_id",
            "work_performance_metrics"."activity_id",
            "work_performance_metrics"."employee_id",
            "work_performance_metrics"."team_id",
            "work_performance_metrics"."block_id",
            "work_performance_metrics"."work_date",
            "work_performance_metrics"."standard_id",
            "work_performance_metrics"."condition_group",
            "work_performance_metrics"."actual_quantity",
            "work_performance_metrics"."actual_unit",
            "work_performance_metrics"."labor_hours",
            "work_performance_metrics"."labor_days",
            "work_performance_metrics"."area_rai",
            "work_performance_metrics"."tree_count",
            "work_performance_metrics"."person_output",
            "work_performance_metrics"."tree_output",
            "work_performance_metrics"."area_output",
            "work_performance_metrics"."hour_output",
            "work_performance_metrics"."person_efficiency_pct",
            "work_performance_metrics"."tree_efficiency_pct",
            "work_performance_metrics"."area_efficiency_pct",
            "work_performance_metrics"."time_efficiency_pct",
            "work_performance_metrics"."quantity_efficiency_pct",
            "work_performance_metrics"."quality_pct",
            "work_performance_metrics"."completion_pct",
            "work_performance_metrics"."quality_adjusted_efficiency_pct",
            "work_performance_metrics"."composite_efficiency_pct",
            "work_performance_metrics"."capped_efficiency_pct",
            "work_performance_metrics"."data_quality_pct",
            "work_performance_metrics"."is_estimated",
            "work_performance_metrics"."sample_weight",
            "work_performance_metrics"."outlier_flag",
            "work_performance_metrics"."outlier_reason",
            "work_performance_metrics"."is_budget_eligible",
            "work_performance_metrics"."calculation_version",
            "work_performance_metrics"."calculated_at"
           FROM "public"."work_performance_metrics"
          WHERE (("work_performance_metrics"."metric_scope" = 'result'::"text") AND ("work_performance_metrics"."is_budget_eligible" = true) AND ("work_performance_metrics"."composite_efficiency_pct" IS NOT NULL))
        ), "quantiles" AS (
         SELECT "result_base"."activity_id",
            "result_base"."condition_group",
            "percentile_cont"((0.10)::double precision) WITHIN GROUP (ORDER BY (("result_base"."composite_efficiency_pct")::double precision)) AS "p10",
            "percentile_cont"((0.50)::double precision) WITHIN GROUP (ORDER BY (("result_base"."composite_efficiency_pct")::double precision)) AS "median_efficiency_pct",
            "percentile_cont"((0.90)::double precision) WITHIN GROUP (ORDER BY (("result_base"."composite_efficiency_pct")::double precision)) AS "p90"
           FROM "result_base"
          GROUP BY "result_base"."activity_id", "result_base"."condition_group"
        ), "employee_counts" AS (
         SELECT "work_performance_metrics"."activity_id",
            "work_performance_metrics"."condition_group",
            "count"(DISTINCT "work_performance_metrics"."employee_id") AS "employee_count"
           FROM "public"."work_performance_metrics"
          WHERE ("work_performance_metrics"."metric_scope" = 'employee'::"text")
          GROUP BY "work_performance_metrics"."activity_id", "work_performance_metrics"."condition_group"
        )
 SELECT "r"."activity_id",
    "a"."activity_code",
    "a"."activity_name",
    "r"."condition_group",
    "min"("r"."work_date") AS "period_start",
    "max"("r"."work_date") AS "period_end",
    "count"(*) AS "sample_count",
    COALESCE("ec"."employee_count", (0)::bigint) AS "employee_count",
    "count"(DISTINCT "r"."team_id") AS "team_count",
    "count"(DISTINCT "r"."block_id") AS "block_count",
    "q"."median_efficiency_pct",
    "avg"("r"."composite_efficiency_pct") FILTER (WHERE ((("r"."composite_efficiency_pct")::double precision >= "q"."p10") AND (("r"."composite_efficiency_pct")::double precision <= "q"."p90"))) AS "trimmed_mean_efficiency_pct",
    "avg"("r"."quality_pct") AS "average_quality_pct",
    "avg"("r"."data_quality_pct") AS "average_data_quality_pct",
    "count"(*) FILTER (WHERE "r"."outlier_flag") AS "outlier_count"
   FROM ((("result_base" "r"
     JOIN "quantiles" "q" ON ((("q"."activity_id" = "r"."activity_id") AND ("q"."condition_group" = "r"."condition_group"))))
     JOIN "public"."activities" "a" ON (("a"."id" = "r"."activity_id")))
     LEFT JOIN "employee_counts" "ec" ON ((("ec"."activity_id" = "r"."activity_id") AND ("ec"."condition_group" = "r"."condition_group"))))
  GROUP BY "r"."activity_id", "a"."activity_code", "a"."activity_name", "r"."condition_group", "q"."median_efficiency_pct", "q"."p10", "q"."p90", "ec"."employee_count";


--
-- Name: v_activity_performance_standard_setup; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_activity_performance_standard_setup" WITH ("security_invoker"='true') AS
 SELECT "a"."id" AS "activity_id",
    "a"."activity_code",
    "a"."activity_name",
    "a"."default_unit",
    "s"."id" AS "standard_id",
    "s"."budget_year_id",
    "byear"."fiscal_year",
    "s"."standard_code",
    "s"."condition_group",
    "s"."standard_per_person",
    "s"."standard_per_tree",
    "s"."standard_per_rai",
    "s"."standard_per_hour",
    "s"."person_weight_pct",
    "s"."tree_weight_pct",
    "s"."area_weight_pct",
    "s"."time_weight_pct",
    "s"."quality_weight_pct",
    "s"."minimum_sample_count",
    "s"."minimum_data_quality_pct",
    "s"."status",
        CASE
            WHEN ("s"."id" IS NULL) THEN 'missing_template'::"text"
            WHEN (("s"."standard_per_person" IS NULL) AND ("s"."standard_per_tree" IS NULL) AND ("s"."standard_per_rai" IS NULL) AND ("s"."standard_per_hour" IS NULL)) THEN 'needs_standard_values'::"text"
            WHEN ("s"."status" <> 'approved'::"text") THEN 'needs_approval'::"text"
            ELSE 'ready'::"text"
        END AS "setup_status",
    "s"."effective_from",
    "s"."effective_to",
    "s"."approved_at",
    "s"."updated_at"
   FROM (("public"."activities" "a"
     LEFT JOIN "public"."activity_performance_standards" "s" ON ((("s"."activity_id" = "a"."id") AND ("s"."budget_year_id" = 'budget-year-2569'::"text") AND ("s"."condition_group" = 'default'::"text") AND ("s"."version_no" = 1))))
     LEFT JOIN "public"."budget_years" "byear" ON (("byear"."id" = "s"."budget_year_id")));


