--
-- Name: v_app_workspace_definition; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_app_workspace_definition" WITH ("security_invoker"='true') AS
 SELECT "workspace_key",
    "max"("label_th") FILTER (WHERE ("is_primary" AND (NOT "is_hidden"))) AS "workspace_label",
    "max"("route") FILTER (WHERE ("is_primary" AND (NOT "is_hidden"))) AS "workspace_route",
    "max"("required_permission_key") FILTER (WHERE ("is_primary" AND (NOT "is_hidden"))) AS "required_permission_key",
    "jsonb_agg"("jsonb_build_object"('menu_key', "menu_key", 'label_th', "label_th", 'route', "route", 'tab', "workspace_tab", 'navigation_mode', "navigation_mode", 'hidden', "is_hidden", 'permission', "required_permission_key", 'legacy_view_key', "legacy_view_key", 'description', "description", 'configuration', "configuration_json") ORDER BY "sort_order", "menu_key") AS "tabs",
    ("jsonb_agg"("configuration_json" ORDER BY "sort_order", "menu_key") FILTER (WHERE ("is_primary" AND (NOT "is_hidden"))) -> 0) AS "workspace_configuration"
   FROM "public"."menu_items" "m"
  WHERE (("status" = 'active'::"text") AND ("workspace_key" IS NOT NULL) AND ("navigation_mode" <> 'group'::"text"))
  GROUP BY "workspace_key";


