-- Name: v_available_inbound_weight_tickets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_available_inbound_weight_tickets" WITH ("security_invoker"='true') AS
 SELECT "tsr"."id" AS "transport_source_record_id",
    "tsr"."record_key",
    "tsr"."doc_no",
    "tsr"."doc_date",
    "tsr"."supplier_code",
    "tsr"."supplier_name",
    "tsr"."source_area_key",
