    "tsr"."standard",
    "tsr"."net_weight" AS "source_net_weight_kg",
    COALESCE("sum"("wrwt"."allocated_weight_kg") FILTER (WHERE ("wrwt"."link_status" <> 'cancelled'::"text")), (0)::numeric) AS "allocated_weight_kg",
    ("tsr"."net_weight" - COALESCE("sum"("wrwt"."allocated_weight_kg") FILTER (WHERE ("wrwt"."link_status" <> 'cancelled'::"text")), (0)::numeric)) AS "remaining_weight_kg",
    "count"("wrwt"."id") FILTER (WHERE ("wrwt"."link_status" <> 'cancelled'::"text")) AS "allocation_count",
    "tsr"."is_cancelled",
    "tsr"."updated_at"
   FROM ("public"."transport_source_records" "tsr"
     LEFT JOIN "public"."work_result_weight_tickets" "wrwt" ON (("wrwt"."transport_source_record_id" = "tsr"."id")))
  WHERE ("tsr"."in_out_type" = 'I'::"text")
  GROUP BY "tsr"."id", "tsr"."record_key", "tsr"."doc_no", "tsr"."doc_date", "tsr"."supplier_code", "tsr"."supplier_name", "tsr"."source_area_key", "tsr"."yard", "tsr"."standard", "tsr"."net_weight", "tsr"."is_cancelled", "tsr"."updated_at";


