    COALESCE("s"."snapshot_count", (0)::bigint) AS "snapshot_count",
    "s"."matched_block_count",
    "s"."snapshot_at" AS "last_snapshot_at"
   FROM ((("public"."budget_activity_rates" "bar"
     LEFT JOIN "public"."budget_rate_rule_sets" "rs" ON (("rs"."id" = "bar"."rule_set_id")))
     LEFT JOIN "public"."budget_rate_rules" "r" ON (("r"."id" = "bar"."rule_id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "snapshot_count",
            "count"(DISTINCT "snap"."block_id") AS "matched_block_count",
            "max"("snap"."snapshot_at") AS "snapshot_at"
           FROM "public"."budget_rate_block_snapshots" "snap"
