-- Name: v_budget_rate_announcement_matrix; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_budget_rate_announcement_matrix" WITH ("security_invoker"='true') AS
 SELECT "rs"."id" AS "rule_set_id",
    "rs"."fiscal_year",
    "rs"."rule_set_name",
    "rs"."announcement_no",
    "r"."activity_id",
    COALESCE("a"."activity_code", "r"."activity_code_snapshot") AS "activity_code",
    COALESCE("a"."activity_name", "r"."activity_name_snapshot") AS "activity_name",
    "r"."condition_name",
    "r"."condition_mode",
    "r"."unit_name",
    "r"."rate_current",
    "r"."rate_proposed",
    "r"."rate_approved",
    "r"."dose_from",
    "r"."dose_to",
    "r"."dose_unit",
    "r"."package_size_kg",
    "r"."priority",
    "r"."status",
    ("count"(DISTINCT "s"."block_id"))::integer AS "block_count",
    COALESCE("sum"("s"."area_rai_snapshot"), (0)::numeric) AS "total_area_rai",
    COALESCE("sum"("s"."tree_count_snapshot"), (0)::bigint) AS "total_tree_count"
   FROM ((("public"."budget_rate_rule_sets" "rs"
     JOIN "public"."budget_rate_rules" "r" ON (("r"."rule_set_id" = "rs"."id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "r"."activity_id")))
     LEFT JOIN "public"."budget_rate_block_snapshots" "s" ON ((("s"."rule_set_id" = "rs"."id") AND ("s"."rule_id" = "r"."id"))))
  GROUP BY "rs"."id", "rs"."fiscal_year", "rs"."rule_set_name", "rs"."announcement_no", "r"."id", "r"."activity_id", "a"."activity_code", "r"."activity_code_snapshot", "a"."activity_name", "r"."activity_name_snapshot", "r"."condition_name", "r"."condition_mode", "r"."unit_name", "r"."rate_current", "r"."rate_proposed", "r"."rate_approved", "r"."dose_from", "r"."dose_to", "r"."dose_unit", "r"."package_size_kg", "r"."priority", "r"."status";


--
-- Name: v_budget_rate_rule_matches; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_budget_rate_rule_matches" WITH ("security_invoker"='true') AS
 WITH "matched" AS (
         SELECT "rs"."id" AS "rule_set_id",
            "rs"."budget_year_id",
            "rs"."fiscal_year",
            "rs"."status" AS "rule_set_status",
            "r"."id" AS "rule_id",
            "r"."rule_code",
            "r"."rule_name",
            "r"."activity_id",
            "r"."activity_code_snapshot",
            "r"."rate_type",
            "r"."rate_dimension_key",
            "r"."unit_name",
            "r"."condition_mode",
            "r"."condition_name",
            "r"."priority",
            "r"."needs_mapping",
            "b"."id" AS "block_id",
            "b"."block_code",
            "b"."ap_code",
            "b"."planting_year",
            "public"."calculate_palm_age_for_budget_year"("rs"."fiscal_year", "b"."planting_year") AS "calculated_age",
            "public"."palm_size_for_budget_year"("rs"."fiscal_year", "b"."planting_year") AS "palm_size",
            "b"."area_rai",
            "b"."tree_count",
            "b"."rspo_status",
            COALESCE("rb"."override_rate", "r"."rate_approved", "r"."rate_proposed", "r"."rate_current") AS "resolved_rate",
            (("rb"."id" IS NOT NULL) AND "rb"."is_included") AS "explicit_block_match",
            "dense_rank"() OVER (PARTITION BY "rs"."id", "b"."id", "r"."activity_id", "r"."rate_type", "r"."rate_dimension_key", "r"."unit_name" ORDER BY "r"."priority" DESC, (("rb"."id" IS NOT NULL) AND "rb"."is_included") DESC) AS "priority_rank",
            "row_number"() OVER (PARTITION BY "rs"."id", "b"."id", "r"."activity_id", "r"."rate_type", "r"."rate_dimension_key", "r"."unit_name" ORDER BY "r"."priority" DESC, (("rb"."id" IS NOT NULL) AND "rb"."is_included") DESC, "r"."rule_code", "r"."id") AS "resolution_rank"
           FROM ((("public"."budget_rate_rule_sets" "rs"
             JOIN "public"."budget_rate_rules" "r" ON (("r"."rule_set_id" = "rs"."id")))
             CROSS JOIN "public"."blocks" "b")
             LEFT JOIN "public"."budget_rate_rule_blocks" "rb" ON ((("rb"."rule_id" = "r"."id") AND ("rb"."block_id" = "b"."id") AND ("rb"."is_included" = true))))
          WHERE (("rs"."status" <> ALL (ARRAY['rejected'::"text", 'cancelled'::"text"])) AND ("r"."status" <> ALL (ARRAY['rejected'::"text", 'cancelled'::"text", 'inactive'::"text"])) AND "public"."budget_rule_matches_block"("r"."id", "b"."id", "rs"."fiscal_year"))
        )
 SELECT "rule_set_id",
    "budget_year_id",
    "fiscal_year",
    "rule_set_status",
    "rule_id",
    "rule_code",
    "rule_name",
    "activity_id",
    "activity_code_snapshot",
    "rate_type",
    "rate_dimension_key",
    "unit_name",
    "condition_mode",
    "condition_name",
    "priority",
    "needs_mapping",
    "block_id",
    "block_code",
    "ap_code",
    "planting_year",
    "calculated_age",
    "palm_size",
    "area_rai",
    "tree_count",
    "rspo_status",
    "resolved_rate",
    "explicit_block_match",
    "priority_rank",
    "resolution_rank",
    "count"(*) FILTER (WHERE ("priority_rank" = 1)) OVER (PARTITION BY "rule_set_id", "block_id", "activity_id", "rate_type", "rate_dimension_key", "unit_name") AS "top_priority_match_count"
   FROM "matched";


--
-- Name: v_budget_rate_rule_conflicts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_budget_rate_rule_conflicts" WITH ("security_invoker"='true') AS
 SELECT "rule_set_id",
    "block_id",
    "block_code",
    "activity_id",
    "rate_type",
    "rate_dimension_key",
    "unit_name",
    "max"("top_priority_match_count") AS "conflicting_rules",
    "jsonb_agg"("jsonb_build_object"('rule_id', "rule_id", 'rule_code', "rule_code", 'rule_name', "rule_name", 'priority', "priority", 'rate', "resolved_rate") ORDER BY "priority" DESC, "rule_code") FILTER (WHERE ("priority_rank" = 1)) AS "rules"
   FROM "public"."v_budget_rate_rule_matches"
  WHERE (("top_priority_match_count" > 1) AND ("priority_rank" = 1))
  GROUP BY "rule_set_id", "block_id", "block_code", "activity_id", "rate_type", "rate_dimension_key", "unit_name";


--
-- Name: v_budget_rate_rule_editor; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_budget_rate_rule_editor" WITH ("security_invoker"='true') AS
 SELECT "rs"."id" AS "rule_set_id",
    "rs"."budget_year_id",
    "rs"."fiscal_year",
    "rs"."rule_set_code",
    "rs"."rule_set_name",
    "rs"."announcement_no",
    "rs"."announcement_date",
    "rs"."effective_from" AS "rule_set_effective_from",
    "rs"."effective_to" AS "rule_set_effective_to",
    "rs"."version_no",
    "rs"."status" AS "rule_set_status",
    "r"."id" AS "rule_id",
    "r"."rule_code",
    "r"."rule_name",
    "r"."activity_id",
    COALESCE("a"."activity_code", "r"."activity_code_snapshot") AS "activity_code",
    COALESCE("a"."activity_name", "r"."activity_name_snapshot") AS "activity_name",
    "r"."rate_type",
    "r"."rate_dimension_key",
    "r"."unit_name",
    "r"."calculation_method",
    "r"."comparison_basis",
    "r"."condition_mode",
    "r"."condition_name",
    "r"."rate_current",
    "r"."rate_proposed",
    "r"."rate_approved",
    "r"."priority",
    "r"."material_id",
    "m"."material_code",
    "m"."material_name",
    "r"."dose_from",
    "r"."dose_to",
    "r"."dose_unit",
    "r"."package_size_kg",
    "r"."worker_scope",
    "r"."contractor_id",
    "r"."effective_from",
    "r"."effective_to",
    "r"."status",
    "r"."needs_mapping",
    COALESCE("c"."conditions", '[]'::"jsonb") AS "conditions",
    COALESCE("b"."block_overrides", '[]'::"jsonb") AS "block_overrides",
    COALESCE("s"."matched_block_count", 0) AS "matched_block_count",
    COALESCE("s"."area_rai", (0)::numeric) AS "matched_area_rai",
    COALESCE("s"."tree_count", (0)::bigint) AS "matched_tree_count"
   FROM (((((("public"."budget_rate_rule_sets" "rs"
     JOIN "public"."budget_rate_rules" "r" ON (("r"."rule_set_id" = "rs"."id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "r"."activity_id")))
     LEFT JOIN "public"."materials" "m" ON (("m"."id" = "r"."material_id")))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('id', "c_1"."id", 'scope', "c_1"."condition_scope", 'key', "c_1"."condition_key", 'operator', "c_1"."operator", 'value_text', "c_1"."value_text", 'value_from', "c_1"."value_from_numeric", 'value_to', "c_1"."value_to_numeric", 'value_json', "c_1"."value_json", 'display_value', "c_1"."display_value") ORDER BY "c_1"."sort_order", "c_1"."created_at") AS "conditions"
           FROM "public"."budget_rate_rule_conditions" "c_1"
          WHERE ("c_1"."rule_id" = "r"."id")) "c" ON (true))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('id', "rb"."id", 'block_id', "rb"."block_id", 'block_code', "bl"."block_code", 'included', "rb"."is_included", 'override_rate', "rb"."override_rate", 'note', "rb"."note") ORDER BY "bl"."block_code") AS "block_overrides"
           FROM ("public"."budget_rate_rule_blocks" "rb"
             JOIN "public"."blocks" "bl" ON (("bl"."id" = "rb"."block_id")))
          WHERE ("rb"."rule_id" = "r"."id")) "b" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(DISTINCT "ss"."block_id"))::integer AS "matched_block_count",
            COALESCE("sum"(DISTINCT "ss"."area_rai_snapshot"), (0)::numeric) AS "area_rai",
            COALESCE("sum"(DISTINCT "ss"."tree_count_snapshot"), (0)::bigint) AS "tree_count"
           FROM "public"."budget_rate_block_snapshots" "ss"
          WHERE (("ss"."rule_id" = "r"."id") AND ("ss"."rule_set_id" = "rs"."id"))) "s" ON (true));


