--
-- Name: v_budget_rate_rule_validation_issues; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_budget_rate_rule_validation_issues" WITH ("security_invoker"='true') AS
 SELECT "r"."rule_set_id",
    "r"."id" AS "rule_id",
    NULL::"uuid" AS "block_id",
    'RULE_NEEDS_MAPPING'::"text" AS "issue_code",
    'กฎยังต้องตรวจสอบการเชื่อมพื้นที่'::"text" AS "issue_message"
   FROM "public"."budget_rate_rules" "r"
  WHERE ("r"."needs_mapping" AND ("r"."status" <> ALL (ARRAY['rejected'::"text", 'cancelled'::"text", 'inactive'::"text"])))
UNION ALL
 SELECT "r"."rule_set_id",
    "r"."id" AS "rule_id",
    NULL::"uuid" AS "block_id",
    'MISSING_RATE'::"text" AS "issue_code",
    'ยังไม่มีอัตราที่ใช้ได้'::"text" AS "issue_message"
   FROM "public"."budget_rate_rules" "r"
  WHERE ((COALESCE("r"."rate_approved", "r"."rate_proposed", "r"."rate_current") IS NULL) AND ("r"."status" <> ALL (ARRAY['rejected'::"text", 'cancelled'::"text", 'inactive'::"text"])))
UNION ALL
 SELECT "r"."rule_set_id",
    "r"."id" AS "rule_id",
    NULL::"uuid" AS "block_id",
    'NO_MATCHING_BLOCK'::"text" AS "issue_code",
    'กฎไม่พบบล็อกที่เข้าเงื่อนไข'::"text" AS "issue_message"
   FROM "public"."budget_rate_rules" "r"
  WHERE (("r"."status" <> ALL (ARRAY['rejected'::"text", 'cancelled'::"text", 'inactive'::"text"])) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."v_budget_rate_rule_matches" "m"
          WHERE ("m"."rule_id" = "r"."id")))))
UNION ALL
 SELECT "c"."rule_set_id",
    NULL::"uuid" AS "rule_id",
    "c"."block_id",
    'RULE_CONFLICT'::"text" AS "issue_code",
    'บล็อกได้รับกฎลำดับสูงสุดมากกว่าหนึ่งรายการ'::"text" AS "issue_message"
   FROM "public"."v_budget_rate_rule_conflicts" "c";


--
-- Name: v_budget_year_rule_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_budget_year_rule_readiness" WITH ("security_invoker"='true') AS
 SELECT "byear"."id" AS "budget_year_id",
    "byear"."fiscal_year",
    "byear"."budget_name",
    "byear"."status",
    "byear"."rule_engine_status",
    "byear"."default_rule_set_id",
    "rs"."rule_set_code",
    "rs"."rule_set_name",
    "rs"."status" AS "rule_set_status",
    "count"("bar"."id") AS "rate_count",
    "count"("bar"."rule_id") AS "linked_rule_count",
    "count"(*) FILTER (WHERE (("bar"."id" IS NOT NULL) AND ("bar"."rule_sync_status" <> ALL (ARRAY['synced'::"text", 'version_created'::"text"])))) AS "unsynced_rate_count",
    "count"(*) FILTER (WHERE (("bar"."id" IS NOT NULL) AND ("bar"."rule_id" IS NULL))) AS "missing_rule_count",
    "count"(*) FILTER (WHERE (("bar"."id" IS NOT NULL) AND "byear"."snapshot_required" AND (COALESCE("s"."snapshot_count", (0)::bigint) = 0))) AS "missing_snapshot_rate_count",
    COALESCE("bool_and"((("bar"."id" IS NULL) OR (("bar"."rule_id" IS NOT NULL) AND ("bar"."rule_sync_status" = ANY (ARRAY['synced'::"text", 'version_created'::"text"]))))), false) AS "rules_ready"
   FROM ((("public"."budget_years" "byear"
     LEFT JOIN "public"."budget_rate_rule_sets" "rs" ON (("rs"."id" = "byear"."default_rule_set_id")))
     LEFT JOIN "public"."budget_activity_rates" "bar" ON (("bar"."budget_year_id" = "byear"."id")))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "snapshot_count"
           FROM "public"."budget_rate_block_snapshots" "snap"
          WHERE ("snap"."rule_id" = "bar"."rule_id")) "s" ON (true))
  GROUP BY "byear"."id", "byear"."fiscal_year", "byear"."budget_name", "byear"."status", "byear"."rule_engine_status", "byear"."default_rule_set_id", "rs"."rule_set_code", "rs"."rule_set_name", "rs"."status";


