--
-- Name: v_farm_workflow_workspace; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_farm_workflow_workspace" WITH ("security_invoker"='true') AS
 WITH "worker_counts" AS (
         SELECT "work_order_workers"."work_order_id",
            ("count"(*))::integer AS "worker_count"
           FROM "public"."work_order_workers"
          GROUP BY "work_order_workers"."work_order_id"
        ), "material_counts" AS (
         SELECT "work_order_materials"."work_order_id",
            ("count"(*))::integer AS "material_count",
            "sum"("work_order_materials"."planned_quantity") AS "planned_material_quantity",
            "sum"("work_order_materials"."issued_quantity") AS "issued_material_quantity",
            "bool_or"((("work_order_materials"."issued_quantity" > (0)::numeric) OR ("work_order_materials"."status" = ANY (ARRAY['issued'::"text", 'used'::"text", 'returned'::"text"])))) AS "has_issued_material"
           FROM "public"."work_order_materials"
          GROUP BY "work_order_materials"."work_order_id"
        ), "machine_counts" AS (
         SELECT "work_order_machines"."work_order_id",
            ("count"(*))::integer AS "machine_count"
           FROM "public"."work_order_machines"
          GROUP BY "work_order_machines"."work_order_id"
        ), "result_counts" AS (
         SELECT "work_results"."work_order_id",
            ("count"(*))::integer AS "result_count",
            "max"("work_results"."result_date") AS "latest_result_date"
           FROM "public"."work_results"
          GROUP BY "work_results"."work_order_id"
        ), "latest_results" AS (
         SELECT DISTINCT ON ("work_results"."work_order_id") "work_results"."work_order_id",
            "work_results"."id" AS "result_id",
            "work_results"."result_status",
            "work_results"."result_date",
            "work_results"."actual_quantity",
            "work_results"."actual_unit",
            "work_results"."quality_score",
            "work_results"."completion_pct",
            "work_results"."weigh_ticket_count",
            "work_results"."actual_fuel_liter",
            "work_results"."actual_fuel_cost"
           FROM "public"."work_results"
          ORDER BY "work_results"."work_order_id", "work_results"."result_date" DESC NULLS LAST, "work_results"."sequence_no" DESC, "work_results"."created_at" DESC
        ), "issue_counts" AS (
         SELECT "goods_issues"."work_order_id",
            ("count"(*))::integer AS "issue_count"
           FROM "public"."goods_issues"
          WHERE ("goods_issues"."status" <> ALL (ARRAY['cancelled'::"text", 'rejected'::"text"]))
          GROUP BY "goods_issues"."work_order_id"
        )
 SELECT "wo"."id" AS "work_order_id",
    "wo"."work_order_no",
    "wo"."status" AS "work_order_status",
    "wo"."scheduled_date",
    "wo"."planned_work_item_id",
    "pwi"."annual_plan_id",
    "awp"."plan_year",
    "awp"."plan_name",
    "wo"."block_id",
    "b"."block_code",
    "b"."block_name",
    "b"."ap_code",
    "b"."area_rai",
    "b"."tree_count",
    "b"."rspo_status",
    "wo"."activity_id",
    "a"."activity_code",
    "a"."activity_name",
    "wo"."team_id",
    "t"."team_code",
    "t"."team_name",
    "wo"."supervisor_employee_id",
    "sup"."full_name" AS "supervisor_name",
    "wo"."manager_employee_id",
    "mgr"."full_name" AS "manager_name",
    "wo"."contractor_id",
    "wo"."planned_quantity",
    "wo"."planned_unit",
    "wo"."planned_labor_cost",
    "wo"."planned_material_cost",
    "wo"."planned_fuel_cost",
    "wo"."planned_machine_cost",
    "wo"."planned_total_cost",
    COALESCE("wc"."worker_count", 0) AS "worker_count",
    COALESCE("mc"."material_count", 0) AS "material_count",
    COALESCE("mc"."planned_material_quantity", (0)::numeric) AS "planned_material_quantity",
    COALESCE("mc"."issued_material_quantity", (0)::numeric) AS "issued_material_quantity",
    COALESCE("mc"."has_issued_material", false) AS "has_issued_material",
    COALESCE("xc"."machine_count", 0) AS "machine_count",
    COALESCE("rc"."result_count", 0) AS "result_count",
    "lr"."result_id",
    "lr"."result_status",
    "lr"."result_date",
    "lr"."actual_quantity",
    "lr"."actual_unit",
    "lr"."quality_score",
    "lr"."completion_pct",
    "lr"."weigh_ticket_count",
    "lr"."actual_fuel_liter",
    "lr"."actual_fuel_cost",
    COALESCE("ic"."issue_count", 0) AS "goods_issue_count",
    ("wo"."planned_work_item_id" IS NOT NULL) AS "plan_ready",
    (("wo"."team_id" IS NOT NULL) OR ("wo"."contractor_id" IS NOT NULL)) AS "resource_ready",
    (("wo"."contractor_id" IS NOT NULL) OR (COALESCE("wc"."worker_count", 0) > 0)) AS "workers_ready",
    ((COALESCE("mc"."material_count", 0) = 0) OR COALESCE("mc"."has_issued_material", false) OR (COALESCE("ic"."issue_count", 0) > 0)) AS "material_issue_ready",
        CASE
            WHEN ("wo"."status" = 'draft'::"text") THEN 'complete_order'::"text"
            WHEN (("wo"."team_id" IS NULL) AND ("wo"."contractor_id" IS NULL)) THEN 'assign_resource'::"text"
            WHEN (("wo"."contractor_id" IS NULL) AND (COALESCE("wc"."worker_count", 0) = 0)) THEN 'confirm_workers'::"text"
            WHEN ((COALESCE("mc"."material_count", 0) > 0) AND (NOT COALESCE("mc"."has_issued_material", false)) AND (COALESCE("ic"."issue_count", 0) = 0)) THEN 'prepare_material_issue'::"text"
            WHEN (COALESCE("rc"."result_count", 0) = 0) THEN 'record_result'::"text"
            WHEN ("lr"."result_status" = 'draft'::"text") THEN 'continue_result'::"text"
            WHEN ("lr"."result_status" = 'submitted'::"text") THEN 'verify_result'::"text"
            WHEN ("lr"."result_status" = 'verified'::"text") THEN 'close_result'::"text"
            WHEN (("wo"."status" = 'closed'::"text") OR ("lr"."result_status" = 'closed'::"text")) THEN 'view_closed'::"text"
            ELSE 'view'::"text"
        END AS "next_action",
    "wo"."workflow_source",
    "wo"."workflow_version",
    "wo"."last_action_at"
   FROM ((((((((((((("public"."work_orders" "wo"
     LEFT JOIN "public"."planned_work_items" "pwi" ON (("pwi"."id" = "wo"."planned_work_item_id")))
     LEFT JOIN "public"."annual_work_plans" "awp" ON (("awp"."id" = "pwi"."annual_plan_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "wo"."block_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."teams" "t" ON (("t"."id" = "wo"."team_id")))
     LEFT JOIN "public"."employees" "sup" ON (("sup"."id" = "wo"."supervisor_employee_id")))
     LEFT JOIN "public"."employees" "mgr" ON (("mgr"."id" = "wo"."manager_employee_id")))
     LEFT JOIN "worker_counts" "wc" ON (("wc"."work_order_id" = "wo"."id")))
     LEFT JOIN "material_counts" "mc" ON (("mc"."work_order_id" = "wo"."id")))
     LEFT JOIN "machine_counts" "xc" ON (("xc"."work_order_id" = "wo"."id")))
     LEFT JOIN "result_counts" "rc" ON (("rc"."work_order_id" = "wo"."id")))
     LEFT JOIN "latest_results" "lr" ON (("lr"."work_order_id" = "wo"."id")))
     LEFT JOIN "issue_counts" "ic" ON (("ic"."work_order_id" = "wo"."id")));


