    "f"."team_id",
    "f"."team_code",
    "f"."team_name",
    "f"."supervisor_employee_id",
    "f"."supervisor_name",
    "f"."manager_employee_id",
    "f"."manager_name",
    "f"."contractor_id",
    "f"."planned_quantity",
    "f"."planned_unit",
    "f"."planned_labor_cost",
    "f"."planned_material_cost",
    "f"."planned_fuel_cost",
    "f"."planned_machine_cost",
    "f"."planned_total_cost",
    "f"."worker_count",
    "f"."material_count",
    "f"."planned_material_quantity",
    "f"."issued_material_quantity",
    "f"."has_issued_material",
    "f"."machine_count",
    "f"."result_count",
    "f"."result_id",
    "f"."result_status",
    "f"."result_date",
    "f"."actual_quantity",
    "f"."actual_unit",
    "f"."quality_score",
    "f"."completion_pct",
