    "f"."last_action_at",
    COALESCE("a"."requires_weigh_ticket", false) AS "requires_weigh_ticket",
    COALESCE("a"."requires_worker_detail", true) AS "requires_worker_detail",
    COALESCE("a"."requires_material_detail", false) AS "requires_material_detail",
    COALESCE("a"."requires_machine_detail", false) AS "requires_machine_detail",
        CASE
            WHEN ("f"."result_id" IS NULL) THEN 'create'::"text"
            ELSE 'continue'::"text"
        END AS "entry_mode"
   FROM ("public"."v_farm_workflow_workspace" "f"
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "f"."activity_id")));


--
-- Name: v_employee_activity_performance_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_employee_activity_performance_summary" WITH ("security_invoker"='true') AS
 SELECT "m"."employee_id",
    "e"."employee_code",
    "e"."full_name",
    "m"."activity_id",
    "a"."activity_code",
    "a"."activity_name",
    "min"("m"."work_date") AS "period_start",
    "max"("m"."work_date") AS "period_end",
    "count"(*) AS "sample_count",
    "count"(DISTINCT "m"."work_date") AS "work_day_count",
    "sum"("m"."actual_quantity") AS "total_quantity",
    "sum"("m"."area_rai") AS "total_area_rai",
    "sum"("m"."tree_count") AS "total_tree_count",
    "sum"("m"."labor_hours") AS "total_labor_hours",
    "avg"("m"."person_output") AS "avg_person_output",
    "avg"("m"."tree_output") AS "avg_tree_output",
    "avg"("m"."area_output") AS "avg_area_output",
    "avg"("m"."person_efficiency_pct") AS "person_efficiency_pct",
    "avg"("m"."tree_efficiency_pct") AS "tree_efficiency_pct",
    "avg"("m"."area_efficiency_pct") AS "area_efficiency_pct",
    "avg"("m"."quality_pct") AS "quality_pct",
    "avg"("m"."quality_adjusted_efficiency_pct") AS "quality_adjusted_efficiency_pct",
    "avg"("m"."composite_efficiency_pct") AS "composite_efficiency_pct",
    "avg"("m"."capped_efficiency_pct") AS "capped_efficiency_pct",
    "avg"("m"."data_quality_pct") AS "data_quality_pct",
    "count"(*) FILTER (WHERE "m"."is_estimated") AS "estimated_sample_count",
    "count"(*) FILTER (WHERE "m"."outlier_flag") AS "outlier_count"
   FROM (("public"."work_performance_metrics" "m"
     JOIN "public"."employees" "e" ON (("e"."id" = "m"."employee_id")))
     JOIN "public"."activities" "a" ON (("a"."id" = "m"."activity_id")))
  WHERE ("m"."metric_scope" = 'employee'::"text")
  GROUP BY "m"."employee_id", "e"."employee_code", "e"."full_name", "m"."activity_id", "a"."activity_code", "a"."activity_name";


