    "d"."department_name",
    "p"."position_code",
    "p"."position_name",
    "t"."worker_type",
    "t"."payment_type",
    "t"."daily_wage",
    "t"."hourly_wage_rate",
    "t"."monthly_salary",
    "t"."contract_rate",
    "t"."normal_hours_per_day",
    "t"."effective_from",
    "t"."effective_to"
   FROM ((("public"."employees" "e"
     LEFT JOIN "public"."employee_employment_terms" "t" ON ((("t"."employee_id" = "e"."id") AND "t"."is_current")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "t"."department_id")))
     LEFT JOIN "public"."positions" "p" ON (("p"."id" = "t"."position_id")));


--
-- Name: v_employee_department_assignment_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_employee_department_assignment_queue" WITH ("security_invoker"='true') AS
 SELECT "e"."id" AS "employee_id",
    "e"."employee_code",
    "e"."full_name",
    "t"."worker_type",
    "p"."position_name",
        CASE
            WHEN (COALESCE("t"."worker_type", ''::"text") ~~* '%ตัดปาล์ม%'::"text") THEN 'DEPT-HARVEST'::"text"
            ELSE 'DEPT-FIELD'::"text"
        END AS "suggested_department_code",
        CASE
            WHEN (COALESCE("t"."worker_type", ''::"text") ~~* '%ตัดปาล์ม%'::"text") THEN 'high'::"text"
            ELSE 'review'::"text"
        END AS "suggestion_confidence",
        CASE
            WHEN (COALESCE("t"."worker_type", ''::"text") ~~* '%ตัดปาล์ม%'::"text") THEN 'ประเภทงานเกี่ยวข้องกับการเก็บเกี่ยว'::"text"
            ELSE 'ต้องตรวจสอบก่อนยืนยันฝ่าย'::"text"
        END AS "suggestion_reason"
   FROM (("public"."employees" "e"
     JOIN "public"."employee_employment_terms" "t" ON ((("t"."employee_id" = "e"."id") AND "t"."is_current")))
     LEFT JOIN "public"."positions" "p" ON (("p"."id" = "t"."position_id")))
  WHERE ("t"."department_id" IS NULL);


