--
-- Name: work_result_workers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."work_result_workers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_result_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "team_id" "uuid",
    "work_date" "date" NOT NULL,
    "worker_role" "text",
    "attendance_status" "text",
    "actual_hours" numeric DEFAULT 0 NOT NULL,
    "actual_quantity" numeric DEFAULT 0 NOT NULL,
    "actual_unit" "text",
    "rate_type" "text",
    "rate_amount" numeric DEFAULT 0 NOT NULL,
    "earning_amount" numeric DEFAULT 0 NOT NULL,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actual_area_rai" numeric(18,4),
    "actual_tree_count" integer,
    "individual_quality_pct" numeric(7,2),
    "individual_completion_pct" numeric(7,2),
    "quantity_allocation_method" "text" DEFAULT 'manual'::"text" NOT NULL,
    "is_quantity_estimated" boolean DEFAULT false NOT NULL,
    CONSTRAINT "work_result_workers_nonnegative_chk" CHECK ((("actual_hours" >= (0)::numeric) AND ("actual_quantity" >= (0)::numeric) AND ("rate_amount" >= (0)::numeric) AND ("earning_amount" >= (0)::numeric)))
);


--
-- Name: v_farm_daily_workforce_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_farm_daily_workforce_summary" WITH ("security_invoker"='true') AS
 WITH "worker_totals" AS (
         SELECT "work_result_workers"."work_result_id",
            "count"(DISTINCT "work_result_workers"."employee_id") AS "worker_count",
            COALESCE("sum"("work_result_workers"."actual_hours"), (0)::numeric) AS "actual_hours",
            COALESCE("sum"("work_result_workers"."earning_amount"), (0)::numeric) AS "labor_earning"
           FROM "public"."work_result_workers"
          GROUP BY "work_result_workers"."work_result_id"
        ), "weight_totals" AS (
         SELECT "work_result_weight_tickets"."work_result_id",
            "count"(*) FILTER (WHERE ("work_result_weight_tickets"."link_status" <> 'cancelled'::"text")) AS "ticket_count",
            COALESCE("sum"("work_result_weight_tickets"."allocated_weight_kg") FILTER (WHERE ("work_result_weight_tickets"."link_status" <> 'cancelled'::"text")), (0)::numeric) AS "allocated_weight_kg"
           FROM "public"."work_result_weight_tickets"
          GROUP BY "work_result_weight_tickets"."work_result_id"
        )
 SELECT "wr"."result_date",
    "wr"."id" AS "work_result_id",
    "wr"."result_no",
    "wo"."id" AS "work_order_id",
    "wo"."work_order_no",
    "a"."activity_code",
    "a"."activity_name",
    "b"."block_name" AS "terrain_code",
    "t"."team_code",
    "t"."team_name",
    "wr"."result_status",
    "wr"."source_type",
    "wr"."actual_quantity",
    "wr"."actual_unit",
    COALESCE("wt"."ticket_count", (0)::bigint) AS "weigh_ticket_count",
    COALESCE("wt"."allocated_weight_kg", (0)::numeric) AS "allocated_weight_kg",
    COALESCE("wkr"."worker_count", (0)::bigint) AS "worker_count",
    COALESCE("wkr"."actual_hours", (0)::numeric) AS "actual_hours",
    COALESCE("wkr"."labor_earning", (0)::numeric) AS "labor_earning"
   FROM (((((("public"."work_results" "wr"
     LEFT JOIN "public"."work_orders" "wo" ON (("wo"."id" = "wr"."work_order_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "wo"."block_id")))
     LEFT JOIN "public"."teams" "t" ON (("t"."id" = "wo"."team_id")))
     LEFT JOIN "worker_totals" "wkr" ON (("wkr"."work_result_id" = "wr"."id")))
     LEFT JOIN "weight_totals" "wt" ON (("wt"."work_result_id" = "wr"."id")));


--
-- Name: v_farm_work_orders_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_farm_work_orders_readable" WITH ("security_invoker"='true') AS
 SELECT "wo"."work_order_no",
    "wo"."scheduled_date",
    "wo"."status" AS "work_order_status",
    "a"."activity_code",
    "a"."activity_name",
    "b"."block_name" AS "terrain_code",
    "b"."block_code" AS "short_block_code",
    "b"."ap_code",
    "b"."rspo_status",
    "wo"."planned_quantity",
    "wo"."planned_unit",
    "wo"."planned_labor_cost",
    "wo"."planned_material_cost",
    "wo"."planned_fuel_cost",
    "wo"."planned_machine_cost",
    "wo"."planned_total_cost",
    "wo"."note",
    "wo"."created_at",
    "wo"."updated_at"
   FROM (("public"."work_orders" "wo"
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "wo"."block_id")));


