    "minimum_fuel_liter" numeric DEFAULT 0 NOT NULL,
    "reorder_point_liter" numeric DEFAULT 0 NOT NULL,
    "safety_stock_liter" numeric DEFAULT 0 NOT NULL,
    "target_fill_percent" numeric DEFAULT 90 NOT NULL,
    "minimum_operating_percent" numeric DEFAULT 10 NOT NULL,
    "fuel_measurement_basis" "text" DEFAULT 'engine_hours'::"text" NOT NULL,
    "standard_liter_per_hour" numeric,
    "standard_km_per_liter" numeric,
