--
-- Name: v_vehicle_fuel_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_vehicle_fuel_status" WITH ("security_invoker"='true') AS
 SELECT "v"."id" AS "vehicle_id",
    "v"."vehicle_code",
    "v"."vehicle_name",
    "v"."vehicle_type",
    "v"."plate_no",
    "v"."fuel_type",
    "v"."tank_capacity_liter",
    "b"."current_estimated_liter",
    "b"."average_unit_cost",
    "v"."reorder_point_liter",
    "v"."safety_stock_liter",
    COALESCE("p"."projected_usage_liter", (0)::numeric) AS "projected_usage_liter",
    ("b"."current_estimated_liter" - COALESCE("p"."projected_usage_liter", (0)::numeric)) AS "projected_balance_liter",
    GREATEST((LEAST("v"."tank_capacity_liter", (("v"."tank_capacity_liter" * "v"."target_fill_percent") / 100.0)) - "b"."current_estimated_liter"), ((COALESCE("p"."projected_usage_liter", (0)::numeric) + "v"."safety_stock_liter") - "b"."current_estimated_liter"), (0)::numeric) AS "recommended_refill_liter",
        CASE
            WHEN ("v"."tank_capacity_liter" <= (0)::numeric) THEN 'not_configured'::"text"
            WHEN ("b"."current_estimated_liter" <= "v"."minimum_fuel_liter") THEN 'critical'::"text"
            WHEN ("b"."current_estimated_liter" <= "v"."reorder_point_liter") THEN 'reorder'::"text"
            WHEN (("b"."current_estimated_liter" - COALESCE("p"."projected_usage_liter", (0)::numeric)) < "v"."safety_stock_liter") THEN 'projected_shortage'::"text"
            ELSE 'normal'::"text"
        END AS "fuel_status",
    "r"."id" AS "open_requisition_id",
    "r"."status" AS "open_requisition_status",
    "b"."last_refill_at",
    "b"."last_measurement_at",
    "b"."last_odometer",
    "b"."last_hour_meter"
   FROM ((("public"."vehicles" "v"
     JOIN "public"."vehicle_fuel_balances" "b" ON (("b"."vehicle_id" = "v"."id")))
     LEFT JOIN LATERAL ( SELECT COALESCE("sum"(GREATEST((COALESCE("m"."fuel_plan_liter", (0)::numeric) - COALESCE("m"."fuel_actual_liter", (0)::numeric)), (0)::numeric)), (0)::numeric) AS "projected_usage_liter"
           FROM ("public"."work_order_machines" "m"
             JOIN "public"."work_orders" "w" ON (("w"."id" = "m"."work_order_id")))
          WHERE (("m"."vehicle_id" = "v"."id") AND ("m"."status" <> ALL (ARRAY['cancelled'::"text", 'closed'::"text"])) AND ("w"."status" <> ALL (ARRAY['cancelled'::"text", 'closed'::"text", 'completed'::"text", 'done'::"text"])))) "p" ON (true))
     LEFT JOIN LATERAL ( SELECT "q"."id",
            "q"."status"
           FROM "public"."fuel_requisitions" "q"
          WHERE (("q"."vehicle_id" = "v"."id") AND ("q"."status" = ANY (ARRAY['suggested'::"text", 'draft'::"text", 'pending'::"text", 'approved'::"text", 'partially_issued'::"text"])))
          ORDER BY "q"."created_at" DESC
         LIMIT 1) "r" ON (true));


--
-- Name: vehicle_fuel_efficiency_standards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."vehicle_fuel_efficiency_standards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
