    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vehicle_fuel_standard_dates_chk" CHECK ((("effective_to" IS NULL) OR ("effective_to" >= "effective_from"))),
    CONSTRAINT "vehicle_fuel_standard_rate_chk" CHECK (("standard_rate" > (0)::numeric))
);


--
-- Name: work_result_vehicle_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."work_result_vehicle_usage" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
