    "working_hours" numeric DEFAULT 0 NOT NULL,
    "idle_hours" numeric DEFAULT 0 NOT NULL,
    "actual_area_rai" numeric DEFAULT 0 NOT NULL,
    "actual_tree_count" integer DEFAULT 0 NOT NULL,
    "actual_quantity" numeric DEFAULT 0 NOT NULL,
    "actual_unit" "text",
    "allocation_basis_value" numeric DEFAULT 0 NOT NULL,
    "allocated_fuel_liter" numeric DEFAULT 0 NOT NULL,
