    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "work_result_vehicle_usage_meter_chk" CHECK (((("start_odometer" IS NULL) OR ("end_odometer" IS NULL) OR ("end_odometer" >= "start_odometer")) AND (("start_hour_meter" IS NULL) OR ("end_hour_meter" IS NULL) OR ("end_hour_meter" >= "start_hour_meter")))),
    CONSTRAINT "work_result_vehicle_usage_nonnegative_chk" CHECK ((("distance_km" >= (0)::numeric) AND ("engine_hours" >= (0)::numeric) AND ("working_hours" >= (0)::numeric) AND ("idle_hours" >= (0)::numeric) AND ("allocated_fuel_liter" >= (0)::numeric) AND ("fuel_cost_amount" >= (0)::numeric)))
);


--
-- Name: v_work_result_vehicle_fuel_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_work_result_vehicle_fuel_detail" WITH ("security_invoker"='true') AS
 SELECT "u"."id",
    "u"."work_result_id",
    "u"."work_order_id",
    "u"."vehicle_id",
    "u"."consumption_period_id",
    "u"."driver_employee_id",
    "u"."start_at",
    "u"."end_at",
    "u"."start_odometer",
    "u"."end_odometer",
    "u"."start_hour_meter",
    "u"."end_hour_meter",
    "u"."distance_km",
    "u"."engine_hours",
    "u"."working_hours",
    "u"."idle_hours",
    "u"."actual_area_rai",
    "u"."actual_tree_count",
    "u"."actual_quantity",
    "u"."actual_unit",
    "u"."allocation_basis_value",
    "u"."allocated_fuel_liter",
    "u"."fuel_cost_amount",
    "u"."allocation_method",
    "u"."status",
    "u"."note",
    "u"."created_at",
    "u"."updated_at",
    "w"."work_order_no",
    "wr"."result_no",
    "wr"."result_date",
    "a"."activity_code",
    "a"."activity_name",
    "b"."block_code",
    "v"."vehicle_code",
    "v"."vehicle_name",
    "e"."employee_code" AS "driver_code",
    "e"."full_name" AS "driver_name",
        CASE
            WHEN ("u"."engine_hours" > (0)::numeric) THEN ("u"."allocated_fuel_liter" / "u"."engine_hours")
            ELSE NULL::numeric
        END AS "actual_liter_per_hour",
        CASE
            WHEN ("u"."distance_km" > (0)::numeric) THEN ("u"."distance_km" / "u"."allocated_fuel_liter")
            ELSE NULL::numeric
        END AS "actual_km_per_liter",
        CASE
            WHEN ("u"."actual_area_rai" > (0)::numeric) THEN ("u"."allocated_fuel_liter" / "u"."actual_area_rai")
            ELSE NULL::numeric
        END AS "actual_liter_per_rai",
    "s"."metric_basis" AS "standard_metric_basis",
    "s"."standard_rate",
        CASE
            WHEN ("s"."standard_rate" IS NULL) THEN NULL::numeric
            WHEN (("s"."metric_basis" = 'liter_per_hour'::"text") AND ("u"."engine_hours" > (0)::numeric) AND ("u"."allocated_fuel_liter" > (0)::numeric)) THEN (("s"."standard_rate" / ("u"."allocated_fuel_liter" / "u"."engine_hours")) * (100)::numeric)
            WHEN (("s"."metric_basis" = 'km_per_liter'::"text") AND ("u"."allocated_fuel_liter" > (0)::numeric)) THEN ((("u"."distance_km" / "u"."allocated_fuel_liter") / "s"."standard_rate") * (100)::numeric)
            WHEN (("s"."metric_basis" = 'liter_per_rai'::"text") AND ("u"."actual_area_rai" > (0)::numeric) AND ("u"."allocated_fuel_liter" > (0)::numeric)) THEN (("s"."standard_rate" / ("u"."allocated_fuel_liter" / "u"."actual_area_rai")) * (100)::numeric)
            ELSE NULL::numeric
        END AS "fuel_efficiency_pct"
   FROM ((((((("public"."work_result_vehicle_usage" "u"
     JOIN "public"."work_results" "wr" ON (("wr"."id" = "u"."work_result_id")))
     JOIN "public"."work_orders" "w" ON (("w"."id" = "u"."work_order_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "w"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "w"."block_id")))
     JOIN "public"."vehicles" "v" ON (("v"."id" = "u"."vehicle_id")))
     LEFT JOIN "public"."employees" "e" ON (("e"."id" = "u"."driver_employee_id")))
     LEFT JOIN LATERAL ( SELECT "fs"."id",
            "fs"."vehicle_id",
            "fs"."activity_id",
            "fs"."condition_group",
            "fs"."metric_basis",
            "fs"."standard_rate",
            "fs"."warning_variance_pct",
            "fs"."critical_variance_pct",
            "fs"."effective_from",
            "fs"."effective_to",
            "fs"."status",
            "fs"."approved_by_profile_id",
            "fs"."approved_at",
            "fs"."note",
            "fs"."created_at",
            "fs"."updated_at"
           FROM "public"."vehicle_fuel_efficiency_standards" "fs"
          WHERE (("fs"."vehicle_id" = "u"."vehicle_id") AND (("fs"."activity_id" = "w"."activity_id") OR ("fs"."activity_id" IS NULL)) AND ("fs"."status" = 'approved'::"text") AND ((COALESCE("wr"."result_date", CURRENT_DATE) >= "fs"."effective_from") AND (COALESCE("wr"."result_date", CURRENT_DATE) <= COALESCE("fs"."effective_to", '9999-12-31'::"date"))))
          ORDER BY ("fs"."activity_id" IS NOT NULL) DESC, "fs"."effective_from" DESC
         LIMIT 1) "s" ON (true));


--
-- Name: vehicle_fuel_consumption_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."vehicle_fuel_consumption_periods" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
