    "closing_balance_liter" numeric,
    "consumed_liter" numeric DEFAULT 0 NOT NULL,
    "allocation_method" "text" DEFAULT 'engine_hours'::"text" NOT NULL,
    "average_unit_cost" numeric DEFAULT 0 NOT NULL,
    "fuel_cost_amount" numeric DEFAULT 0 NOT NULL,
    "unallocated_liter" numeric DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "closed_by_profile_id" "uuid",
    "closed_at" timestamp with time zone,
    "verified_by_profile_id" "uuid",
    "verified_at" timestamp with time zone,
    "applied_at" timestamp with time zone,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vehicle_fuel_period_balance_chk" CHECK ((("opening_balance_liter" >= (0)::numeric) AND ("refill_liter" >= (0)::numeric) AND ("consumed_liter" >= (0)::numeric) AND (("closing_balance_liter" IS NULL) OR ("closing_balance_liter" >= (0)::numeric))))
);


--
-- Name: v_fuel_control_exceptions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_fuel_control_exceptions" WITH ("security_invoker"='true') AS
 SELECT 'vehicle_low_fuel'::"text" AS "exception_type",
    ("v"."vehicle_id")::"text" AS "entity_id",
    (("v"."vehicle_code" || ' '::"text") || "v"."vehicle_name") AS "entity_name",
    "v"."fuel_status" AS "severity",
    "v"."current_estimated_liter" AS "observed_value",
    "v"."recommended_refill_liter" AS "expected_value",
    'รถมีน้ำมันต่ำหรือคาดว่าจะไม่พอกับงาน'::"text" AS "description"
   FROM "public"."v_vehicle_fuel_status" "v"
  WHERE (("v"."fuel_status" <> 'normal'::"text") AND ("v"."fuel_status" <> 'not_configured'::"text"))
UNION ALL
 SELECT 'unallocated_consumption'::"text" AS "exception_type",
    ("p"."id")::"text" AS "entity_id",
    (("v"."vehicle_code" || ' '::"text") || "v"."vehicle_name") AS "entity_name",
        CASE
            WHEN ("p"."unallocated_liter" > 0.05) THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "severity",
    "p"."unallocated_liter" AS "observed_value",
    0 AS "expected_value",
    'น้ำมันใช้จริงยังจัดสรรเข้าใบงานไม่ครบ'::"text" AS "description"
   FROM ("public"."vehicle_fuel_consumption_periods" "p"
     JOIN "public"."vehicles" "v" ON (("v"."id" = "p"."vehicle_id")))
  WHERE (("p"."applied_at" IS NOT NULL) AND ("p"."unallocated_liter" > 0.05))
UNION ALL
 SELECT 'fuel_efficiency'::"text" AS "exception_type",
    ("d"."id")::"text" AS "entity_id",
    (("d"."vehicle_code" || ' / '::"text") || "d"."work_order_no") AS "entity_name",
        CASE
            WHEN ("d"."fuel_efficiency_pct" < (80)::numeric) THEN 'critical'::"text"
            WHEN ("d"."fuel_efficiency_pct" < (90)::numeric) THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "severity",
    "d"."fuel_efficiency_pct" AS "observed_value",
    100 AS "expected_value",
    'ประสิทธิภาพน้ำมันต่ำกว่ามาตรฐาน'::"text" AS "description"
   FROM "public"."v_work_result_vehicle_fuel_detail" "d"
  WHERE (("d"."fuel_efficiency_pct" IS NOT NULL) AND ("d"."fuel_efficiency_pct" < (90)::numeric));


--
-- Name: v_fuel_tank_setup_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_fuel_tank_setup_queue" WITH ("security_invoker"='true') AS
 SELECT "id" AS "tank_id",
    "tank_code",
    "tank_name",
    "fuel_type",
    "capacity_liter",
    "current_balance_liter",
    "current_unit_cost",
    "reorder_point_liter",
    "safety_stock_liter",
    "target_fill_percent",
        CASE
            WHEN (COALESCE("fuel_type", ''::"text") = ''::"text") THEN 'missing_fuel_type'::"text"
            WHEN (COALESCE("capacity_liter", (0)::numeric) <= (0)::numeric) THEN 'missing_capacity'::"text"
            WHEN (COALESCE("reorder_point_liter", (0)::numeric) <= (0)::numeric) THEN 'missing_reorder_point'::"text"
            WHEN (COALESCE("safety_stock_liter", (0)::numeric) <= (0)::numeric) THEN 'missing_safety_stock'::"text"
            ELSE 'ready'::"text"
        END AS "setup_status"
   FROM "public"."fuel_tanks" "t"
  WHERE ("status" = 'active'::"text");


--
-- Name: v_goods_issue_multi_day_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_goods_issue_multi_day_status" WITH ("security_invoker"='true') AS
 SELECT "gi"."id",
    "gi"."issue_no",
    "gi"."warehouse_id",
    "gi"."work_order_id",
    "gi"."work_result_id",
    "gi"."issue_date",
    COALESCE("gi"."issue_start_date", "gi"."issue_date") AS "issue_start_date",
    COALESCE("gi"."issue_end_date", "gi"."issue_date") AS "issue_end_date",
    "gi"."allow_multi_day",
    "gi"."status",
    "gi"."usage_status",
    "gi"."issued_to_employee_id",
    "gil"."id" AS "goods_issue_line_id",
    "gil"."material_id",
    "m"."material_code",
    "m"."material_name",
    "gil"."quantity" AS "issued_quantity",
    "gil"."unit_id" AS "issued_unit_id",
    "u"."unit_name" AS "issued_unit_name",
    COALESCE("us"."used_quantity", (0)::numeric) AS "used_quantity",
    COALESCE("rt"."returned_quantity", (0)::numeric) AS "returned_quantity",
    GREATEST((("gil"."quantity" - COALESCE("us"."used_quantity", (0)::numeric)) - COALESCE("rt"."returned_quantity", (0)::numeric)), (0)::numeric) AS "outstanding_quantity",
    COALESCE("us"."usage_day_count", (0)::bigint) AS "usage_day_count",
    "us"."first_usage_date",
    "us"."last_usage_date"
   FROM ((((("public"."goods_issues" "gi"
     JOIN "public"."goods_issue_lines" "gil" ON (("gil"."issue_id" = "gi"."id")))
     JOIN "public"."materials" "m" ON (("m"."id" = "gil"."material_id")))
     LEFT JOIN "public"."units" "u" ON (("u"."id" = "gil"."unit_id")))
     LEFT JOIN LATERAL ( SELECT "sum"("x"."issue_unit_quantity") AS "used_quantity",
            "count"(DISTINCT "x"."usage_date") AS "usage_day_count",
            "min"("x"."usage_date") AS "first_usage_date",
            "max"("x"."usage_date") AS "last_usage_date"
           FROM "public"."goods_issue_daily_usage" "x"
          WHERE (("x"."goods_issue_line_id" = "gil"."id") AND ("x"."status" <> 'cancelled'::"text"))) "us" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("public"."convert_material_quantity"("gil"."material_id", "x"."quantity", "x"."unit_id", "gil"."unit_id")) AS "returned_quantity"
           FROM ("public"."goods_return_lines" "x"
             JOIN "public"."goods_returns" "h" ON (("h"."id" = "x"."return_id")))
          WHERE (("x"."goods_issue_line_id" = "gil"."id") AND ("h"."status" = 'posted'::"text"))) "rt" ON (true));


--
-- Name: VIEW "v_goods_issue_multi_day_status"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW "public"."v_goods_issue_multi_day_status" IS 'สรุปยอดจ่าย ใช้รายวัน คืน และคงเหลือของใบจ่ายหลายวัน';


--
-- Name: v_goods_return_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_goods_return_readiness" WITH ("security_invoker"='true') AS
 SELECT "id" AS "goods_issue_id",
    "issue_no",
    "work_order_id",
    "warehouse_id",
    "goods_issue_line_id",
    "material_id",
    "material_code",
    "material_name",
    "issued_quantity",
    "issued_unit_id",
    "issued_unit_name",
    "used_quantity",
    "returned_quantity",
    "outstanding_quantity",
    "usage_day_count",
        CASE
            WHEN ("status" <> 'posted'::"text") THEN 'issue_not_posted'::"text"
            WHEN ("usage_status" = 'closed'::"text") THEN 'closed'::"text"
            WHEN ("outstanding_quantity" > (0)::numeric) THEN 'return_or_use_required'::"text"
            ELSE 'ready_to_close'::"text"
        END AS "return_readiness"
   FROM "public"."v_goods_issue_multi_day_status" "v";


