);


--
-- Name: v_hr_attendance_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_attendance_summary" WITH ("security_invoker"='true') AS
 SELECT "employee_id",
    ("date_trunc"('month'::"text", "check_in_at"))::"date" AS "attendance_month",
    ("count"(*))::integer AS "attendance_count",
    ("count"(*) FILTER (WHERE ("check_out_at" IS NULL)))::integer AS "missing_checkout_count",
    ("count"(*) FILTER (WHERE ("attendance_status" = 'late'::"text")))::integer AS "late_count",
    (COALESCE("sum"((EXTRACT(epoch FROM ("check_out_at" - "check_in_at")) / (3600)::numeric)) FILTER (WHERE ("check_out_at" IS NOT NULL)), (0)::numeric))::numeric(14,2) AS "worked_hours"
   FROM "public"."work_attendance" "attendance"
  WHERE (("employee_id" IS NOT NULL) AND ("check_in_at" IS NOT NULL))
  GROUP BY "employee_id", (("date_trunc"('month'::"text", "check_in_at"))::"date");


--
-- Name: v_hr_document_compliance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_document_compliance" WITH ("security_invoker"='true') AS
 SELECT "employee"."id" AS "employee_id",
    "employee"."employee_code",
    "employee"."full_name",
    ("count"("document"."id"))::integer AS "document_count",
    ("count"("document"."id") FILTER (WHERE ("document"."status" = 'active'::"text")))::integer AS "active_count",
    ("count"("document"."id") FILTER (WHERE ("document"."expiry_date" < CURRENT_DATE)))::integer AS "expired_count",
    ("count"("document"."id") FILTER (WHERE (("document"."expiry_date" >= CURRENT_DATE) AND ("document"."expiry_date" <= (CURRENT_DATE + 7)))))::integer AS "due_7_count",
    ("count"("document"."id") FILTER (WHERE (("document"."expiry_date" >= CURRENT_DATE) AND ("document"."expiry_date" <= (CURRENT_DATE + 30)))))::integer AS "due_30_count",
    ("count"("document"."id") FILTER (WHERE (("document"."expiry_date" >= CURRENT_DATE) AND ("document"."expiry_date" <= (CURRENT_DATE + 60)))))::integer AS "due_60_count",
    ("count"("document"."id") FILTER (WHERE (("document"."expiry_date" >= CURRENT_DATE) AND ("document"."expiry_date" <= (CURRENT_DATE + 90)))))::integer AS "due_90_count",
    ("count"("document"."id") FILTER (WHERE ("document"."status" = 'in_renewal'::"text")))::integer AS "in_renewal_count"
   FROM ("public"."employees" "employee"
     LEFT JOIN "public"."employee_documents" "document" ON ((("document"."employee_id" = "employee"."id") AND ("document"."archived_at" IS NULL))))
  WHERE ("employee"."is_current" IS TRUE)
  GROUP BY "employee"."id", "employee"."employee_code", "employee"."full_name";


--
-- Name: v_hr_document_expiry; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_document_expiry" WITH ("security_invoker"='true') AS
 SELECT "document"."id" AS "document_id",
    "document"."employee_id",
    "employee"."employee_code",
    "employee"."full_name",
    "document"."document_type_id",
    "document_type"."document_type_code",
    "document_type"."document_type_name_th",
    "document"."document_number_masked",
    "document"."expiry_date",
    ("document"."expiry_date" - CURRENT_DATE) AS "days_to_expiry",
    "document"."status",
    "document"."verification_status",
    "document"."renewal_case_id"
   FROM (("public"."employee_documents" "document"
     JOIN "public"."employees" "employee" ON (("employee"."id" = "document"."employee_id")))
     JOIN "public"."employee_document_types" "document_type" ON (("document_type"."id" = "document"."document_type_id")))
  WHERE (("document"."archived_at" IS NULL) AND ("document"."expiry_date" IS NOT NULL));


--
-- Name: v_hr_employee_360; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_employee_360" WITH ("security_invoker"='true') AS
 SELECT "employee"."id" AS "employee_id",
    "employee"."employee_code",
    "employee"."full_name",
    "employee"."nationality",
    "employee"."employee_type",
    "employee"."status" AS "employee_status",
    "employee"."start_date",
    "employee"."end_date",
    "term"."department_id",
    "department"."department_code",
    "department"."department_name",
    "term"."position_id",
    "position"."position_code",
    "position"."position_name",
    "term"."worker_type",
    "term"."payment_type",
    "migrant"."current_compliance_status",
    "migrant"."passport_reference_masked",
    COALESCE("document_summary"."document_count", 0) AS "document_count",
    COALESCE("document_summary"."expired_document_count", 0) AS "expired_document_count",
    COALESCE("document_summary"."due_90_document_count", 0) AS "due_90_document_count",
    COALESCE("renewal_summary"."open_renewal_count", 0) AS "open_renewal_count",
    COALESCE("emergency_contact"."has_emergency_contact", false) AS "has_emergency_contact"
   FROM ((((((("public"."employees" "employee"
     LEFT JOIN "public"."employee_employment_terms" "term" ON ((("term"."employee_id" = "employee"."id") AND ("term"."is_current" IS TRUE))))
     LEFT JOIN "public"."departments" "department" ON (("department"."id" = "term"."department_id")))
     LEFT JOIN "public"."positions" "position" ON (("position"."id" = "term"."position_id")))
     LEFT JOIN "public"."employee_migrant_profiles" "migrant" ON (("migrant"."employee_id" = "employee"."id")))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "document_count",
            ("count"(*) FILTER (WHERE ("document"."expiry_date" < CURRENT_DATE)))::integer AS "expired_document_count",
            ("count"(*) FILTER (WHERE (("document"."expiry_date" >= CURRENT_DATE) AND ("document"."expiry_date" <= (CURRENT_DATE + 90)))))::integer AS "due_90_document_count"
           FROM "public"."employee_documents" "document"
          WHERE (("document"."employee_id" = "employee"."id") AND ("document"."archived_at" IS NULL))) "document_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "open_renewal_count"
           FROM "public"."employee_renewal_cases" "renewal"
          WHERE (("renewal"."employee_id" = "employee"."id") AND ("renewal"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text", 'rejected'::"text"])))) "renewal_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT true AS "has_emergency_contact"
           FROM "public"."employee_emergency_contacts" "contact"
          WHERE (("contact"."employee_id" = "employee"."id") AND ("contact"."status" = 'active'::"text"))
         LIMIT 1) "emergency_contact" ON (true))
  WHERE ("employee"."is_current" IS TRUE);


--
-- Name: v_hr_employee_data_quality; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_employee_data_quality" WITH ("security_invoker"='true') AS
 SELECT "employee"."id" AS "employee_id",
    "employee"."employee_code",
    "employee"."full_name",
    ("term"."department_id" IS NULL) AS "missing_department",
    (NULLIF("btrim"("employee"."nationality"), ''::"text") IS NULL) AS "missing_nationality",
    (NULLIF("btrim"("employee"."phone"), ''::"text") IS NULL) AS "missing_phone",
    (NULLIF("btrim"("employee"."id_card_no"), ''::"text") IS NULL) AS "missing_identification",
    ("term"."id" IS NULL) AS "missing_current_employment_term",
    ("contact"."id" IS NULL) AS "missing_emergency_contact",
    COALESCE("requirement"."missing_required_document_count", 0) AS "missing_required_document_count",
    (((((((("term"."department_id" IS NULL))::integer + ((NULLIF("btrim"("employee"."nationality"), ''::"text") IS NULL))::integer) + ((NULLIF("btrim"("employee"."phone"), ''::"text") IS NULL))::integer) + ((NULLIF("btrim"("employee"."id_card_no"), ''::"text") IS NULL))::integer) + (("term"."id" IS NULL))::integer) + (("contact"."id" IS NULL))::integer) + ((COALESCE("requirement"."missing_required_document_count", 0) > 0))::integer) AS "issue_count"
   FROM ((("public"."employees" "employee"
     LEFT JOIN "public"."employee_employment_terms" "term" ON ((("term"."employee_id" = "employee"."id") AND ("term"."is_current" IS TRUE))))
     LEFT JOIN LATERAL ( SELECT "emergency"."id"
           FROM "public"."employee_emergency_contacts" "emergency"
          WHERE (("emergency"."employee_id" = "employee"."id") AND ("emergency"."status" = 'active'::"text"))
         LIMIT 1) "contact" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "missing_required_document_count"
           FROM "public"."employee_document_requirements" "required"
          WHERE (("required"."status" = 'active'::"text") AND ("required"."is_required" IS TRUE) AND ((CURRENT_DATE >= "required"."effective_from") AND (CURRENT_DATE <= COALESCE("required"."effective_to", 'infinity'::"date"))) AND (("required"."nationality" IS NULL) OR ("required"."nationality" = "employee"."nationality")) AND (("required"."worker_type" IS NULL) OR ("required"."worker_type" = "term"."worker_type")) AND (("required"."employee_type" IS NULL) OR ("required"."employee_type" = "employee"."employee_type")) AND (("required"."position_id" IS NULL) OR ("required"."position_id" = "term"."position_id")) AND (("required"."department_id" IS NULL) OR ("required"."department_id" = "term"."department_id")) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."employee_documents" "document"
                  WHERE (("document"."employee_id" = "employee"."id") AND ("document"."document_type_id" = "required"."document_type_id") AND ("document"."status" = ANY (ARRAY['active'::"text", 'due_soon'::"text", 'in_renewal'::"text"])) AND ("document"."archived_at" IS NULL))))))) "requirement" ON (true))
  WHERE ("employee"."is_current" IS TRUE);


--
-- Name: v_hr_employee_turnover; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_employee_turnover" WITH ("security_invoker"='true') AS
 SELECT ("date_trunc"('month'::"text", (COALESCE("end_date", "start_date"))::timestamp with time zone))::"date" AS "event_month",
    ("count"(*) FILTER (WHERE ("start_date" IS NOT NULL)))::integer AS "joined_count",
    ("count"(*) FILTER (WHERE ("end_date" IS NOT NULL)))::integer AS "left_count",
    ("avg"((COALESCE("end_date", CURRENT_DATE) - "start_date")) FILTER (WHERE ("start_date" IS NOT NULL)))::numeric(14,2) AS "average_tenure_days"
   FROM "public"."employees" "employee"
  WHERE ("is_current" IS TRUE)
  GROUP BY (("date_trunc"('month'::"text", (COALESCE("end_date", "start_date"))::timestamp with time zone))::"date");


--
-- Name: v_hr_headcount_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_headcount_summary" WITH ("security_invoker"='true') AS
 SELECT "employee"."status" AS "employee_status",
    COALESCE(NULLIF("employee"."nationality", ''::"text"), 'unspecified'::"text") AS "nationality",
    "term"."department_id",
    "department"."department_name",
    "term"."position_id",
    "position"."position_name",
    COALESCE("term"."worker_type", 'unspecified'::"text") AS "worker_type",
    COALESCE("term"."payment_type", 'unspecified'::"text") AS "payment_type",
    ("count"(*))::integer AS "employee_count"
   FROM ((("public"."employees" "employee"
     LEFT JOIN "public"."employee_employment_terms" "term" ON ((("term"."employee_id" = "employee"."id") AND ("term"."is_current" IS TRUE))))
     LEFT JOIN "public"."departments" "department" ON (("department"."id" = "term"."department_id")))
     LEFT JOIN "public"."positions" "position" ON (("position"."id" = "term"."position_id")))
  WHERE ("employee"."is_current" IS TRUE)
  GROUP BY "employee"."status", COALESCE(NULLIF("employee"."nationality", ''::"text"), 'unspecified'::"text"), "term"."department_id", "department"."department_name", "term"."position_id", "position"."position_name", COALESCE("term"."worker_type", 'unspecified'::"text"), COALESCE("term"."payment_type", 'unspecified'::"text");


--
-- Name: v_hr_migrant_compliance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_migrant_compliance" WITH ("security_invoker"='true') AS
 SELECT "migrant"."employee_id",
    "employee"."employee_code",
    "employee"."full_name",
    "migrant"."nationality",
    "migrant"."current_compliance_status",
    "migrant"."assigned_hr_profile_id",
    COALESCE("document_summary"."document_count", 0) AS "document_count",
    COALESCE("document_summary"."expired_count", 0) AS "expired_count",
    COALESCE("renewal_summary"."open_renewal_count", 0) AS "open_renewal_count",
    COALESCE("renewal_summary"."completed_renewal_cost", (0)::numeric) AS "completed_renewal_cost"
   FROM ((("public"."employee_migrant_profiles" "migrant"
     JOIN "public"."employees" "employee" ON (("employee"."id" = "migrant"."employee_id")))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "document_count",
            ("count"(*) FILTER (WHERE ("document"."expiry_date" < CURRENT_DATE)))::integer AS "expired_count"
           FROM "public"."employee_documents" "document"
          WHERE (("document"."employee_id" = "migrant"."employee_id") AND ("document"."archived_at" IS NULL))) "document_summary" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(*) FILTER (WHERE ("renewal"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text", 'rejected'::"text"]))))::integer AS "open_renewal_count",
            COALESCE("sum"("renewal"."actual_cost") FILTER (WHERE ("renewal"."status" = 'completed'::"text")), (0)::numeric) AS "completed_renewal_cost"
           FROM "public"."employee_renewal_cases" "renewal"
          WHERE ("renewal"."employee_id" = "migrant"."employee_id")) "renewal_summary" ON (true));


--
-- Name: v_hr_notification_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_notification_queue" WITH ("security_invoker"='true') AS
 SELECT "id",
    "notification_type",
    "employee_id",
    "document_id",
    "renewal_case_id",
    "recipient_profile_id",
    "recipient_employee_id",
    "channel",
    "title",
    "scheduled_at",
    "status",
    "attempt_count",
    "last_error_code",
    "created_at"
   FROM "public"."hr_notifications" "notification";


--
-- Name: v_hr_payroll_cost_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_payroll_cost_summary" WITH ("security_invoker"='true') AS
 SELECT "period"."id" AS "payroll_period_id",
    "period"."period_code",
    "period"."start_date",
    "period"."end_date",
    "term"."department_id",
    "department"."department_name",
    ("count"("summary"."employee_id"))::integer AS "employee_count",
    COALESCE("sum"("summary"."gross_amount"), (0)::numeric) AS "gross_amount",
    COALESCE("sum"("summary"."net_amount"), (0)::numeric) AS "net_amount",
    COALESCE("sum"("summary"."overtime_earning"), (0)::numeric) AS "overtime_amount",
    COALESCE("sum"("summary"."allowance_amount"), (0)::numeric) AS "allowance_amount",
    COALESCE("sum"("summary"."deduction_amount"), (0)::numeric) AS "deduction_amount"
   FROM ((("public"."payroll_periods" "period"
     LEFT JOIN "public"."payroll_employee_summaries" "summary" ON (("summary"."payroll_period_id" = "period"."id")))
     LEFT JOIN "public"."employee_employment_terms" "term" ON ((("term"."employee_id" = "summary"."employee_id") AND ("term"."effective_from" <= "period"."end_date") AND (("term"."effective_to" IS NULL) OR ("term"."effective_to" >= "period"."start_date")))))
     LEFT JOIN "public"."departments" "department" ON (("department"."id" = "term"."department_id")))
  GROUP BY "period"."id", "period"."period_code", "period"."start_date", "period"."end_date", "term"."department_id", "department"."department_name";


--
-- Name: v_hr_people_workspace; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_people_workspace" WITH ("security_invoker"='true') AS
 SELECT "e"."id" AS "employee_id",
    "e"."employee_code",
    "e"."full_name",
    "e"."nickname",
    "e"."nationality",
    "e"."phone",
    "e"."status" AS "employee_status",
    "e"."start_date",
    "e"."end_date",
    "et"."id" AS "employment_term_id",
    "et"."department_id",
    "d"."department_code",
    "d"."department_name",
    "et"."position_id",
    "p"."position_code",
    "p"."position_name",
    "et"."worker_type",
    "et"."payment_type",
    "et"."daily_wage",
    "et"."hourly_wage_rate",
    "et"."monthly_salary",
    "et"."contract_rate",
    "et"."normal_hours_per_day",
    "et"."effective_from",
    "et"."effective_to",
    "team_data"."team_ids",
    "team_data"."team_codes",
    "team_data"."team_names",
    "team_data"."active_team_count",
    "team_data"."primary_supervisor_name",
    "profile_data"."profile_id",
    "profile_data"."profile_status",
    "profile_data"."profile_role",
    ("profile_data"."profile_id" IS NOT NULL) AS "has_system_profile",
    ("et"."department_id" IS NOT NULL) AS "department_ready",
    ("team_data"."active_team_count" <= 1) AS "team_assignment_valid"
   FROM ((((("public"."employees" "e"
     LEFT JOIN "public"."employee_employment_terms" "et" ON ((("et"."employee_id" = "e"."id") AND "et"."is_current")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "et"."department_id")))
     LEFT JOIN "public"."positions" "p" ON (("p"."id" = "et"."position_id")))
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("t"."id" ORDER BY "t"."team_code") AS "team_ids",
            "string_agg"("t"."team_code", ', '::"text" ORDER BY "t"."team_code") AS "team_codes",
            "string_agg"("t"."team_name", ', '::"text" ORDER BY "t"."team_code") AS "team_names",
            ("count"(*))::integer AS "active_team_count",
            "min"("sup"."full_name") AS "primary_supervisor_name"
           FROM (("public"."team_members" "tm"
             JOIN "public"."teams" "t" ON ((("t"."id" = "tm"."team_id") AND ("t"."status" = 'active'::"text"))))
             LEFT JOIN "public"."employees" "sup" ON (("sup"."id" = "t"."supervisor_employee_id")))
          WHERE (("tm"."employee_id" = "e"."id") AND "tm"."is_active" AND (("tm"."start_date" IS NULL) OR ("tm"."start_date" <= CURRENT_DATE)) AND (("tm"."end_date" IS NULL) OR ("tm"."end_date" >= CURRENT_DATE)))) "team_data" ON (true))
     LEFT JOIN LATERAL ( SELECT "pr"."id" AS "profile_id",
            "pr"."status" AS "profile_status",
            "pr"."role" AS "profile_role"
           FROM "public"."profiles" "pr"
          WHERE ("pr"."employee_id" = "e"."id")
          ORDER BY "pr"."created_at"
         LIMIT 1) "profile_data" ON (true));


--
-- Name: v_hr_renewal_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_renewal_pipeline" WITH ("security_invoker"='true') AS
 SELECT "status",
    "priority",
    ("count"(*))::integer AS "case_count",
    ("count"(*) FILTER (WHERE ("target_completion_date" < CURRENT_DATE)))::integer AS "overdue_count",
    COALESCE("sum"("estimated_cost"), (0)::numeric) AS "estimated_cost",
    COALESCE("sum"("actual_cost"), (0)::numeric) AS "actual_cost"
   FROM "public"."employee_renewal_cases" "renewal"
  GROUP BY "status", "priority";


--
-- Name: v_hr_setup_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_setup_queue" WITH ("security_invoker"='true') AS
 SELECT "employee_id",
    "employee_code",
    "full_name",
    "employee_status",
    "department_id",
    "department_name",
    "position_name",
    "worker_type",
    "payment_type",
    "active_team_count",
    "team_names",
    "has_system_profile",
        CASE
            WHEN ("employment_term_id" IS NULL) THEN 'missing_employment_term'::"text"
            WHEN ("department_id" IS NULL) THEN 'missing_department'::"text"
            WHEN ("active_team_count" > 1) THEN 'multiple_active_teams'::"text"
            WHEN (("employee_status" = 'active'::"text") AND (("position_name" = ANY (ARRAY['ผู้อำนวยการ'::"text", 'หัวหน้างาน'::"text", 'ผู้ดูแลระบบ'::"text"])) OR (COALESCE("profile_role", ''::"text") <> ''::"text")) AND (NOT "has_system_profile")) THEN 'missing_system_profile'::"text"
            ELSE 'ready'::"text"
        END AS "setup_status"
   FROM "public"."v_hr_people_workspace";


--
-- Name: v_hr_training_compliance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_hr_training_compliance" WITH ("security_invoker"='true') AS
 SELECT "employee"."id" AS "employee_id",
    "employee"."employee_code",
    "employee"."full_name",
    ("count"(DISTINCT "training"."id") FILTER (WHERE ("training"."result_status" = 'passed'::"text")))::integer AS "passed_course_count",
    ("count"(DISTINCT "certification"."id") FILTER (WHERE ("certification"."status" = 'active'::"text")))::integer AS "active_certification_count",
    ("count"(DISTINCT "certification"."id") FILTER (WHERE ("certification"."expires_on" < CURRENT_DATE)))::integer AS "expired_certification_count",
    ("count"(DISTINCT "certification"."id") FILTER (WHERE (("certification"."expires_on" >= CURRENT_DATE) AND ("certification"."expires_on" <= (CURRENT_DATE + 90)))))::integer AS "due_90_certification_count"
   FROM (("public"."employees" "employee"
     LEFT JOIN "public"."employee_training_records" "training" ON (("training"."employee_id" = "employee"."id")))
     LEFT JOIN "public"."employee_certifications" "certification" ON (("certification"."employee_id" = "employee"."id")))
  WHERE ("employee"."is_current" IS TRUE)
  GROUP BY "employee"."id", "employee"."employee_code", "employee"."full_name";


--
-- Name: warehouses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."warehouses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "warehouse_code" "text" NOT NULL,
    "warehouse_name" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "keeper_employee_id" "uuid",
    "warehouse_type" "text" DEFAULT 'general'::"text" NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "configuration_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: v_inventory_setup_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_inventory_setup_queue" WITH ("security_invoker"='true') AS
 SELECT 'warehouse'::"text" AS "setup_type",
    NULL::"uuid" AS "reference_id",
    'ยังไม่มีคลังสินค้า'::"text" AS "issue"
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "public"."warehouses"
          WHERE ("warehouses"."status" = 'active'::"text"))))
UNION ALL
 SELECT 'default_warehouse'::"text" AS "setup_type",
    "warehouses"."id" AS "reference_id",
    'ยังไม่ได้กำหนดเป็นคลังหลัก'::"text" AS "issue"
   FROM "public"."warehouses"
  WHERE (("warehouses"."status" = 'active'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."warehouses" "warehouses_1"
          WHERE (("warehouses_1"."status" = 'active'::"text") AND "warehouses_1"."is_default")))))
UNION ALL
 SELECT 'stock_balance'::"text" AS "setup_type",
    "m"."id" AS "reference_id",
    'วัสดุยังไม่มียอดคงเหลือในคลัง'::"text" AS "issue"
   FROM "public"."materials" "m"
  WHERE (("m"."status" = 'active'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."stock_balances" "sb"
          WHERE ("sb"."material_id" = "m"."id")))));


--
-- Name: v_inventory_work_order_workspace; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_inventory_work_order_workspace" WITH ("security_invoker"='true') AS
 WITH "material_summary" AS (
         SELECT "m"."work_order_id",
            ("count"(*))::integer AS "material_count",
            "sum"("m"."planned_quantity") AS "planned_quantity",
            "sum"("m"."issued_quantity") AS "issued_quantity",
            "sum"("m"."used_quantity") AS "used_quantity",
            "sum"("m"."returned_quantity") AS "returned_quantity",
            "sum"(GREATEST(("m"."planned_quantity" - "m"."issued_quantity"), (0)::numeric)) AS "outstanding_issue_quantity",
            "sum"(GREATEST((("m"."issued_quantity" - "m"."used_quantity") - "m"."returned_quantity"), (0)::numeric)) AS "outstanding_return_or_use_quantity"
           FROM "public"."work_order_materials" "m"
          GROUP BY "m"."work_order_id"
        ), "issue_summary" AS (
         SELECT "goods_issues"."work_order_id",
            ("count"(*))::integer AS "issue_count",
            "max"("goods_issues"."created_at") AS "latest_issue_at",
            ("array_agg"("goods_issues"."status" ORDER BY "goods_issues"."created_at" DESC))[1] AS "latest_issue_status",
            ("array_agg"("goods_issues"."id" ORDER BY "goods_issues"."created_at" DESC))[1] AS "latest_issue_id"
           FROM "public"."goods_issues"
          GROUP BY "goods_issues"."work_order_id"
        )
 SELECT "wo"."id" AS "work_order_id",
    "wo"."work_order_no",
    "wo"."status" AS "work_order_status",
    "wo"."scheduled_date",
    "b"."block_code",
    "a"."activity_code",
    "a"."activity_name",
    COALESCE("ms"."material_count", 0) AS "material_count",
    COALESCE("ms"."planned_quantity", (0)::numeric) AS "planned_quantity",
    COALESCE("ms"."issued_quantity", (0)::numeric) AS "issued_quantity",
    COALESCE("ms"."used_quantity", (0)::numeric) AS "used_quantity",
    COALESCE("ms"."returned_quantity", (0)::numeric) AS "returned_quantity",
    COALESCE("ms"."outstanding_issue_quantity", (0)::numeric) AS "outstanding_issue_quantity",
    COALESCE("ms"."outstanding_return_or_use_quantity", (0)::numeric) AS "outstanding_return_or_use_quantity",
    COALESCE("ins"."issue_count", 0) AS "issue_count",
    "ins"."latest_issue_id",
    "ins"."latest_issue_status",
    "ins"."latest_issue_at",
        CASE
            WHEN (COALESCE("ms"."material_count", 0) = 0) THEN 'no_material'::"text"
            WHEN ((COALESCE("ms"."outstanding_issue_quantity", (0)::numeric) > (0)::numeric) AND ("ins"."latest_issue_status" IS NULL)) THEN 'prepare_issue'::"text"
            WHEN ("ins"."latest_issue_status" = 'draft'::"text") THEN 'submit_issue'::"text"
            WHEN ("ins"."latest_issue_status" = 'pending_approval'::"text") THEN 'approve_issue'::"text"
            WHEN ("ins"."latest_issue_status" = 'approved'::"text") THEN 'post_issue'::"text"
            WHEN (COALESCE("ms"."outstanding_return_or_use_quantity", (0)::numeric) > (0)::numeric) THEN 'record_use_or_return'::"text"
            ELSE 'complete'::"text"
        END AS "next_action"
   FROM (((("public"."work_orders" "wo"
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "wo"."block_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "material_summary" "ms" ON (("ms"."work_order_id" = "wo"."id")))
     LEFT JOIN "issue_summary" "ins" ON (("ins"."work_order_id" = "wo"."id")));


--
-- Name: v_payroll_period_workspace; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_payroll_period_workspace" WITH ("security_invoker"='true') AS
 WITH "summary_totals" AS (
         SELECT "payroll_employee_summaries"."payroll_period_id",
            ("count"(*))::integer AS "employee_count",
            "sum"("payroll_employee_summaries"."gross_amount") AS "gross_amount",
            "sum"("payroll_employee_summaries"."allowance_amount") AS "allowance_amount",
            "sum"("payroll_employee_summaries"."deduction_amount") AS "deduction_amount",
            "sum"("payroll_employee_summaries"."net_amount") AS "net_amount"
           FROM "public"."payroll_employee_summaries"
          GROUP BY "payroll_employee_summaries"."payroll_period_id"
        ), "earning_counts" AS (
         SELECT "s"."payroll_period_id",
            ("count"("e"."id"))::integer AS "earning_line_count"
           FROM ("public"."payroll_employee_summaries" "s"
             LEFT JOIN "public"."payroll_earning_lines" "e" ON (("e"."payroll_summary_id" = "s"."id")))
          GROUP BY "s"."payroll_period_id"
        )
 SELECT "p"."id" AS "payroll_period_id",
    "p"."period_code",
    "p"."period_name",
    "p"."start_date",
    "p"."end_date",
    "p"."status",
    COALESCE("st"."employee_count", 0) AS "employee_count",
    COALESCE("ec"."earning_line_count", 0) AS "earning_line_count",
    COALESCE("st"."gross_amount", (0)::numeric) AS "gross_amount",
    COALESCE("st"."allowance_amount", (0)::numeric) AS "allowance_amount",
    COALESCE("st"."deduction_amount", (0)::numeric) AS "deduction_amount",
    COALESCE("st"."net_amount", (0)::numeric) AS "net_amount",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."work_result_workers" "wrw"
             JOIN "public"."work_results" "wr" ON (("wr"."id" = "wrw"."work_result_id")))
          WHERE ((("wrw"."work_date" >= "p"."start_date") AND ("wrw"."work_date" <= "p"."end_date")) AND ("wr"."result_status" = ANY (ARRAY['verified'::"text", 'closed'::"text"])))) AS "eligible_worker_lines",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."work_result_workers" "wrw"
             JOIN "public"."work_results" "wr" ON (("wr"."id" = "wrw"."work_result_id")))
          WHERE ((("wrw"."work_date" >= "p"."start_date") AND ("wrw"."work_date" <= "p"."end_date")) AND ("wr"."result_status" <> ALL (ARRAY['verified'::"text", 'closed'::"text"])))) AS "unverified_worker_lines",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."work_result_workers" "wrw"
             JOIN "public"."work_results" "wr" ON (("wr"."id" = "wrw"."work_result_id")))
          WHERE ((("wrw"."work_date" >= "p"."start_date") AND ("wrw"."work_date" <= "p"."end_date")) AND ("wr"."result_status" = ANY (ARRAY['verified'::"text", 'closed'::"text"])) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."payroll_earning_lines" "pe"
                  WHERE ("pe"."work_result_worker_id" = "wrw"."id")))))) AS "unprepared_worker_lines",
        CASE
            WHEN ("p"."status" = 'open'::"text") THEN 'calculate'::"text"
            WHEN ("p"."status" = 'calculated'::"text") THEN 'review'::"text"
            WHEN ("p"."status" = 'reviewing'::"text") THEN 'approve'::"text"
            WHEN ("p"."status" = 'approved'::"text") THEN 'close'::"text"
            WHEN ("p"."status" = 'closed'::"text") THEN 'view_closed'::"text"
            ELSE 'view'::"text"
        END AS "next_action",
    "p"."prepared_at",
    "p"."calculated_at",
    "p"."approved_at",
    "p"."closed_at",
    "p"."calculation_version"
   FROM (("public"."payroll_periods" "p"
     LEFT JOIN "summary_totals" "st" ON (("st"."payroll_period_id" = "p"."id")))
     LEFT JOIN "earning_counts" "ec" ON (("ec"."payroll_period_id" = "p"."id")));


--
-- Name: v_vehicle_fuel_setup_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_vehicle_fuel_setup_queue" WITH ("security_invoker"='true') AS
 SELECT "v"."id" AS "vehicle_id",
    "v"."vehicle_code",
    "v"."vehicle_name",
    "v"."vehicle_type",
    "v"."plate_no",
    "v"."fuel_type",
    "v"."tank_capacity_liter",
    "v"."minimum_fuel_liter",
    "v"."reorder_point_liter",
    "v"."safety_stock_liter",
    "v"."target_fill_percent",
    "v"."fuel_measurement_basis",
    "v"."requires_hour_meter",
    "v"."requires_odometer",
        CASE
            WHEN (COALESCE("v"."fuel_type", ''::"text") = ''::"text") THEN 'missing_fuel_type'::"text"
            WHEN (COALESCE("v"."tank_capacity_liter", (0)::numeric) <= (0)::numeric) THEN 'missing_tank_capacity'::"text"
            WHEN (COALESCE("v"."reorder_point_liter", (0)::numeric) <= (0)::numeric) THEN 'missing_reorder_point'::"text"
            WHEN (COALESCE("v"."safety_stock_liter", (0)::numeric) <= (0)::numeric) THEN 'missing_safety_stock'::"text"
            WHEN (("v"."fuel_measurement_basis" = 'engine_hours'::"text") AND (NOT "v"."requires_hour_meter")) THEN 'hour_meter_not_required'::"text"
            WHEN (("v"."fuel_measurement_basis" = 'distance_km'::"text") AND (NOT "v"."requires_odometer")) THEN 'odometer_not_required'::"text"
            ELSE 'ready'::"text"
        END AS "setup_status",
    "b"."current_estimated_liter",
    "b"."last_measurement_at"
   FROM ("public"."vehicles" "v"
     LEFT JOIN "public"."vehicle_fuel_balances" "b" ON (("b"."vehicle_id" = "v"."id")))
  WHERE ("v"."status" = 'active'::"text");


--
-- Name: v_management_action_center; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_management_action_center" WITH ("security_invoker"='true') AS
 SELECT 'farm.master'::"text" AS "module_key",
    'incomplete_block_master'::"text" AS "action_key",
    0 AS "priority",
    "count"(*) AS "item_count",
    'บล็อกรอกรอกปีปลูก พื้นที่ หรือจำนวนต้นให้ครบ'::"text" AS "action_label",
    '/farm/master'::"text" AS "route"
   FROM "public"."blocks"
  WHERE (("blocks"."planting_year" IS NULL) OR ("blocks"."area_rai" <= (0)::numeric) OR ("blocks"."tree_count" <= 0))
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'farm.work'::"text" AS "module_key",
    "v_farm_workflow_workspace"."next_action" AS "action_key",
        CASE "v_farm_workflow_workspace"."next_action"
            WHEN 'complete_order'::"text" THEN 1
            WHEN 'assign_resource'::"text" THEN 2
            WHEN 'confirm_workers'::"text" THEN 3
            WHEN 'prepare_material_issue'::"text" THEN 4
            ELSE 5
        END AS "priority",
    "count"(*) AS "item_count",
        CASE "v_farm_workflow_workspace"."next_action"
            WHEN 'complete_order'::"text" THEN 'ใบงานรอกรอกข้อมูลให้ครบ'::"text"
            WHEN 'assign_resource'::"text" THEN 'ใบงานรอเลือกทีมหรือผู้รับเหมา'::"text"
            WHEN 'confirm_workers'::"text" THEN 'ใบงานรอยืนยันคนทำงาน'::"text"
            WHEN 'prepare_material_issue'::"text" THEN 'ใบงานรอเตรียมจ่ายพัสดุ'::"text"
            WHEN 'record_result'::"text" THEN 'ใบงานพร้อมบันทึกผลงาน'::"text"
            WHEN 'continue_result'::"text" THEN 'ผลงานรอบันทึกต่อ'::"text"
            WHEN 'verify_result'::"text" THEN 'ผลงานรอตรวจสอบ'::"text"
            WHEN 'close_result'::"text" THEN 'ผลงานรอปิดงาน'::"text"
            ELSE "v_farm_workflow_workspace"."next_action"
        END AS "action_label",
    '/farm/work'::"text" AS "route"
   FROM "public"."v_farm_workflow_workspace"
  WHERE ("v_farm_workflow_workspace"."next_action" <> ALL (ARRAY['view'::"text", 'view_closed'::"text"]))
  GROUP BY "v_farm_workflow_workspace"."next_action"
UNION ALL
 SELECT 'farm.daily'::"text" AS "module_key",
    "work_results"."result_status" AS "action_key",
    6 AS "priority",
    "count"(*) AS "item_count",
        CASE "work_results"."result_status"
            WHEN 'draft'::"text" THEN 'บันทึกผลงานรอกรอกหรือส่งตรวจ'::"text"
            ELSE 'ผลงานรอตรวจสอบ'::"text"
        END AS "action_label",
    '/farm/daily'::"text" AS "route"
   FROM "public"."work_results"
  WHERE ("work_results"."result_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))
  GROUP BY "work_results"."result_status"
UNION ALL
 SELECT 'hr.people'::"text" AS "module_key",
    'missing_department'::"text" AS "action_key",
    10 AS "priority",
    "count"(*) AS "item_count",
    'พนักงานรอกำหนดฝ่าย'::"text" AS "action_label",
    '/hr/people'::"text" AS "route"
   FROM "public"."v_hr_people_workspace"
  WHERE ("v_hr_people_workspace"."department_id" IS NULL)
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'hr.people'::"text" AS "module_key",
    'multiple_active_teams'::"text" AS "action_key",
    11 AS "priority",
    "count"(*) AS "item_count",
    'พนักงานอยู่หลายทีมพร้อมกัน'::"text" AS "action_label",
    '/hr/people'::"text" AS "route"
   FROM "public"."v_hr_people_workspace"
  WHERE ("v_hr_people_workspace"."active_team_count" > 1)
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'hr.people'::"text" AS "module_key",
    'missing_system_profile'::"text" AS "action_key",
    12 AS "priority",
    "count"(*) AS "item_count",
    'ผู้รับผิดชอบงานยังไม่มีบัญชีระบบ'::"text" AS "action_label",
    '/system/access'::"text" AS "route"
   FROM "public"."v_hr_people_workspace"
  WHERE (("v_hr_people_workspace"."employee_status" = 'active'::"text") AND ("v_hr_people_workspace"."position_name" = ANY (ARRAY['ผู้อำนวยการ'::"text", 'หัวหน้างาน'::"text", 'ผู้ดูแลระบบ'::"text"])) AND (NOT "v_hr_people_workspace"."has_system_profile"))
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'inventory.stock'::"text" AS "module_key",
    "v_inventory_setup_queue"."setup_type" AS "action_key",
    20 AS "priority",
    "count"(*) AS "item_count",
    "max"("v_inventory_setup_queue"."issue") AS "action_label",
    '/inventory'::"text" AS "route"
   FROM "public"."v_inventory_setup_queue"
  GROUP BY "v_inventory_setup_queue"."setup_type"
UNION ALL
 SELECT 'inventory.fuel'::"text" AS "module_key",
    'fuel_configuration'::"text" AS "action_key",
    30 AS "priority",
    (( SELECT "count"(*) AS "count"
           FROM "public"."v_vehicle_fuel_setup_queue") +
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "public"."fuel_tanks"
              WHERE ("fuel_tanks"."status" = 'active'::"text")))) THEN 1
            ELSE 0
        END) AS "item_count",
    'รถหรือถังน้ำมันยังตั้งค่าไม่ครบ'::"text" AS "action_label",
    '/inventory/fuel'::"text" AS "route"
  WHERE (COALESCE(( SELECT "system_settings"."setting_value"
           FROM "public"."system_settings"
          WHERE ("system_settings"."setting_key" = 'fuel.configuration_confirmed'::"text")), 'false'::"text") <> 'true'::"text")
UNION ALL
 SELECT 'inventory.fuel'::"text" AS "module_key",
    "v_fuel_control_exceptions"."exception_type" AS "action_key",
    31 AS "priority",
    "count"(*) AS "item_count",
    "max"("v_fuel_control_exceptions"."description") AS "action_label",
    '/inventory/fuel'::"text" AS "route"
   FROM "public"."v_fuel_control_exceptions"
  GROUP BY "v_fuel_control_exceptions"."exception_type"
UNION ALL
 SELECT 'payroll'::"text" AS "module_key",
    'unverified_results'::"text" AS "action_key",
    40 AS "priority",
    ("sum"("v_payroll_period_workspace"."unverified_worker_lines"))::bigint AS "item_count",
    'ผลงานในงวดค่าแรงยังไม่ผ่านการตรวจสอบ'::"text" AS "action_label",
    '/payroll'::"text" AS "route"
   FROM "public"."v_payroll_period_workspace"
  WHERE (("v_payroll_period_workspace"."status" <> 'closed'::"text") AND ("v_payroll_period_workspace"."unverified_worker_lines" > 0))
 HAVING ("sum"("v_payroll_period_workspace"."unverified_worker_lines") > (0)::numeric)
UNION ALL
 SELECT 'performance'::"text" AS "module_key",
    'standards_not_ready'::"text" AS "action_key",
    50 AS "priority",
    "count"(*) AS "item_count",
    'กิจกรรมยังไม่ได้กำหนดหรืออนุมัติมาตรฐานประสิทธิภาพ'::"text" AS "action_label",
    '/farm/performance'::"text" AS "route"
   FROM "public"."v_activity_performance_standard_setup"
  WHERE ("v_activity_performance_standard_setup"."setup_status" <> 'ready'::"text")
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'system.access'::"text" AS "module_key",
    'profiles_not_configured'::"text" AS "action_key",
    60 AS "priority",
    (1)::bigint AS "item_count",
    'ยังไม่มีบัญชีผู้ใช้ที่เชื่อมกับพนักงาน'::"text" AS "action_label",
    '/system/access'::"text" AS "route"
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "public"."profiles")));


--
-- Name: v_material_unit_conversion_options; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_material_unit_conversion_options" WITH ("security_invoker"='true') AS
 SELECT "sc"."material_id",
    "m"."material_code",
    "m"."material_name",
    "sc"."from_unit_id",
    "fu"."unit_code" AS "from_unit_code",
    "fu"."unit_name" AS "from_unit_name",
    "sc"."to_unit_id",
    "tu"."unit_code" AS "to_unit_code",
    "tu"."unit_name" AS "to_unit_name",
    "sc"."conversion_rate",
    "sc"."status",
    'material'::"text" AS "conversion_scope"
   FROM ((("public"."sku_conversions" "sc"
     JOIN "public"."materials" "m" ON (("m"."id" = "sc"."material_id")))
     JOIN "public"."units" "fu" ON (("fu"."id" = "sc"."from_unit_id")))
     JOIN "public"."units" "tu" ON (("tu"."id" = "sc"."to_unit_id")))
  WHERE ("sc"."status" = 'active'::"text")
UNION ALL
 SELECT NULL::"uuid" AS "material_id",
    NULL::"text" AS "material_code",
    NULL::"text" AS "material_name",
    "uc"."from_unit_id",
    "fu"."unit_code" AS "from_unit_code",
    "fu"."unit_name" AS "from_unit_name",
    "uc"."to_unit_id",
    "tu"."unit_code" AS "to_unit_code",
    "tu"."unit_name" AS "to_unit_name",
    "uc"."conversion_rate",
    "uc"."status",
    'global'::"text" AS "conversion_scope"
   FROM (("public"."unit_conversions" "uc"
     JOIN "public"."units" "fu" ON (("fu"."id" = "uc"."from_unit_id")))
     JOIN "public"."units" "tu" ON (("tu"."id" = "uc"."to_unit_id")))
  WHERE ("uc"."status" = 'active'::"text");


--
-- Name: v_menu_consolidation_audit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_menu_consolidation_audit" WITH ("security_invoker"='true') AS
 SELECT "workspace_key",
    "count"(*) AS "tab_count",
    "count"(*) FILTER (WHERE ("is_primary" AND (NOT "is_hidden"))) AS "visible_entry_count",
    "count"(*) FILTER (WHERE "is_hidden") AS "hidden_tab_count",
    "array_agg"("menu_key" ORDER BY "sort_order", "menu_key") AS "menu_keys",
    "array_agg"("workspace_tab" ORDER BY "sort_order", "menu_key") AS "tabs"
   FROM "public"."menu_items"
  WHERE (("status" = 'active'::"text") AND ("workspace_key" IS NOT NULL))
  GROUP BY "workspace_key";


--
-- Name: v_profile_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_profile_permissions" WITH ("security_invoker"='true') AS
 SELECT DISTINCT "pr"."profile_id",
    "r"."role_key",
    "r"."role_name",
    "p"."permission_key",
    "p"."permission_name",
    "p"."module_key",
    "p"."action_key"
   FROM ((("public"."profile_roles" "pr"
     JOIN "public"."roles" "r" ON ((("r"."id" = "pr"."role_id") AND ("r"."status" = 'active'::"text"))))
     JOIN "public"."role_permissions" "rp" ON ((("rp"."role_id" = "r"."id") AND "rp"."is_allowed" AND ("rp"."status" = 'active'::"text"))))
     JOIN "public"."permissions" "p" ON ((("p"."id" = "rp"."permission_id") AND ("p"."status" = 'active'::"text"))))
  WHERE ("pr"."is_active" AND ("pr"."effective_from" <= CURRENT_DATE) AND (("pr"."effective_to" IS NULL) OR ("pr"."effective_to" >= CURRENT_DATE)));


--
-- Name: v_profile_menu; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_profile_menu" WITH ("security_invoker"='true') AS
 SELECT DISTINCT "pp"."profile_id",
    "m"."id",
    "m"."parent_id",
    "m"."menu_key",
    "m"."module_key",
    "m"."label_th",
    "m"."label_mm",
    "m"."route",
    "m"."icon",
    "m"."sort_order",
    "m"."required_permission_key"
   FROM ("public"."menu_items" "m"
     JOIN "public"."v_profile_permissions" "pp" ON (("pp"."permission_key" = "m"."required_permission_key")))
  WHERE ("m"."status" = 'active'::"text");


--
-- Name: v_survey_action_center; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_survey_action_center" WITH ("security_invoker"='true') AS
 SELECT 'survey.pending_response'::"text" AS "action_key",
    'แบบประเมินรอกรอกหรือส่งตรวจ'::"text" AS "action_label",
    ("count"(*))::integer AS "item_count",
    1 AS "priority",
    '/farm/daily?tab=survey'::"text" AS "route"
   FROM "public"."survey_responses"
  WHERE ("survey_responses"."status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'survey.open_finding'::"text" AS "action_key",
    'ข้อพบจากแบบประเมินรอแก้ไข'::"text" AS "action_label",
    ("count"(*))::integer AS "item_count",
    2 AS "priority",
    '/farm/daily?tab=survey-findings'::"text" AS "route"
   FROM "public"."survey_findings"
  WHERE ("survey_findings"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"]))
 HAVING ("count"(*) > 0)
UNION ALL
 SELECT 'survey.overdue_finding'::"text" AS "action_key",
    'ข้อพบจากแบบประเมินเกินกำหนด'::"text" AS "action_label",
    ("count"(*))::integer AS "item_count",
    0 AS "priority",
    '/farm/daily?tab=survey-findings'::"text" AS "route"
   FROM "public"."survey_findings"
  WHERE (("survey_findings"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("survey_findings"."due_date" < CURRENT_DATE))
 HAVING ("count"(*) > 0);


--
-- Name: v_survey_finding_followup; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_survey_finding_followup" WITH ("security_invoker"='true') AS
 SELECT "f"."id",
    "f"."finding_no",
    "f"."severity",
    "f"."finding_type",
    "f"."description",
    "f"."corrective_action",
    "f"."due_date",
    "f"."status",
    "f"."resolved_note",
    "f"."created_at",
    "f"."updated_at",
    "r"."response_no",
    "r"."response_date",
    "r"."score_pct",
    "r"."pass_status",
    "t"."template_code",
    "t"."template_name",
    "q"."question_code",
    "q"."question_text",
    "wo"."work_order_no",
    "a"."activity_code",
    "a"."activity_name",
    "b"."block_code",
    "b"."block_name",
    "e"."employee_code" AS "owner_employee_code",
    "e"."full_name" AS "owner_employee_name",
        CASE
            WHEN (("f"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("f"."due_date" < CURRENT_DATE)) THEN true
            ELSE false
        END AS "is_overdue"
   FROM (((((((("public"."survey_findings" "f"
     JOIN "public"."survey_responses" "r" ON (("r"."id" = "f"."response_id")))
     JOIN "public"."survey_templates" "t" ON (("t"."id" = "r"."template_id")))
     LEFT JOIN "public"."survey_answers" "sa" ON (("sa"."id" = "f"."answer_id")))
     LEFT JOIN "public"."survey_questions" "q" ON (("q"."id" = "sa"."question_id")))
     LEFT JOIN "public"."work_orders" "wo" ON (("wo"."id" = "r"."work_order_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = COALESCE("r"."block_id", "wo"."block_id"))))
     LEFT JOIN "public"."employees" "e" ON (("e"."id" = "f"."owner_employee_id")));


--
-- Name: v_survey_question_analysis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_survey_question_analysis" WITH ("security_invoker"='true') AS
 SELECT "t"."template_base_code",
    "t"."template_name",
    "t"."survey_category",
    "q"."id" AS "question_id",
    "q"."question_code",
    "q"."analysis_key",
    "q"."section_name",
    "q"."question_text",
    "q"."answer_type",
    ("date_trunc"('month'::"text", ("r"."response_date")::timestamp with time zone))::"date" AS "response_month",
    "wo"."activity_id",
    "a"."activity_code",
    "a"."activity_name",
    COALESCE("r"."block_id", "wo"."block_id") AS "block_id",
    "b"."block_code",
    COALESCE("r"."team_id", "wo"."team_id") AS "team_id",
    "tm"."team_code",
    "count"(DISTINCT "r"."id") AS "response_count",
    "count"("sa"."id") AS "answer_count",
    "round"("avg"("sa"."answer_number"), 2) AS "average_numeric_answer",
    "round"("avg"(
        CASE
            WHEN ("sa"."is_compliant" IS TRUE) THEN 100
            WHEN ("sa"."is_compliant" IS FALSE) THEN 0
            ELSE NULL::integer
        END), 2) AS "compliance_pct",
    "round"("avg"(
        CASE
            WHEN ("sa"."max_score_snapshot" > (0)::numeric) THEN (("sa"."score_awarded" / "sa"."max_score_snapshot") * (100)::numeric)
            ELSE NULL::numeric
        END), 2) AS "average_question_score_pct",
    "count"(*) FILTER (WHERE ("sa"."is_compliant" = false)) AS "non_compliance_count"
   FROM ((((((("public"."survey_templates" "t"
     JOIN "public"."survey_questions" "q" ON (("q"."template_id" = "t"."id")))
     JOIN "public"."survey_responses" "r" ON ((("r"."template_id" = "t"."id") AND ("r"."status" = ANY (ARRAY['submitted'::"text", 'verified'::"text", 'closed'::"text"])))))
     LEFT JOIN "public"."survey_answers" "sa" ON ((("sa"."response_id" = "r"."id") AND ("sa"."question_id" = "q"."id"))))
     LEFT JOIN "public"."work_orders" "wo" ON (("wo"."id" = "r"."work_order_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = COALESCE("r"."block_id", "wo"."block_id"))))
     LEFT JOIN "public"."teams" "tm" ON (("tm"."id" = COALESCE("r"."team_id", "wo"."team_id"))))
  WHERE ("q"."status" = 'active'::"text")
  GROUP BY "t"."template_base_code", "t"."template_name", "t"."survey_category", "q"."id", "q"."question_code", "q"."analysis_key", "q"."section_name", "q"."question_text", "q"."answer_type", (("date_trunc"('month'::"text", ("r"."response_date")::timestamp with time zone))::"date"), "wo"."activity_id", "a"."activity_code", "a"."activity_name", COALESCE("r"."block_id", "wo"."block_id"), "b"."block_code", COALESCE("r"."team_id", "wo"."team_id"), "tm"."team_code";


--
-- Name: v_survey_response_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_survey_response_summary" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."response_no",
    "r"."response_date",
    "r"."status",
    "r"."score_total",
    "r"."score_max",
    "r"."score_pct",
    "r"."pass_status",
    "r"."data_quality_pct",
    "r"."survey_scope",
    "r"."entity_table",
    "r"."entity_id",
    "t"."template_code",
    "t"."template_base_code",
    "t"."version_no" AS "template_version",
    "t"."template_name",
    "t"."survey_category",
    "t"."minimum_pass_pct",
    "r"."work_order_id",
    "wo"."work_order_no",
    "wo"."activity_id",
    "a"."activity_code",
    "a"."activity_name",
    "r"."work_result_id",
    "wr"."result_no",
    "wr"."result_status",
    COALESCE("r"."block_id", "wo"."block_id") AS "block_id",
    "b"."block_code",
    "b"."block_name",
    COALESCE("r"."team_id", "wo"."team_id") AS "team_id",
    "tm"."team_code",
    "tm"."team_name",
    "r"."employee_id",
    "e"."employee_code",
    "e"."full_name" AS "employee_name",
    "r"."vehicle_id",
    "v"."vehicle_code",
    "v"."vehicle_name",
    "r"."respondent_employee_id",
    "re"."full_name" AS "respondent_name",
    "r"."evaluator_employee_id",
    "ee"."full_name" AS "evaluator_name",
    ( SELECT "count"(*) AS "count"
           FROM "public"."survey_answers" "x"
          WHERE ("x"."response_id" = "r"."id")) AS "answer_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."survey_response_attachments" "x"
          WHERE ("x"."response_id" = "r"."id")) AS "attachment_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."survey_findings" "x"
          WHERE (("x"."response_id" = "r"."id") AND ("x"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])))) AS "open_finding_count",
    "r"."submitted_at",
    "r"."verified_at",
    "r"."closed_at",
    "r"."updated_at"
   FROM (((((((((("public"."survey_responses" "r"
     JOIN "public"."survey_templates" "t" ON (("t"."id" = "r"."template_id")))
     LEFT JOIN "public"."work_orders" "wo" ON (("wo"."id" = "r"."work_order_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."work_results" "wr" ON (("wr"."id" = "r"."work_result_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = COALESCE("r"."block_id", "wo"."block_id"))))
     LEFT JOIN "public"."teams" "tm" ON (("tm"."id" = COALESCE("r"."team_id", "wo"."team_id"))))
     LEFT JOIN "public"."employees" "e" ON (("e"."id" = "r"."employee_id")))
     LEFT JOIN "public"."vehicles" "v" ON (("v"."id" = "r"."vehicle_id")))
     LEFT JOIN "public"."employees" "re" ON (("re"."id" = "r"."respondent_employee_id")))
     LEFT JOIN "public"."employees" "ee" ON (("ee"."id" = "r"."evaluator_employee_id")));


--
-- Name: v_survey_template_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_survey_template_readiness" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"text" AS "template_code",
    NULL::"text" AS "template_base_code",
    NULL::integer AS "version_no",
    NULL::"text" AS "template_name",
    NULL::"text" AS "survey_scope",
    NULL::"text" AS "survey_category",
    NULL::"text" AS "status",
    NULL::numeric AS "minimum_pass_pct",
    NULL::boolean AS "allow_attachments",
    NULL::"date" AS "effective_from",
    NULL::"date" AS "effective_to",
    NULL::bigint AS "question_count",
    NULL::bigint AS "required_question_count",
    NULL::bigint AS "scored_question_count",
    NULL::numeric AS "total_weight_pct",
    NULL::bigint AS "assignment_count",
    NULL::"text" AS "readiness_status";


--
-- Name: v_system_module_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_system_module_readiness" WITH ("security_invoker"='true') AS
 SELECT 'dashboard'::"text" AS "module_key",
    'ภาพรวมและงานค้าง'::"text" AS "module_name",
    'ready'::"text" AS "readiness_status",
    (( SELECT COALESCE("sum"("v_management_action_center"."item_count"), (0)::numeric) AS "coalesce"
           FROM "public"."v_management_action_center"))::bigint AS "item_count",
    (0)::bigint AS "issue_count",
    'view_action_center'::"text" AS "next_action",
    '/farm/dashboard'::"text" AS "route"
UNION ALL
 SELECT 'farm.master'::"text" AS "module_key",
    'ข้อมูลพื้นที่และกิจกรรม'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'warning'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."blocks") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'complete_block_master'::"text"
        END AS "next_action",
    '/farm/master'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."blocks"
          WHERE (("blocks"."planting_year" IS NULL) OR ("blocks"."area_rai" <= (0)::numeric) OR ("blocks"."tree_count" <= 0))) "x"
UNION ALL
 SELECT 'farm.work'::"text" AS "module_key",
    'วางแผนและใบงาน'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'action_required'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."work_orders") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'assign_resources'::"text"
        END AS "next_action",
    '/farm/work'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_farm_workflow_workspace"
          WHERE ("v_farm_workflow_workspace"."next_action" = ANY (ARRAY['complete_order'::"text", 'assign_resource'::"text", 'confirm_workers'::"text"]))) "x"
UNION ALL
 SELECT 'farm.daily'::"text" AS "module_key",
    'บันทึกงานประจำวัน'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'action_required'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."work_results") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'record_result'::"text"
            ELSE 'continue_or_verify_results'::"text"
        END AS "next_action",
    '/farm/daily'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."work_results"
          WHERE ("work_results"."result_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))) "x"
UNION ALL
 SELECT 'farm.performance'::"text" AS "module_key",
    'มาตรฐานประสิทธิภาพกิจกรรม'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'not_configured'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."activities") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'set_activity_standards'::"text"
        END AS "next_action",
    '/farm/performance'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_activity_performance_standard_setup"
          WHERE ("v_activity_performance_standard_setup"."setup_status" <> 'ready'::"text")) "x"
UNION ALL
 SELECT 'hr.people'::"text" AS "module_key",
    'บุคลากรและโครงสร้าง'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'warning'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."employees") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'complete_hr_setup'::"text"
        END AS "next_action",
    '/hr/people'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_hr_setup_queue"
          WHERE ("v_hr_setup_queue"."setup_status" <> 'ready'::"text")) "x"
UNION ALL
 SELECT 'hr.time'::"text" AS "module_key",
    'เวลา ลา และ OT'::"text" AS "module_name",
    'ready'::"text" AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."work_attendance") AS "item_count",
    (0)::bigint AS "issue_count",
    'record_or_review_attendance'::"text" AS "next_action",
    '/hr/time'::"text" AS "route"
UNION ALL
 SELECT 'hr.performance'::"text" AS "module_key",
    'ประสิทธิภาพและทักษะ'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'not_configured'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."work_performance_metrics") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'approve_performance_standards'::"text"
        END AS "next_action",
    '/hr/performance'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_activity_performance_standard_setup"
          WHERE ("v_activity_performance_standard_setup"."setup_status" <> 'ready'::"text")) "x"
UNION ALL
 SELECT 'inventory.stock'::"text" AS "module_key",
    'พัสดุและสต๊อก'::"text" AS "module_name",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."warehouses"
              WHERE ("warehouses"."status" = 'active'::"text")) = 0) THEN 'not_configured'::"text"
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'warning'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."materials") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."warehouses"
              WHERE ("warehouses"."status" = 'active'::"text")) = 0) THEN 'configure_warehouse'::"text"
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'setup_stock'::"text"
        END AS "next_action",
    '/inventory'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_inventory_setup_queue") "x"
UNION ALL
 SELECT 'inventory.fuel'::"text" AS "module_key",
    'รถและน้ำมัน'::"text" AS "module_name",
        CASE
            WHEN (( SELECT "system_settings"."setting_value"
               FROM "public"."system_settings"
              WHERE ("system_settings"."setting_key" = 'fuel.configuration_confirmed'::"text")) = 'true'::"text") THEN
            CASE
                WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
                ELSE 'warning'::"text"
            END
            ELSE 'not_configured'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."vehicles") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN (( SELECT "system_settings"."setting_value"
               FROM "public"."system_settings"
              WHERE ("system_settings"."setting_key" = 'fuel.configuration_confirmed'::"text")) = 'true'::"text") THEN 'view'::"text"
            ELSE 'configure_vehicle_fuel'::"text"
        END AS "next_action",
    '/inventory/fuel'::"text" AS "route"
   FROM ( SELECT (( SELECT "count"(*) AS "count"
                   FROM "public"."v_vehicle_fuel_setup_queue") +
                CASE
                    WHEN (NOT (EXISTS ( SELECT 1
                       FROM "public"."fuel_tanks"
                      WHERE ("fuel_tanks"."status" = 'active'::"text")))) THEN 1
                    ELSE 0
                END) AS "issue_count") "x"
UNION ALL
 SELECT 'payroll'::"text" AS "module_key",
    'รอบและคำนวณค่าแรง'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'action_required'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."payroll_periods") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'verify_work_results'::"text"
        END AS "next_action",
    '/payroll'::"text" AS "route"
   FROM ( SELECT (COALESCE("sum"("v_payroll_period_workspace"."unverified_worker_lines"), (0)::numeric))::bigint AS "issue_count"
           FROM "public"."v_payroll_period_workspace"
          WHERE ("v_payroll_period_workspace"."status" <> 'closed'::"text")) "x"
UNION ALL
 SELECT 'budget'::"text" AS "module_key",
    'ตั้งค่าอัตรางบประมาณ'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'warning'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."budget_activity_rates") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'review_budget_rules'::"text"
        END AS "next_action",
    '/budget'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_budget_year_rule_readiness"
          WHERE (NOT "v_budget_year_rule_readiness"."rules_ready")) "x"
UNION ALL
 SELECT 'budget.analysis'::"text" AS "module_key",
    'วิเคราะห์อัตราและประสิทธิภาพ'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'not_configured'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."activity_budget_rate_recommendations") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'collect_verified_performance'::"text"
        END AS "next_action",
    '/budget/performance'::"text" AS "route"
   FROM ( SELECT "count"(*) AS "issue_count"
           FROM "public"."v_activity_performance_standard_setup"
          WHERE ("v_activity_performance_standard_setup"."setup_status" <> 'ready'::"text")) "x"
UNION ALL
 SELECT 'reports'::"text" AS "module_key",
    'รายงาน'::"text" AS "module_name",
    'ready'::"text" AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."work_orders") AS "item_count",
    (0)::bigint AS "issue_count",
    'view_reports'::"text" AS "next_action",
    '/reports'::"text" AS "route"
UNION ALL
 SELECT 'system.access'::"text" AS "module_key",
    'ผู้ใช้งานและสิทธิ์'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'not_configured'::"text"
        END AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."profiles") AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'create_profiles_and_roles'::"text"
        END AS "next_action",
    '/system/access'::"text" AS "route"
   FROM ( SELECT
                CASE
                    WHEN (( SELECT "count"(*) AS "count"
                       FROM "public"."profiles") = 0) THEN (1)::bigint
                    ELSE (0)::bigint
                END AS "issue_count") "x"
UNION ALL
 SELECT 'system.integrations'::"text" AS "module_key",
    'การเชื่อมต่อระบบ'::"text" AS "module_name",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'ready'::"text"
            ELSE 'not_configured'::"text"
        END AS "readiness_status",
    (2)::bigint AS "item_count",
    "x"."issue_count",
        CASE
            WHEN ("x"."issue_count" = 0) THEN 'view'::"text"
            ELSE 'configure_integrations'::"text"
        END AS "next_action",
    '/system/integrations'::"text" AS "route"
   FROM ( SELECT ((
                CASE
                    WHEN (COALESCE(( SELECT "system_settings"."setting_value"
                       FROM "public"."system_settings"
                      WHERE ("system_settings"."setting_key" = 'integration.weighbridge_enabled'::"text")), 'false'::"text") <> 'true'::"text") THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN (COALESCE(( SELECT "system_settings"."setting_value"
                       FROM "public"."system_settings"
                      WHERE ("system_settings"."setting_key" = 'fuel.configuration_confirmed'::"text")), 'false'::"text") <> 'true'::"text") THEN 1
                    ELSE 0
                END))::bigint AS "issue_count") "x"
UNION ALL
 SELECT 'system.audit'::"text" AS "module_key",
    'Audit Log'::"text" AS "module_name",
    'ready'::"text" AS "readiness_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_logs") AS "item_count",
    (0)::bigint AS "issue_count",
    'view_audit'::"text" AS "next_action",
    '/system/audit'::"text" AS "route";


--
-- Name: v_team_activity_performance_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_team_activity_performance_summary" WITH ("security_invoker"='true') AS
 SELECT "m"."team_id",
    "t"."team_code",
    "t"."team_name",
    "m"."activity_id",
    "a"."activity_code",
    "a"."activity_name",
    "m"."condition_group",
    "min"("m"."work_date") AS "period_start",
    "max"("m"."work_date") AS "period_end",
    "count"(*) AS "sample_count",
    "count"(DISTINCT "m"."block_id") AS "block_count",
    "sum"("m"."actual_quantity") AS "total_quantity",
    "sum"("m"."area_rai") AS "total_area_rai",
    "sum"("m"."tree_count") AS "total_tree_count",
    "sum"("m"."labor_hours") AS "total_labor_hours",
    "avg"("m"."person_efficiency_pct") AS "person_efficiency_pct",
    "avg"("m"."tree_efficiency_pct") AS "tree_efficiency_pct",
    "avg"("m"."area_efficiency_pct") AS "area_efficiency_pct",
    "avg"("m"."quality_pct") AS "quality_pct",
    "avg"("m"."quality_adjusted_efficiency_pct") AS "quality_adjusted_efficiency_pct",
    "avg"("m"."composite_efficiency_pct") AS "composite_efficiency_pct",
    "avg"("m"."data_quality_pct") AS "data_quality_pct",
    "count"(*) FILTER (WHERE "m"."is_budget_eligible") AS "budget_eligible_count",
    "count"(*) FILTER (WHERE "m"."outlier_flag") AS "outlier_count"
   FROM (("public"."work_performance_metrics" "m"
     LEFT JOIN "public"."teams" "t" ON (("t"."id" = "m"."team_id")))
     JOIN "public"."activities" "a" ON (("a"."id" = "m"."activity_id")))
  WHERE ("m"."metric_scope" = 'result'::"text")
  GROUP BY "m"."team_id", "t"."team_code", "t"."team_name", "m"."activity_id", "a"."activity_code", "a"."activity_name", "m"."condition_group";


--
-- Name: v_user_access_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_user_access_effective" WITH ("security_invoker"='true') AS
 SELECT "pr"."id" AS "profile_id",
    "pr"."employee_id",
    "e"."employee_code",
    "e"."full_name" AS "employee_name",
    "r"."role_key",
    "r"."role_name",
    "uas"."scope_type",
    "uas"."estate_id",
    "uas"."zone_id",
    "uas"."plot_id",
    "uas"."block_id",
    "uas"."status" AS "scope_status"
   FROM (((("public"."profiles" "pr"
     LEFT JOIN "public"."employees" "e" ON (("e"."id" = "pr"."employee_id")))
     LEFT JOIN "public"."profile_roles" "por" ON ((("por"."profile_id" = "pr"."id") AND "por"."is_active")))
     LEFT JOIN "public"."roles" "r" ON (("r"."id" = "por"."role_id")))
     LEFT JOIN "public"."user_access_scopes" "uas" ON ((("uas"."profile_id" = "pr"."id") AND ("uas"."status" = 'active'::"text"))));


--
-- Name: v_web_test_run_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_web_test_run_summary" WITH ("security_invoker"='true') AS
 SELECT "id",
    "run_code",
    "run_name",
    "status",
    "started_at",
    "completed_at",
    "metadata",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."work_orders" "w"
          WHERE ("w"."work_order_no" ~~ ("r"."run_code" || '%'::"text"))), (0)::bigint) AS "work_order_count",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM ("public"."work_results" "wr"
             JOIN "public"."work_orders" "w" ON (("w"."id" = "wr"."work_order_id")))
          WHERE ("w"."work_order_no" ~~ ("r"."run_code" || '%'::"text"))), (0)::bigint) AS "work_result_count",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."payroll_periods" "p"
          WHERE ("p"."period_code" ~~ ("r"."run_code" || '%'::"text"))), (0)::bigint) AS "payroll_period_count"
   FROM "public"."system_test_runs" "r";


--
-- Name: v_web_test_survey_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_web_test_survey_summary" WITH ("security_invoker"='true') AS
 SELECT "tr"."run_code",
    "tr"."status" AS "run_status",
    "tr"."started_at",
    "tr"."completed_at",
    "count"(DISTINCT "t"."id") AS "template_count",
    "count"(DISTINCT "q"."id") AS "question_count",
    "count"(DISTINCT "r"."id") AS "response_count",
    "count"(DISTINCT "a"."id") AS "answer_count",
    "count"(DISTINCT "ra"."id") AS "attachment_count",
    "count"(DISTINCT "f"."id") AS "finding_count",
    "round"("avg"("r"."score_pct") FILTER (WHERE ("r"."status" = ANY (ARRAY['submitted'::"text", 'verified'::"text", 'closed'::"text"]))), 2) AS "average_score_pct",
    "count"(DISTINCT "r"."id") FILTER (WHERE ("r"."pass_status" = 'passed'::"text")) AS "passed_count",
    "count"(DISTINCT "r"."id") FILTER (WHERE ("r"."pass_status" = 'warning'::"text")) AS "warning_count",
    "count"(DISTINCT "r"."id") FILTER (WHERE ("r"."pass_status" = 'failed'::"text")) AS "failed_count",
    "count"(DISTINCT "f"."id") FILTER (WHERE ("f"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"]))) AS "open_finding_count"
   FROM (((((("public"."system_test_runs" "tr"
     LEFT JOIN "public"."survey_templates" "t" ON (("t"."template_code" ~~ ("tr"."run_code" || '%'::"text"))))
     LEFT JOIN "public"."survey_questions" "q" ON (("q"."template_id" = "t"."id")))
     LEFT JOIN "public"."survey_responses" "r" ON (("r"."template_id" = "t"."id")))
     LEFT JOIN "public"."survey_answers" "a" ON (("a"."response_id" = "r"."id")))
     LEFT JOIN "public"."survey_response_attachments" "ra" ON (("ra"."response_id" = "r"."id")))
     LEFT JOIN "public"."survey_findings" "f" ON (("f"."response_id" = "r"."id")))
  GROUP BY "tr"."run_code", "tr"."status", "tr"."started_at", "tr"."completed_at";


--
-- Name: v_work_order_workforce; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_work_order_workforce" WITH ("security_invoker"='true') AS
 SELECT "wo"."id" AS "work_order_id",
    "wo"."work_order_no",
    "wo"."scheduled_date",
    "wo"."status" AS "work_order_status",
    "a"."activity_code",
    "a"."activity_name",
    "b"."block_name" AS "terrain_code",
    "wo"."manager_employee_id",
    "me"."full_name" AS "manager_name",
    "wo"."supervisor_employee_id",
    "se"."full_name" AS "supervisor_name",
    "wo"."team_id",
    "t"."team_code",
    "t"."team_name",
    "count"(DISTINCT "wow"."employee_id") AS "planned_worker_count",
    "count"(DISTINCT "wrw"."employee_id") AS "actual_worker_count",
    COALESCE("sum"("wrw"."earning_amount"), (0)::numeric) AS "actual_worker_earning"
   FROM (((((((("public"."work_orders" "wo"
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "wo"."block_id")))
     LEFT JOIN "public"."employees" "me" ON (("me"."id" = "wo"."manager_employee_id")))
     LEFT JOIN "public"."employees" "se" ON (("se"."id" = "wo"."supervisor_employee_id")))
     LEFT JOIN "public"."teams" "t" ON (("t"."id" = "wo"."team_id")))
     LEFT JOIN "public"."work_order_workers" "wow" ON (("wow"."work_order_id" = "wo"."id")))
     LEFT JOIN "public"."work_results" "wr" ON (("wr"."work_order_id" = "wo"."id")))
     LEFT JOIN "public"."work_result_workers" "wrw" ON (("wrw"."work_result_id" = "wr"."id")))
  GROUP BY "wo"."id", "wo"."work_order_no", "wo"."scheduled_date", "wo"."status", "a"."activity_code", "a"."activity_name", "b"."block_name", "wo"."manager_employee_id", "me"."full_name", "wo"."supervisor_employee_id", "se"."full_name", "wo"."team_id", "t"."team_code", "t"."team_name";


--
-- Name: v_work_result_weight_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_work_result_weight_summary" WITH ("security_invoker"='true') AS
 SELECT "wr"."id" AS "work_result_id",
    "wr"."result_no",
    "wr"."result_date",
    "wo"."work_order_no",
    "a"."activity_code",
    "a"."activity_name",
    "b"."block_name" AS "terrain_code",
    "wr"."result_status",
    "wr"."source_type",
    "wr"."actual_quantity",
    "wr"."actual_unit",
    "count"("wrwt"."id") FILTER (WHERE ("wrwt"."link_status" <> 'cancelled'::"text")) AS "weigh_ticket_count",
    COALESCE("sum"("wrwt"."allocated_weight_kg") FILTER (WHERE ("wrwt"."link_status" <> 'cancelled'::"text")), (0)::numeric) AS "allocated_weight_kg"
   FROM (((("public"."work_results" "wr"
     LEFT JOIN "public"."work_orders" "wo" ON (("wo"."id" = "wr"."work_order_id")))
     LEFT JOIN "public"."activities" "a" ON (("a"."id" = "wo"."activity_id")))
     LEFT JOIN "public"."blocks" "b" ON (("b"."id" = "wo"."block_id")))
     LEFT JOIN "public"."work_result_weight_tickets" "wrwt" ON (("wrwt"."work_result_id" = "wr"."id")))
  GROUP BY "wr"."id", "wr"."result_no", "wr"."result_date", "wo"."work_order_no", "a"."activity_code", "a"."activity_name", "b"."block_name", "wr"."result_status", "wr"."source_type", "wr"."actual_quantity", "wr"."actual_unit";


