    "approved_by_profile_id" "uuid",
    "approved_at" timestamp with time zone,
    "applied_at" timestamp with time zone,
    "photo_url" "text",
    "reason" "text",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vehicle_fuel_measurements_liter_chk" CHECK (("measured_liter" >= (0)::numeric)),
    CONSTRAINT "vehicle_fuel_measurements_percent_chk" CHECK ((("tank_percent" IS NULL) OR (("tank_percent" >= (0)::numeric) AND ("tank_percent" <= (100)::numeric))))
);


