--
-- Name: v_budget_rate_rule_set_summary _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."v_budget_rate_rule_set_summary" WITH ("security_invoker"='true') AS
 SELECT "rs"."id" AS "rule_set_id",
    "rs"."budget_year_id",
    "rs"."fiscal_year",
    "rs"."rule_set_code",
    "rs"."rule_set_name",
    "rs"."status",
    "count"(DISTINCT "r"."id") AS "rule_count",
    "count"(DISTINCT "m"."block_id") AS "matched_block_count",
    "count"(DISTINCT "s"."id") AS "snapshot_count",
    "count"(DISTINCT "c"."block_id") AS "conflict_block_count",
    "count"(DISTINCT "r"."id") FILTER (WHERE "r"."needs_mapping") AS "rules_needing_mapping",
    "max"("s"."snapshot_at") AS "last_snapshot_at"
   FROM (((("public"."budget_rate_rule_sets" "rs"
     LEFT JOIN "public"."budget_rate_rules" "r" ON (("r"."rule_set_id" = "rs"."id")))
     LEFT JOIN "public"."v_budget_rate_rule_resolution" "m" ON (("m"."rule_set_id" = "rs"."id")))
     LEFT JOIN "public"."budget_rate_block_snapshots" "s" ON (("s"."rule_set_id" = "rs"."id")))
     LEFT JOIN "public"."v_budget_rate_rule_conflicts" "c" ON (("c"."rule_set_id" = "rs"."id")))
  GROUP BY "rs"."id";


--
-- Name: v_survey_template_readiness _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."v_survey_template_readiness" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."template_code",
    "t"."template_base_code",
    "t"."version_no",
    "t"."template_name",
    "t"."survey_scope",
    "t"."survey_category",
    "t"."status",
    "t"."minimum_pass_pct",
    "t"."allow_attachments",
    "t"."effective_from",
    "t"."effective_to",
    "count"("q"."id") AS "question_count",
    "count"("q"."id") FILTER (WHERE "q"."required") AS "required_question_count",
    "count"("q"."id") FILTER (WHERE "q"."is_scored") AS "scored_question_count",
    "round"("sum"("q"."weight_pct") FILTER (WHERE "q"."is_scored"), 2) AS "total_weight_pct",
    "count"("a"."id") AS "assignment_count",
        CASE
            WHEN ("count"("q"."id") = 0) THEN 'no_questions'::"text"
            WHEN (("count"("q"."id") FILTER (WHERE "q"."is_scored") > 0) AND (COALESCE("sum"("q"."weight_pct") FILTER (WHERE "q"."is_scored"), (0)::numeric) = (0)::numeric)) THEN 'missing_weights'::"text"
            ELSE 'ready'::"text"
        END AS "readiness_status"
   FROM (("public"."survey_templates" "t"
     LEFT JOIN "public"."survey_questions" "q" ON ((("q"."template_id" = "t"."id") AND ("q"."status" = 'active'::"text"))))
     LEFT JOIN "public"."survey_template_assignments" "a" ON ((("a"."template_id" = "t"."id") AND ("a"."status" = 'active'::"text"))))
  GROUP BY "t"."id";


